// Content for What Makes Me, Me (node g07, ages 6-9, Chapter 2): reworked to GDD 07 v2 (mechanic-embodying).
// "Who I am is mine." The BASE of the gender thread (UNESCO 3.1): 82 researched, India-grounded scenarios
// across six categories, each re-encoded to one of the shared v2 play actions (reflect / role-play /
// strike-rewrite / branch / sort / match / build): no binary "tap the right card", led by the me-collage
// BUILD ("the one and only you", many parts → one me) + the gentle sex-vs-gender explainer (the body you're
// born with vs who you know you are inside). Many-ways-to-be is anchored in INDIA's own hijra heritage and
// the Supreme Court's NALSA (2014) third-gender recognition: homegrown, not imported. Respect is the floor
// for EVERY family (use the name given, don't tease, include everyone); self-knowledge, never pressure
// ("only you know yourself", "you never have to prove or change"): protecting the gender-diverse child AND
// the majority child. Scope-disciplined: body anatomy stays light here (it lives in g02/g06); this node owns
// the IDEA, not the biology: no medical / romantic / political content. Rendered by the shared engine
// (components/games/v2-engine.tsx). gameId "what-makes-me" (the GDD's "what-makes-me-me" is design-doc only). DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // All my parts
  {"id":"wm-001","cat":"parts-of-me","type":"build","hook":"Lensy: let's build the one and only YOU. What goes in?","prompt":"Drag the parts that make you, you, into your collage.","pieces":["my name","what I love","my feelings","my family","my body","who I am inside"],"mode":"assemble","key":["my name","what I love","my feelings","my family","my body","who I am inside"],"relearn":"Lots of things together make you, you, and your gender is one part among many.","persona":"any","source":"self-concept"},
  {"id":"wm-002","cat":"parts-of-me","type":"reflect","hook":"Lensy: which part of you feels most 'you' today?","prompt":"Point to one (or say your own).","options":["What I love doing","My family","How I make people laugh","Who I am inside"],"affirm":"All of those are part of the one-of-a-kind you. Lovely.","relearn":"You're made of many parts, and you get to notice them.","persona":"any","source":"self-concept"},
  {"id":"wm-003","cat":"parts-of-me","type":"match","hook":"Match each part of you to where it lives.","pairs":[{"left":"My name","right":"What people call me"},{"left":"My feelings","right":"Inside my heart"},{"left":"Who I am","right":"Something only I know best"},{"left":"What I love","right":"The things I pick to do"},{"left":"My family","right":"The people I belong with"}],"relearn":"Different parts of you live in different places, and all are yours.","persona":"any","source":"self-concept"},
  {"id":"wm-004","cat":"parts-of-me","type":"reflect","hook":"Lensy: is there anyone exactly like you in the world?","prompt":"What do you think?","options":["No, I'm one of a kind","Nobody's just like me","I'm unique"],"affirm":"Nobody else is exactly you, that's pretty amazing.","relearn":"You are one of a kind; nobody else is just like you.","persona":"any","source":"uniqueness"},
  {"id":"wm-005","cat":"parts-of-me","type":"build","hook":"Add 'who I am inside' to your collage.","prompt":"Place it among your other parts (one of many).","pieces":["I'm a boy / a girl / me","plus all my other parts"],"mode":"assemble","key":["I'm a boy / a girl / me","plus all my other parts"],"relearn":"Who you are (your gender) is one important part of you, among many.","persona":"gender thread","source":"identity facets"},
  {"id":"wm-006","cat":"parts-of-me","type":"sort","hook":"Sort: a part of who I am, or just a thing I own?","items":[{"id":"a","text":"My feelings"},{"id":"b","text":"My shoe brand"},{"id":"c","text":"What I love doing"},{"id":"d","text":"My family"},{"id":"e","text":"The price of my bag"},{"id":"f","text":"How kind I am"}],"bins":[{"id":"me","label":"Part of me","valence":"neutral"},{"id":"no","label":"Just a thing","valence":"neutral"}],"key":{"a":"me","b":"no","c":"me","d":"me","e":"no","f":"me"},"relearn":"Your feelings, loves, family and kindness are real parts of you.","persona":"any","source":"self-concept"},
  {"id":"wm-007","cat":"parts-of-me","type":"reflect","hook":"Lensy: it's okay to still be figuring yourself out. Agree?","prompt":"What do you think?","options":["Yes","I'm still discovering me","That's okay"],"affirm":"You're still discovering who you are, and that's exactly right.","relearn":"You're still discovering you, and that's okay.","persona":"any","source":"identity exploration"},
  {"id":"wm-008","cat":"parts-of-me","type":"match","hook":"Match the kid to a part they're proud of.","pairs":[{"left":"Loves cricket","right":"A favourite game"},{"left":"Great at drawing","right":"A skill they grew"},{"left":"Very kind","right":"A way they treat people"},{"left":"Tells funny jokes","right":"How they make friends laugh"},{"left":"Speaks two tongues","right":"Words from their home"}],"relearn":"The things you love and do are proud parts of you.","persona":"any","source":"self-concept"},
  {"id":"wm-009","cat":"parts-of-me","type":"sort","hook":"Sort the parts of you into where they live.","items":[{"id":"a","text":"My arms and legs"},{"id":"b","text":"My feelings"},{"id":"c","text":"My height"},{"id":"d","text":"Who I know I am"},{"id":"e","text":"My curly hair"},{"id":"f","text":"What makes me happy"}],"bins":[{"id":"body","label":"My body (outside)","valence":"neutral"},{"id":"inside","label":"My inside-self","valence":"neutral"}],"key":{"a":"body","b":"inside","c":"body","d":"inside","e":"body","f":"inside"},"relearn":"Your body and who you are inside are both part of you.","persona":"any","source":"self-concept"},
  {"id":"wm-010","cat":"parts-of-me","type":"build","hook":"Finish version one of your collage.","prompt":"Add a frame that says...","pieces":["one of a kind","made of many parts","good as I am"],"mode":"assemble","key":["one of a kind","made of many parts","good as I am"],"relearn":"All your parts together make one special, one-of-a-kind you.","persona":"any","source":"self-concept"},
  {"id":"wm-011","cat":"parts-of-me","type":"role-play","hook":"A new friend asks \"what are you like?\"","setup":"Tell them about you. Say:","yourLine":[{"text":"\"I'm ___, I love ___, and I'm me.\"","best":true},{"text":"\"I'm just like everyone.\""}],"relearn":"You can describe yourself by your many parts, in your own words.","persona":"any","source":"self-expression / voice"},
  {"id":"wm-012","cat":"parts-of-me","type":"reflect","hook":"Lensy: all your parts add up to one special you. How's that feel?","prompt":"Pick one.","options":["Good","Cool","I like being me"],"affirm":"All your parts together make one special you. Carry that.","relearn":"You're a wonderful whole, made of many parts.","persona":"any","source":"self-concept"},

  // Body & inside-me
  {"id":"wm-013","cat":"sex-and-gender","type":"match","hook":"Two words to learn. Match them.","pairs":[{"left":"Sex","right":"The body you're born with"},{"left":"Gender","right":"Who you know you are inside"},{"left":"Respect","right":"Letting people be themselves"},{"left":"Inside-self","right":"The you only you know best"},{"left":"Name","right":"What people kindly call you"}],"relearn":"Sex is the body you're born with; gender is who you know you are inside.","persona":"educator","source":"UNESCO 3.1"},
  {"id":"wm-014","cat":"sex-and-gender","type":"branch","hook":"One friend's body and inside-self match; another's differ.","options":[{"text":"Say \"both of you are okay, just as you are\"","consequence":"Both feel accepted and safe.","outcome":"kind","best":true},{"text":"Say one of them is 'wrong'","consequence":"A friend is hurt over something that's perfectly okay.","outcome":"unkind"}],"debrief":"For most, body and inside-self match; for some they differ.","relearn":"Body and inside-self match for most, differ for some.","persona":"gender thread","source":"gender development"},
  {"id":"wm-015","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Everyone always feels like the body they were born with.\"","myth":{"un":"Everyone always feels like the body they were born with.","re":"Most do; some people feel different inside, and that's real and okay.","why":"People know their own inside-selves."},"relearn":"Some people feel different inside, and that is real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-016","cat":"sex-and-gender","type":"reflect","hook":"Lensy: gender is about...?","prompt":"Pick the best.","options":["Who you know you are inside","Your true self","How you feel inside"],"affirm":"Yes, gender is who you know yourself to be inside.","relearn":"Gender is who you know you are inside.","persona":"any","source":"UNESCO 3.1"},
  {"id":"wm-017","cat":"sex-and-gender","type":"sort","hook":"A grown-up says 'it's a girl!' by looking. Sort what each thing is about.","items":[{"id":"a","text":"Looking at the body"},{"id":"b","text":"Knowing your inside-self"},{"id":"c","text":"The parts you're born with"},{"id":"d","text":"Who you grow to know"},{"id":"e","text":"What a first glance sees"},{"id":"f","text":"A feeling that's yours"}],"bins":[{"id":"sex","label":"About the body (sex)","valence":"neutral"},{"id":"gender","label":"About inside-self (gender)","valence":"neutral"}],"key":{"a":"sex","b":"gender","c":"sex","d":"gender","e":"sex","f":"gender"},"relearn":"A first guess is about the body; gender is who you grow to know.","persona":"educator","source":"sex vs gender"},
  {"id":"wm-018","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"You can tell someone's gender by how they look.\"","myth":{"un":"You can tell someone's gender by their hair or clothes.","re":"You can't; gender is who someone knows they are inside.","why":"Looks don't reveal an inside-self."},"relearn":"You can't know someone's gender from how they look.","persona":"any","source":"gender vs expression"},
  {"id":"wm-019","cat":"sex-and-gender","type":"reflect","hook":"Lensy: who knows your inside-self best?","prompt":"What do you think?","options":["Me","Only I do","I know myself best"],"affirm":"Only you know who you are inside. That's yours.","relearn":"Only you know who you are inside.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-020","cat":"sex-and-gender","type":"role-play","hook":"You're not sure if a new classmate is a boy or a girl.","setup":"What's the kind thing to do? Say:","yourLine":[{"text":"\"Hi! What's your name?\" (and use it)","best":true},{"text":"\"Are you a boy or a girl?\" (loudly)"}],"relearn":"Let people tell you; use the name they give you.","persona":"respect","source":"respect / voice"},
  {"id":"wm-021","cat":"sex-and-gender","type":"match","hook":"Match each kid to 'okay'. (Trick: all of them are!)","pairs":[{"left":"Feels like the boy he was called","right":"Okay and common"},{"left":"Feels like the girl she was called","right":"Also common"},{"left":"Feels like a different gender","right":"Okay and real"},{"left":"Feels like neither or both","right":"Okay as well"},{"left":"Still figuring it out","right":"That's fine too"}],"relearn":"Feeling like the boy or girl you were called is common; feeling different is okay too.","persona":"gender thread","source":"gender development"},
  {"id":"wm-022","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"If you feel like a different gender, something's wrong.\"","myth":{"un":"Feeling like a different gender means something's wrong.","re":"Some kids feel like a different gender, and that's okay too.","why":"It's a normal part of how people are."},"relearn":"Feeling like a different gender is okay too.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-023","cat":"sex-and-gender","type":"match","hook":"Match each word to a simple meaning.","pairs":[{"left":"Sex","right":"Body parts you're born with"},{"left":"Gender","right":"The you, you know inside"},{"left":"Respect","right":"Letting people be themselves"},{"left":"Inside-self","right":"What only you can know"},{"left":"Kind","right":"Using the name someone gives"}],"relearn":"Knowing these words helps us understand ourselves and others.","persona":"educator","source":"body literacy"},
  {"id":"wm-024","cat":"sex-and-gender","type":"reflect","hook":"Lensy: who someone is inside is precious. Worth respecting?","prompt":"What do you think?","options":["Yes","Always","Definitely"],"affirm":"Yes, who someone is inside deserves respect.","relearn":"Who someone is inside deserves respect.","persona":"respect","source":"respect"},

  // Not what you like
  {"id":"wm-025","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy's favourite colour is pink.","myth":{"un":"Liking pink means a boy isn't really a boy.","re":"Liking a colour doesn't change who you are.","why":"Pink is just a colour."},"relearn":"What you like doesn't change who you are inside.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-026","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl has short hair and loves football.","myth":{"un":"Short hair and football mean she isn't really a girl.","re":"What she likes doesn't change that she's a girl.","why":"Hair and hobbies aren't a gender."},"relearn":"What you like doesn't change who you are.","persona":"Ananya","source":"gender vs expression"},
  {"id":"wm-027","cat":"not-what-you-like","type":"sort","hook":"Sort: does this decide your gender, or is it just something you like?","items":[{"id":"a","text":"Liking dolls"},{"id":"b","text":"Who you know you are inside"},{"id":"c","text":"Your haircut"},{"id":"d","text":"The clothes you wear"},{"id":"e","text":"Your favourite colour"},{"id":"f","text":"The games you play"}],"bins":[{"id":"gender","label":"Decides gender","valence":"neutral"},{"id":"like","label":"Just what you like","valence":"neutral"}],"key":{"a":"like","b":"gender","c":"like","d":"like","e":"like","f":"like"},"relearn":"Only who you know you are inside is your gender; the rest is just what you like.","persona":"gender thread","source":"UNESCO 3.1"},
  {"id":"wm-028","cat":"not-what-you-like","type":"branch","hook":"A boy enjoys playing with dolls and a kid says \"that makes you a girl.\"","options":[{"text":"Say \"toys don't decide who I am\"","consequence":"He keeps playing happily; the myth loses.","outcome":"assertive","best":true},{"text":"Stop playing to avoid teasing","consequence":"He gives up fun over a wrong idea.","outcome":"missed"}],"debrief":"Toys don't decide your gender; he's still a boy.","relearn":"Toys don't decide your gender.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-029","cat":"not-what-you-like","type":"strike-rewrite","hook":"\"Crying makes a boy a girl.\"","myth":{"un":"Crying makes a boy a girl.","re":"Everyone cries; feelings aren't a gender.","why":"Tears are for every kid (see Feelings Friends)."},"relearn":"Feelings aren't a gender; everyone cries.","persona":"Faizan-type","source":"links g01"},
  {"id":"wm-030","cat":"not-what-you-like","type":"role-play","hook":"Someone teases a boy for dancing.","setup":"Back him up. Say:","yourLine":[{"text":"\"Dancing's great, and he's still exactly who he is.\"","best":true},{"text":"Laugh along"}],"relearn":"Dancing (or anything you love) doesn't change who you are.","persona":"Faizan-type","source":"gender vs expression / voice"},
  {"id":"wm-031","cat":"not-what-you-like","type":"strike-rewrite","hook":"\"The clothes you wear decide who you are inside.\"","myth":{"un":"Clothes decide who you are inside.","re":"Clothes are just clothes; they don't decide your inside-self.","why":"A kurta or a frock is an outfit, not an identity."},"relearn":"Clothes don't decide who you are inside.","persona":"any","source":"gender vs expression"},
  {"id":"wm-032","cat":"not-what-you-like","type":"sort","hook":"Sort: is it just hair, or is it your gender?","items":[{"id":"a","text":"Long hair"},{"id":"b","text":"Short hair"},{"id":"c","text":"A bun"},{"id":"d","text":"Who you know you are"},{"id":"e","text":"A ponytail"},{"id":"f","text":"A shaved head"}],"bins":[{"id":"hair","label":"Just hair","valence":"neutral"},{"id":"gender","label":"Your gender","valence":"neutral"}],"key":{"a":"hair","b":"hair","c":"hair","d":"gender","e":"hair","f":"hair"},"relearn":"Long or short, hair is just hair, not a gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-033","cat":"not-what-you-like","type":"reflect","hook":"Lensy: can you like 'boy things' AND 'girl things'?","prompt":"What do you think?","options":["Yes, they're just things","Of course","Things have no gender"],"affirm":"Yes, you can like anything; they're just things, not rules.","relearn":"You can like anything; they're just things.","persona":"any","source":"gender vs expression"},
  {"id":"wm-034","cat":"not-what-you-like","type":"strike-rewrite","hook":"\"Playing a different game changes your gender.\"","myth":{"un":"Playing a different game can change your gender.","re":"Nothing you play or wear changes who you are inside.","why":"Your inside-self is steady."},"relearn":"Nothing you play or wear changes who you are inside.","persona":"any","source":"gender stability"},
  {"id":"wm-035","cat":"not-what-you-like","type":"branch","hook":"Friends say you can't like a thing because of your gender.","options":[{"text":"Say \"I can like what I like\"","consequence":"You keep what you love; others often agree.","outcome":"assertive","best":true},{"text":"Drop it to fit in","consequence":"You give up something you enjoy for a silly rule.","outcome":"missed"}],"debrief":"What you enjoy is yours; gender doesn't decide it.","relearn":"You can like what you like, whatever your gender.","persona":"Reyansh","source":"peer norms"},
  {"id":"wm-036","cat":"not-what-you-like","type":"reflect","hook":"Lensy: your gender is...?","prompt":"Finish it.","options":["who I am inside","not what I like or wear","mine to know"],"affirm":"Your gender is who you are inside, not what you like or wear.","relearn":"Gender is who you are inside, not what you like or wear.","persona":"gender thread","source":"UNESCO 3.1"},

  // Many ways to be
  {"id":"wm-037","cat":"many-ways","type":"strike-rewrite","hook":"\"There are only two kinds of people and everyone must fit.\"","myth":{"un":"There are only two kinds of people and everyone must fit.","re":"Boy, girl, and some feel like neither or both, all real.","why":"People are wonderfully varied."},"relearn":"Boy, girl, and some people feel like neither or both, all real.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-038","cat":"many-ways","type":"reflect","hook":"Lensy: in India, people beyond just 'boy' and 'girl' have been part of life for a very long time. Did you know?","prompt":"What do you think?","options":["I do now!","That's interesting","Cool, our own history"],"affirm":"Yes, India has known people beyond boy and girl for a very long time.","relearn":"India has known people beyond boy and girl for a very long time.","persona":"India","source":"hijra history"},
  {"id":"wm-039","cat":"many-ways","type":"strike-rewrite","hook":"\"India's law only recognises male and female.\"","myth":{"un":"India only recognises male and female.","re":"India's law recognises a third gender, not only male and female.","why":"The Supreme Court recognised it (NALSA, 2014)."},"relearn":"India's law recognises a third gender.","persona":"India","source":"NALSA 2014"},
  {"id":"wm-040","cat":"many-ways","type":"match","hook":"Match each way of being to 'real and okay'. (Trick: all are!)","pairs":[{"left":"A boy","right":"Real and okay"},{"left":"A girl","right":"A wonderful way to be"},{"left":"Someone who feels like neither","right":"True and fine"},{"left":"Someone who feels like both","right":"Welcome here too"},{"left":"Someone who uses 'they'","right":"Easy to respect"}],"relearn":"Being a boy, a girl, or something else, all okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-041","cat":"many-ways","type":"role-play","hook":"Someone uses 'they' for themselves.","setup":"Use it kindly. Say:","yourLine":[{"text":"\"Okay! I'll use 'they' for you.\"","best":true},{"text":"\"That's too weird.\""}],"relearn":"Some people use 'they'; using it for them is kind and easy.","persona":"respect","source":"respect / voice"},
  {"id":"wm-042","cat":"many-ways","type":"strike-rewrite","hook":"\"There's only one right way to be a boy.\"","myth":{"un":"There's only one right way to be a boy.","re":"There are many ways to be a boy, quiet, loud, sporty, arty.","why":"Boys are as varied as all people."},"relearn":"There are many ways to be a boy.","persona":"Faizan-type","source":"gender norms"},
  {"id":"wm-043","cat":"many-ways","type":"strike-rewrite","hook":"\"There's only one right way to be a girl.\"","myth":{"un":"There's only one right way to be a girl.","re":"There are many ways to be a girl, bold, gentle, sporty, bookish.","why":"Girls are as varied as all people."},"relearn":"There are many ways to be a girl.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-044","cat":"many-ways","type":"reflect","hook":"Lensy: a child who feels like a different gender than their body, real and okay?","prompt":"What do you think?","options":["Yes","Real and okay","They're just being themselves"],"affirm":"Yes, a child who feels like a different gender is real and okay.","relearn":"A child who feels like a different gender is real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-045","cat":"many-ways","type":"sort","hook":"Sort: true about people, or a too-tight box?","items":[{"id":"a","text":"People are wonderfully varied"},{"id":"b","text":"Everyone fits two neat boxes"},{"id":"c","text":"There are many ways to be"},{"id":"d","text":"Everyone must be the same"},{"id":"e","text":"Some feel like neither or both"},{"id":"f","text":"Only two kinds exist anywhere"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"box","label":"Too-tight box","valence":"neg"}],"key":{"a":"true","b":"box","c":"true","d":"box","e":"true","f":"box"},"relearn":"People don't fit neat boxes; we're wonderfully varied.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-046","cat":"many-ways","type":"reflect","hook":"Lensy: meeting someone different from you, what's that like?","prompt":"What do you think?","options":["Interesting","I learn something","Good"],"affirm":"Meeting people different from you makes the world interesting.","relearn":"Meeting different people makes the world interesting.","persona":"any","source":"diversity"},
  {"id":"wm-047","cat":"many-ways","type":"strike-rewrite","hook":"\"Some people are 'made wrong'.\"","myth":{"un":"Some people are 'made wrong' for being who they are.","re":"No one is made wrong for being who they are.","why":"Every person deserves dignity."},"relearn":"No one is 'made wrong' for being who they are.","persona":"respect","source":"dignity"},
  {"id":"wm-048","cat":"many-ways","type":"match","hook":"Match each fact to where it comes from. (All India's own!)","pairs":[{"left":"Hijra community","right":"Long part of our history"},{"left":"Third gender in law","right":"India's Supreme Court"},{"left":"Many ways to be","right":"True of people everywhere"},{"left":"Wedding blessings","right":"An old Indian custom"},{"left":"More than two","right":"Part of our own stories"}],"relearn":"'More than two' is part of India's own history and law.","persona":"India","source":"hijra history / NALSA"},
  {"id":"wm-049","cat":"many-ways","type":"role-play","hook":"You feel sure you're a boy/girl, and you meet someone who feels different.","setup":"Say the both-at-once line:","yourLine":[{"text":"\"I know who I am, and I respect who you are.\"","best":true},{"text":"\"You should be like me.\""}],"relearn":"You can be sure of yourself and respect others at the same time.","persona":"respect","source":"respect / voice"},
  {"id":"wm-050","cat":"many-ways","type":"sort","hook":"Sort: deserves kindness? (Trick: everyone does.)","items":[{"id":"a","text":"A boy"},{"id":"b","text":"A girl"},{"id":"c","text":"Someone who feels different"},{"id":"d","text":"Everyone"},{"id":"e","text":"Someone who uses 'they'"},{"id":"f","text":"A new kid you just met"}],"bins":[{"id":"yes","label":"Deserves kindness","valence":"pos"},{"id":"all","label":"Yes, every single one","valence":"pos"}],"key":{"a":"yes","b":"yes","c":"all","d":"all","e":"yes","f":"all"},"relearn":"Every way of being a person deserves kindness.","persona":"respect","source":"dignity"},
  {"id":"wm-082","cat":"many-ways","type":"reflect","hook":"Lensy looks around at the whole class of collages.","prompt":"Is every kid a different, wonderful 'me'?","options":["Yes","Every one","We're all different and good"],"affirm":"Every single kid is a different, wonderful 'me'.","relearn":"Every single kid is a different, wonderful 'me'.","persona":"any","source":"diversity"},

  // Respect everyone
  {"id":"wm-051","cat":"respect-me","type":"role-play","hook":"A new friend says \"my name is Aarav, I'm a boy.\"","setup":"Show respect. Say:","yourLine":[{"text":"\"Hi Aarav! Want to play?\"","best":true},{"text":"Use a different name anyway"}],"relearn":"Call people the name they give you; it shows respect.","persona":"respect","source":"respect / voice"},
  {"id":"wm-052","cat":"respect-me","type":"branch","hook":"A classmate is teased for being 'too girly'.","options":[{"text":"Say \"leave them alone, that's not kind\"","consequence":"The teasing often stops when someone steps in.","outcome":"ally","best":true},{"text":"Join in so you fit in","consequence":"They feel alone and hurt.","outcome":"bystander"}],"debrief":"Teasing someone for who they are isn't kind; you can step in.","relearn":"You can stand up when someone's teased for who they are.","persona":"Faizan-type","source":"bystander"},
  {"id":"wm-053","cat":"respect-me","type":"role-play","hook":"You accidentally call someone the wrong name.","setup":"Make it right. Say:","yourLine":[{"text":"\"Sorry! [right name]. I'll get it.\"","best":true},{"text":"Keep using the wrong one"}],"relearn":"Mistakes happen; say sorry and try again. That's kind.","persona":"respect","source":"repair / voice"},
  {"id":"wm-054","cat":"respect-me","type":"strike-rewrite","hook":"\"Using the wrong name on purpose is just a joke.\"","myth":{"un":"Using the wrong name on purpose to be mean is just a joke.","re":"Using the wrong name on purpose to hurt isn't kind.","why":"Names matter to people."},"relearn":"Using the wrong name on purpose to hurt isn't kind.","persona":"respect","source":"respect"},
  {"id":"wm-055","cat":"respect-me","type":"branch","hook":"A kid says \"you can't play, you're a girl.\"","options":[{"text":"Say \"that's not fair, anyone can play\"","consequence":"The game opens up; it's fairer and more fun.","outcome":"fair","best":true},{"text":"Let it slide","consequence":"Someone's left out for no good reason.","outcome":"unfair"}],"debrief":"Leaving someone out for their gender isn't fair.","relearn":"No one should be left out for their gender.","persona":"Ananya","source":"fairness"},
  {"id":"wm-056","cat":"respect-me","type":"role-play","hook":"A friend likes things people call 'for the other gender'.","setup":"Be a good friend. Say:","yourLine":[{"text":"\"Cool, want to play it together?\"","best":true},{"text":"\"That's weird, stop.\""}],"relearn":"What a friend likes doesn't change your friendship.","persona":"any","source":"friendship / voice"},
  {"id":"wm-057","cat":"respect-me","type":"sort","hook":"Sort: respectful, or not?","items":[{"id":"a","text":"Using the name someone gives"},{"id":"b","text":"Teasing how someone looks"},{"id":"c","text":"Including everyone"},{"id":"d","text":"Copying an unkind word"},{"id":"e","text":"Saying sorry for a mistake"},{"id":"f","text":"Leaving someone out on purpose"}],"bins":[{"id":"yes","label":"Respectful","valence":"pos"},{"id":"no","label":"Not respectful","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"Respect is using people's names, including them, saying sorry, and not copying unkind words.","persona":"respect","source":"respect"},
  {"id":"wm-058","cat":"respect-me","type":"reflect","hook":"Lensy: the golden rule. How should you treat others' 'me'?","prompt":"Pick the best.","options":["The way I'd want mine treated","With kindness","With respect"],"affirm":"Treat others' who-they-are the way you'd want yours treated.","relearn":"Treat others' 'me' the way you'd want yours treated.","persona":"respect","source":"golden rule"},
  {"id":"wm-059","cat":"respect-me","type":"branch","hook":"An older person uses an unkind word for someone different.","options":[{"text":"Choose kindness; don't copy the word","consequence":"You stay kind even when others aren't.","outcome":"values","best":true},{"text":"Copy it to fit in","consequence":"An unkind word spreads through you.","outcome":"missed"}],"debrief":"You don't have to copy unkind words; you can choose kindness.","relearn":"You can choose kindness even if a grown-up doesn't.","persona":"ally seed","source":"values"},
  {"id":"wm-060","cat":"respect-me","type":"role-play","hook":"Someone different from you wants to join the game.","setup":"Welcome them. Say:","yourLine":[{"text":"\"Come join us!\"","best":true},{"text":"\"This game's not for you.\""}],"relearn":"Including everyone, whoever they are, is kind.","persona":"any","source":"inclusion / voice"},
  {"id":"wm-061","cat":"respect-me","type":"branch","hook":"You meet someone whose way of being is new to you.","options":[{"text":"Be friendly and respectful anyway","consequence":"You make a new friend and learn something.","outcome":"kind","best":true},{"text":"Treat them as 'weird'","consequence":"You miss a friend and make them feel small.","outcome":"unkind"}],"debrief":"Even if it's new to you, every person deserves respect.","relearn":"Even if it's new to you, every person deserves respect.","persona":"respect","source":"respect"},
  {"id":"wm-062","cat":"respect-me","type":"branch","hook":"You're unsure how to treat someone you've just met.","options":[{"text":"Ask kindly and listen","consequence":"You learn who they are; they feel respected.","outcome":"kind","best":true},{"text":"Guess and tease","consequence":"You could hurt someone you've just met.","outcome":"unkind"}],"debrief":"Asking kindly and listening beats guessing or teasing.","relearn":"Asking kindly and listening shows respect.","persona":"respect","source":"respect"},
  {"id":"wm-063","cat":"respect-me","type":"strike-rewrite","hook":"\"Respect means making people be like me.\"","myth":{"un":"Respect means making people be like me.","re":"Respect means letting people be themselves.","why":"We don't all have to be the same."},"relearn":"Respect means letting people be themselves.","persona":"respect","source":"respect"},
  {"id":"wm-064","cat":"respect-me","type":"role-play","hook":"A friend was just teased for who they are.","setup":"Check on them. Say:","yourLine":[{"text":"\"You okay? You're great as you are.\"","best":true},{"text":"Pretend nothing happened"}],"relearn":"A quiet 'you okay?' tells someone they're not alone.","persona":"Faizan-type","source":"support / voice"},
  {"id":"wm-065","cat":"respect-me","type":"sort","hook":"Sort: builds respect, or breaks it?","items":[{"id":"a","text":"Listening to someone"},{"id":"b","text":"Making fun of them"},{"id":"c","text":"Using their name"},{"id":"d","text":"Leaving them out"},{"id":"e","text":"Welcoming a new kid"},{"id":"f","text":"Spreading a mean nickname"}],"bins":[{"id":"build","label":"Builds respect","valence":"pos"},{"id":"break","label":"Breaks it","valence":"neg"}],"key":{"a":"build","b":"break","c":"build","d":"break","e":"build","f":"break"},"relearn":"Listening, using names and welcoming build respect; mocking, excluding and mean nicknames break it.","persona":"respect","source":"respect"},
  {"id":"wm-066","cat":"respect-me","type":"reflect","hook":"Lensy: one kind thing you could do for someone different tomorrow?","prompt":"Plan one.","options":["Use their name","Include them","Stand up for them","Just be friendly"],"affirm":"That's a kind plan. Small respect makes a big difference.","relearn":"You can show respect in small, everyday ways.","persona":"respect","source":"prosocial"},

  // Be yourself
  {"id":"wm-067","cat":"be-yourself","type":"strike-rewrite","hook":"\"You must prove you're a 'real' boy or girl.\"","myth":{"un":"You must prove your gender to others.","re":"You don't have to prove who you are to anyone.","why":"You simply are who you are."},"relearn":"You never have to prove who you are.","persona":"be-yourself","source":"gender norms"},
  {"id":"wm-068","cat":"be-yourself","type":"role-play","hook":"Someone says \"act more like a boy / a girl.\"","setup":"Hold your ground, kindly. Say:","yourLine":[{"text":"\"I'm being myself, and that's okay.\"","best":true},{"text":"Change who I am to please them"}],"relearn":"You don't have to change who you are to please others.","persona":"Faizan-type","source":"gender norms / voice"},
  {"id":"wm-069","cat":"be-yourself","type":"role-play","hook":"You catch yourself wishing you were more like someone else.","setup":"Say the kinder, truer line:","yourLine":[{"text":"\"It's good to be exactly the person I am.\"","best":true},{"text":"\"I should be someone else.\""}],"relearn":"It's good to be exactly the person you are.","persona":"be-yourself","source":"self-esteem / voice"},
  {"id":"wm-070","cat":"be-yourself","type":"branch","hook":"Others push you to be louder/quieter than you are to fit in.","options":[{"text":"Stay true to yourself","consequence":"You feel right; the right friends like the real you.","outcome":"values","best":true},{"text":"Pretend to be someone else","consequence":"It's tiring, and they like a 'you' that isn't you.","outcome":"missed"}],"debrief":"You don't have to change yourself to fit in.","relearn":"Being yourself beats pretending to fit in.","persona":"Reyansh","source":"authenticity"},
  {"id":"wm-071","cat":"be-yourself","type":"reflect","hook":"Lensy: your collage is full of your parts. Proud of them?","prompt":"What do you think?","options":["Yes","Proud","All of me"],"affirm":"You can be proud of all the parts that make you, you.","relearn":"You can be proud of all the parts that make you, you.","persona":"any","source":"self-esteem"},
  {"id":"wm-072","cat":"be-yourself","type":"reflect","hook":"Lensy: who gets to decide who you are inside?","prompt":"Who?","options":["Me","I do","Only me"],"affirm":"You get to know and decide who you are inside.","relearn":"You get to know and decide who you are inside.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-073","cat":"be-yourself","type":"branch","hook":"You feel unsure about a part of yourself.","options":[{"text":"Talk to a trusted grown-up about it","consequence":"You feel less alone; they help.","outcome":"supported","best":true},{"text":"Worry about it all alone","consequence":"The worry grows in silence.","outcome":"missed"}],"debrief":"Feeling unsure is okay; a trusted grown-up can help.","relearn":"It's okay to feel unsure, and to ask a trusted grown-up.","persona":"any","source":"trusted adults"},
  {"id":"wm-074","cat":"be-yourself","type":"role-play","hook":"A friend says 'be yourself' is good advice.","setup":"Agree, and pass it on. Say:","yourLine":[{"text":"\"Yes, you be you, and I'll be me.\"","best":true},{"text":"\"No, copy everyone else.\""}],"relearn":"Being yourself is some of the best advice there is.","persona":"be-yourself","source":"self-esteem / voice"},
  {"id":"wm-075","cat":"be-yourself","type":"strike-rewrite","hook":"\"You have to be like everyone else to be okay.\"","myth":{"un":"You have to be like everyone else to be okay.","re":"You don't have to be like everyone else to be okay.","why":"Different is normal and good."},"relearn":"You don't have to be like everyone else to be okay.","persona":"any","source":"self-esteem"},
  {"id":"wm-076","cat":"be-yourself","type":"reflect","hook":"Lensy: the things that make you different, can they be strengths?","prompt":"What do you think?","options":["Yes","They make me, me","Definitely"],"affirm":"The things that make you different can be your strengths.","relearn":"Your differences can be your strengths.","persona":"any","source":"self-esteem"},
  {"id":"wm-077","cat":"be-yourself","type":"role-play","hook":"A friend feels bad for being different.","setup":"Lift them up. Say:","yourLine":[{"text":"\"You're great just as you are.\"","best":true},{"text":"\"Try to be normal.\""}],"relearn":"Reminding a friend they're great as they are is a gift.","persona":"ally seed","source":"friendship / voice"},
  {"id":"wm-078","cat":"be-yourself","type":"reflect","hook":"Lensy: you'll grow and change. Still you?","prompt":"What do you think?","options":["Yes, still me","I grow and stay me","Of course"],"affirm":"You can grow and change and still be wonderfully you.","relearn":"You can grow and change and still be you.","persona":"any","source":"identity over time"},
  {"id":"wm-079","cat":"be-yourself","type":"branch","hook":"Capstone: a kid is being teased for who they are, and you're nearby.","options":[{"text":"Stand with them and use their name kindly","consequence":"They feel seen and safe; you set the tone.","outcome":"ally","best":true},{"text":"Walk past","consequence":"They feel alone.","outcome":"bystander"}],"debrief":"Standing with someone and using their name is real respect in action.","relearn":"You can put respect into action when it counts.","persona":"Faizan-type","source":"bystander / consolidation"},
  {"id":"wm-080","cat":"be-yourself","type":"build","hook":"Finish your me-collage and read it out.","prompt":"Add your final frame.","pieces":["one of a kind","good as I am","who I am is mine"],"mode":"assemble","key":["one of a kind","good as I am","who I am is mine"],"relearn":"I am one of a kind, and good exactly as I am.","persona":"any","source":"self-esteem"},
  {"id":"wm-081","cat":"be-yourself","type":"reflect","hook":"Lensy: what's your motto from today?","prompt":"Pick one to carry.","options":["Who I am is mine","Many ways to be","Respect everyone's me","I'm good as I am"],"affirm":"Carry that. You're going to be a wonderful, respectful you.","relearn":"Who you are is yours, there are many ways to be, and everyone deserves respect.","persona":"any","source":"consolidation"},
  {"id":"wm-1350","cat":"be-yourself","type":"strike-rewrite","hook":"\"Big kids don't do things their own way.\"","myth":{"un":"You must do things the way everyone else does.","re":"You can do things your own way and still belong.","why":"There's more than one right way to be you."},"relearn":"Your own way of doing things is okay.","persona":"be-yourself","source":"self-esteem"},
  {"id":"wm-1351","cat":"be-yourself","type":"strike-rewrite","hook":"\"Shy kids should pretend to be loud.\"","myth":{"un":"You have to pretend to be loud to be liked.","re":"Quiet is a fine way to be; you don't have to fake loud.","why":"The real you is enough, exactly as you are."},"relearn":"You don't have to fake being someone you're not.","persona":"be-yourself","source":"self-esteem"},
  {"id":"wm-1352","cat":"be-yourself","type":"strike-rewrite","hook":"\"You're too different to fit in anywhere.\"","myth":{"un":"Being different means you don't belong.","re":"Being different is normal, and you still belong.","why":"Every group has room for one-of-a-kind people."},"relearn":"You belong, just as you are.","persona":"any","source":"belonging"},
  {"id":"wm-1353","cat":"be-yourself","type":"strike-rewrite","hook":"\"You should hide the things that make you, you.\"","myth":{"un":"You should hide the parts that make you different.","re":"Your different parts are worth showing, not hiding.","why":"They can be your strengths."},"relearn":"You don't have to hide what makes you, you.","persona":"be-yourself","source":"self-esteem"},
  {"id":"wm-1354","cat":"be-yourself","type":"strike-rewrite","hook":"\"Once people decide who you are, you can't change.\"","myth":{"un":"You can never grow or change who you are.","re":"You can grow and change and still be wonderfully you.","why":"Growing is part of being a person."},"relearn":"You can grow and change and still be you.","persona":"any","source":"identity over time"},
  {"id":"wm-1355","cat":"be-yourself","type":"strike-rewrite","hook":"\"You have to earn the right to be yourself.\"","myth":{"un":"You must prove yourself before you can be you.","re":"You never have to prove who you are to anyone.","why":"You already are who you are."},"relearn":"You never have to prove who you are.","persona":"gender thread","source":"gender norms"},
  {"id":"wm-1356","cat":"be-yourself","type":"strike-rewrite","hook":"\"Carrying a worry alone makes you brave.\"","myth":{"un":"Brave kids keep big worries to themselves.","re":"Telling a trusted grown-up about a worry is brave too.","why":"You don't have to carry worry alone."},"relearn":"Sharing a worry with a trusted grown-up is brave.","persona":"any","source":"trusted adults"},
  {"id":"wm-1357","cat":"be-yourself","type":"role-play","hook":"Cousins say your hobby is 'weird'.","setup":"Stand up for what you love. Say:","yourLine":[{"text":"\"I like it, and that's enough for me.\"","best":true},{"text":"Quietly give up the thing I love"}],"relearn":"You can keep loving what you love.","persona":"be-yourself","source":"self-esteem / voice"},
  {"id":"wm-1358","cat":"be-yourself","type":"role-play","hook":"A friend copies everything you do to fit in.","setup":"Set them free, kindly. Say:","yourLine":[{"text":"\"You don't have to copy me. You're great as you.\"","best":true},{"text":"\"Good, keep copying me.\""}],"relearn":"Each of us can be our own self.","persona":"ally seed","source":"friendship / voice"},
  {"id":"wm-1359","cat":"be-yourself","type":"role-play","hook":"At a family function someone says \"be more grown-up like your brother.\"","setup":"Be yourself, gently. Say:","yourLine":[{"text":"\"I'm my own person, and that's okay.\"","best":true},{"text":"Try to act exactly like my brother"}],"relearn":"You can be your own person.","persona":"be-yourself","source":"family / voice"},
  {"id":"wm-1360","cat":"be-yourself","type":"role-play","hook":"Classmates dare you to mock another kid to seem cool.","setup":"Keep your kindness. Say:","yourLine":[{"text":"\"No thanks. I'm fine being kind.\"","best":true},{"text":"Mock the kid so they'll like me"}],"relearn":"You can stay kind even when others push.","persona":"ally seed","source":"peer pressure / voice"},
  {"id":"wm-1361","cat":"be-yourself","type":"role-play","hook":"Someone laughs at the way you talk.","setup":"Hold steady, kindly. Say:","yourLine":[{"text":"\"This is how I talk, and I like it.\"","best":true},{"text":"Stop talking so no one hears me"}],"relearn":"The way you are is okay.","persona":"Faizan-type","source":"self-esteem / voice"},
  {"id":"wm-1362","cat":"be-yourself","type":"role-play","hook":"A friend says \"everyone's into this game, you have to be too.\"","setup":"Choose for yourself. Say:","yourLine":[{"text":"\"It's okay if I like different things.\"","best":true},{"text":"Pretend to love it so I fit in"}],"relearn":"You can like different things and still belong.","persona":"Reyansh","source":"authenticity / voice"},
  {"id":"wm-1363","cat":"be-yourself","type":"role-play","hook":"You feel proud after drawing something only you would make.","setup":"Say the proud, true line:","yourLine":[{"text":"\"This is so me, and I'm proud of it.\"","best":true},{"text":"\"It's silly, I should hide it.\""}],"relearn":"You can be proud of what makes you, you.","persona":"be-yourself","source":"self-esteem / voice"},
  {"id":"wm-1364","cat":"be-yourself","type":"role-play","hook":"A friend says they wish they were someone else.","setup":"Lift them up. Say:","yourLine":[{"text":"\"I'm glad you're you. The world needs the real you.\"","best":true},{"text":"\"Yeah, be someone else.\""}],"relearn":"Reminding a friend they're enough is a gift.","persona":"ally seed","source":"friendship / voice"},
  {"id":"wm-1365","cat":"be-yourself","type":"role-play","hook":"Older kids say your favourite colour is 'babyish'.","setup":"Keep what you love. Say:","yourLine":[{"text":"\"I love this colour, and that's my choice.\"","best":true},{"text":"Pick a colour I don't even like"}],"relearn":"What you love is your own choice.","persona":"be-yourself","source":"self-esteem / voice"},
  {"id":"wm-1366","cat":"be-yourself","type":"role-play","hook":"A teacher asks the class to share one thing they like about themselves.","setup":"Speak up about you. Say:","yourLine":[{"text":"\"I like that I'm kind and curious.\"","best":true},{"text":"\"There's nothing good about me.\""}],"relearn":"It's good to name what you like about you.","persona":"educator","source":"self-esteem / voice"},
  {"id":"wm-1367","cat":"be-yourself","type":"role-play","hook":"You did something the slow, careful way and it worked.","setup":"Own your way. Say:","yourLine":[{"text":"\"My careful way works for me.\"","best":true},{"text":"\"I'm too slow, I should change.\""}],"relearn":"Your own way of doing things can be just right.","persona":"be-yourself","source":"self-esteem / voice"},
  {"id":"wm-1368","cat":"be-yourself","type":"role-play","hook":"A new friend wants you to drop your old friend to seem cooler.","setup":"Be true to yourself. Say:","yourLine":[{"text":"\"I choose my own friends, thanks.\"","best":true},{"text":"Drop my friend to look cool"}],"relearn":"You get to make your own choices.","persona":"be-yourself","source":"authenticity / voice"},
  {"id":"wm-1369","cat":"be-yourself","type":"role-play","hook":"You feel unsure about something inside and want to talk.","setup":"Reach out. Say:","yourLine":[{"text":"\"Didi, can I tell you something I'm unsure about?\"","best":true},{"text":"Keep it bottled up alone"}],"relearn":"You can ask a trusted grown-up or sibling for help.","persona":"any","source":"trusted adults / voice"},
  {"id":"wm-1370","cat":"be-yourself","type":"role-play","hook":"Someone says \"you've changed since last year, that's bad.\"","setup":"Welcome your growth. Say:","yourLine":[{"text":"\"I've grown, and I'm still me.\"","best":true},{"text":"\"I'll go back to how I was.\""}],"relearn":"You can grow and still be wonderfully you.","persona":"be-yourself","source":"identity over time / voice"},
  {"id":"wm-1371","cat":"be-yourself","type":"branch","hook":"Everyone in class joins a club you don't enjoy.","options":[{"text":"Pick the club you actually like","consequence":"You enjoy it and feel like yourself.","outcome":"values","best":true},{"text":"Join the popular one to fit in","consequence":"You're bored and a bit lonely there.","outcome":"missed"}],"debrief":"Choosing what's true to you feels right.","relearn":"You can choose what's true to you.","persona":"Ananya","source":"authenticity"},
  {"id":"wm-1372","cat":"be-yourself","type":"branch","hook":"A part of yourself feels confusing and you don't know who to tell.","options":[{"text":"Tell a teacher or your sister","consequence":"They listen and you feel lighter.","outcome":"supported","best":true},{"text":"Decide you must figure it out alone","consequence":"The worry feels heavier each day.","outcome":"missed"}],"debrief":"A trusted grown-up or sibling can help you carry it.","relearn":"You don't have to figure everything out alone.","persona":"any","source":"trusted adults"},
  {"id":"wm-1373","cat":"be-yourself","type":"branch","hook":"Friends laugh at your different lunch and ask you to throw it away.","options":[{"text":"Keep and enjoy your lunch","consequence":"You eat happy; soon a friend wants a taste.","outcome":"values","best":true},{"text":"Throw it away to fit in","consequence":"You're hungry and a part of home feels lost.","outcome":"missed"}],"debrief":"Your home and your tastes are part of you.","relearn":"What makes you different is part of you.","persona":"Faizan-type","source":"belonging"},
  {"id":"wm-1374","cat":"be-yourself","type":"branch","hook":"You're great at something most kids find boring.","options":[{"text":"Keep practising what you love","consequence":"You get even better; it becomes your thing.","outcome":"strength","best":true},{"text":"Quit so you're like everyone else","consequence":"You lose a spark that was really yours.","outcome":"missed"}],"debrief":"Your differences can grow into your strengths.","relearn":"Your differences can be your strengths.","persona":"any","source":"self-esteem"},
  {"id":"wm-1375","cat":"be-yourself","type":"branch","hook":"Kids tease you to act 'tougher' and never show you care.","options":[{"text":"Stay caring and gentle","consequence":"Friends feel safe with you; you feel right.","outcome":"values","best":true},{"text":"Act cold so they stop teasing","consequence":"You feel false and a bit lonely.","outcome":"missed"}],"debrief":"Caring is a real strength, not a weakness.","relearn":"You can be caring and still be strong.","persona":"Faizan-type","source":"self-esteem"},
  {"id":"wm-1376","cat":"be-yourself","type":"branch","hook":"You want to try a new hobby but worry kids will laugh.","options":[{"text":"Give it a try anyway","consequence":"You find a new thing you love about you.","outcome":"growth","best":true},{"text":"Skip it so no one laughs","consequence":"You always wonder what you missed.","outcome":"missed"}],"debrief":"Trying new things helps you find more of you.","relearn":"You can try new things and grow.","persona":"any","source":"identity over time"},
  {"id":"wm-1377","cat":"be-yourself","type":"branch","hook":"A friend whispers that they feel different and scared to say so.","options":[{"text":"Tell them they're safe and great as they are","consequence":"They breathe easier and feel less alone.","outcome":"ally","best":true},{"text":"Tell them to just act normal","consequence":"They shrink and stop trusting you.","outcome":"missed"}],"debrief":"Telling a friend they're okay as they are is a real gift.","relearn":"You can help a friend feel okay as they are.","persona":"ally seed","source":"friendship"},
  {"id":"wm-1378","cat":"be-yourself","type":"branch","hook":"You're asked to pick a costume for the school play.","options":[{"text":"Pick the role that feels like you","consequence":"You shine because it fits the real you.","outcome":"values","best":true},{"text":"Pick what others say suits you","consequence":"You feel a bit like you're wearing a mask.","outcome":"missed"}],"debrief":"Choosing what feels like you helps you shine.","relearn":"You can choose what feels like you.","persona":"be-yourself","source":"authenticity"},
  {"id":"wm-1379","cat":"be-yourself","type":"branch","hook":"Someone says you must change one part of you to join the team.","options":[{"text":"Stay yourself and find your spot","consequence":"You join as you; a good team makes room.","outcome":"values","best":true},{"text":"Hide that part to be allowed in","consequence":"You're in, but a part of you stays hidden.","outcome":"missed"}],"debrief":"You don't have to change who you are to belong.","relearn":"You never have to change who you are to belong.","persona":"be-yourself","source":"belonging"},
  {"id":"wm-1380","cat":"be-yourself","type":"branch","hook":"You feel proud of yourself and a kid says \"stop showing off.\"","options":[{"text":"Stay quietly proud of you","consequence":"Your pride is yours; it doesn't fade.","outcome":"values","best":true},{"text":"Decide being proud is wrong","consequence":"You start to dim your own light.","outcome":"missed"}],"debrief":"Being quietly proud of yourself is a good thing.","relearn":"It's okay to be proud of who you are.","persona":"any","source":"self-esteem"},
  {"id":"wm-1381","cat":"be-yourself","type":"reflect","hook":"Lensy: who knows the real you best?","prompt":"What do you think?","options":["Me","I do","Only I know"],"affirm":"Only you truly know the real you. That's yours.","relearn":"Only you truly know the real you.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-1382","cat":"be-yourself","type":"reflect","hook":"Lensy: is it okay to like different things than your friends?","prompt":"What do you think?","options":["Yes","Totally okay","I like my things"],"affirm":"It's okay to like different things and still be friends.","relearn":"You can like different things and still belong.","persona":"any","source":"authenticity"},
  {"id":"wm-1383","cat":"be-yourself","type":"reflect","hook":"Lensy: name one thing you like about being you.","prompt":"What comes to mind?","options":["My kindness","How curious I am","My own ideas"],"affirm":"That's a lovely part of the one-of-a-kind you.","relearn":"There's a lot to like about being you.","persona":"any","source":"self-esteem"},
  {"id":"wm-1384","cat":"be-yourself","type":"reflect","hook":"Lensy: if you feel unsure, who could you tell?","prompt":"Who comes to mind?","options":["A parent","My teacher","My sister or brother"],"affirm":"Telling a trusted grown-up means you don't carry it alone.","relearn":"A trusted grown-up can help when you feel unsure.","persona":"any","source":"trusted adults"},
  {"id":"wm-1385","cat":"be-yourself","type":"reflect","hook":"Lensy: can the things that make you different be good things?","prompt":"What do you think?","options":["Yes","They're my strengths","For sure"],"affirm":"Your differences can be some of your best strengths.","relearn":"Your differences can be your strengths.","persona":"any","source":"self-esteem"},
  {"id":"wm-1386","cat":"be-yourself","type":"reflect","hook":"Lensy: do you have to be loud to matter?","prompt":"What do you think?","options":["No","Quiet matters too","I'm fine as I am"],"affirm":"Loud or quiet, you matter exactly as you are.","relearn":"You matter whether you're loud or quiet.","persona":"any","source":"self-esteem"},
  {"id":"wm-1387","cat":"be-yourself","type":"reflect","hook":"Lensy: will you still be you when you're bigger?","prompt":"What do you think?","options":["Yes","I grow and stay me","Still me"],"affirm":"You can grow as big as you like and still be you.","relearn":"You grow and change and still stay you.","persona":"any","source":"identity over time"},
  {"id":"wm-1388","cat":"be-yourself","type":"reflect","hook":"Lensy: do you have to prove who you are to anyone?","prompt":"What do you think?","options":["No","I just am","Never"],"affirm":"You never have to prove who you are. You simply are.","relearn":"You never have to prove who you are.","persona":"be-yourself","source":"gender norms"},
  {"id":"wm-1389","cat":"be-yourself","type":"reflect","hook":"Lensy: is it okay to do something your own way?","prompt":"What do you think?","options":["Yes","My way is fine","Of course"],"affirm":"There's more than one right way, and yours is okay.","relearn":"Your own way of doing things is okay.","persona":"any","source":"self-esteem"},
  {"id":"wm-1390","cat":"be-yourself","type":"reflect","hook":"Lensy: is it kind to remind a friend they're great as they are?","prompt":"What do you think?","options":["Yes","Very kind","It's a gift"],"affirm":"Reminding a friend they're great as they are is a real gift.","relearn":"Lifting a friend up is a kind thing to do.","persona":"ally seed","source":"friendship"},
  {"id":"wm-1391","cat":"be-yourself","type":"reflect","hook":"Lensy: who decides what you love?","prompt":"What do you think?","options":["Me","I do","My own heart"],"affirm":"You decide what you love. That choice is yours.","relearn":"You decide what you love.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-1392","cat":"be-yourself","type":"reflect","hook":"Lensy: is it okay to feel unsure sometimes?","prompt":"What do you think?","options":["Yes","Everyone does","It's normal"],"affirm":"Feeling unsure is normal, and you can ask for help.","relearn":"It's okay to feel unsure sometimes.","persona":"any","source":"trusted adults"},
  {"id":"wm-1393","cat":"be-yourself","type":"reflect","hook":"Lensy: is there anyone else exactly like you?","prompt":"What do you think?","options":["No","I'm one of a kind","Just me"],"affirm":"Nobody else is exactly you, and that is amazing.","relearn":"You are one of a kind.","persona":"any","source":"self-esteem"},
  {"id":"wm-1394","cat":"be-yourself","type":"reflect","hook":"Lensy: can you be both gentle and strong?","prompt":"What do you think?","options":["Yes","Both at once","That's me"],"affirm":"You can be gentle and strong; both are truly you.","relearn":"You can be gentle and strong at the same time.","persona":"any","source":"self-esteem"},
  {"id":"wm-1395","cat":"be-yourself","type":"reflect","hook":"Lensy: is it showing off to be proud of yourself?","prompt":"What do you think?","options":["No","It's just being proud","It's okay"],"affirm":"Being proud of yourself is a good and healthy thing.","relearn":"It's okay to be proud of who you are.","persona":"any","source":"self-esteem"},
  {"id":"wm-1396","cat":"be-yourself","type":"reflect","hook":"Lensy: what would you tell a kid who feels too different?","prompt":"What would you say?","options":["You belong","Different is good","You're great as you are"],"affirm":"That's a kind, true thing to tell anyone who feels different.","relearn":"Different is normal, and everyone belongs.","persona":"ally seed","source":"belonging"},
  {"id":"wm-1397","cat":"be-yourself","type":"reflect","hook":"Lensy: pick a tiny promise to yourself.","prompt":"Pick one to keep.","options":["I'll be me","I'll stay kind","I'll ask for help when I need it"],"affirm":"That's a wonderful promise to keep for the one-of-a-kind you.","relearn":"You can make kind promises to yourself.","persona":"be-yourself","source":"self-esteem"},
  {"id":"wm-1398","cat":"be-yourself","type":"build","hook":"Build a 'this is me' badge to wear.","prompt":"Pick the parts that are really you.","pieces":["one of a kind","kind and curious","good as I am","just like everyone else"],"mode":"assemble","key":["one of a kind","kind and curious","good as I am"],"relearn":"You can name the parts that make you, you.","persona":"any","source":"self-esteem"},
  {"id":"wm-1399","cat":"be-yourself","type":"build","hook":"Build a calm-down plan for when you feel unsure.","prompt":"Put the steps in order.","pieces":["Take a slow breath","Name the worry","Tell a trusted grown-up"],"mode":"sequence","key":["Take a slow breath","Name the worry","Tell a trusted grown-up"],"relearn":"You can breathe, name it, and tell a trusted grown-up.","persona":"any","source":"trusted adults"},
  {"id":"wm-1400","cat":"be-yourself","type":"build","hook":"Build a kind thing to say to a friend who feels small.","prompt":"Pick the words that lift them up.","pieces":["You're great as you are","Just be normal","The real you is enough"],"mode":"assemble","key":["You're great as you are","The real you is enough"],"relearn":"Kind words can remind a friend they're enough.","persona":"ally seed","source":"friendship"},
  {"id":"wm-1401","cat":"be-yourself","type":"build","hook":"Build your 'be myself' plan for a new school.","prompt":"Put the steps in order.","pieces":["Say my name clearly","Share one thing I love","Be kind to someone new"],"mode":"sequence","key":["Say my name clearly","Share one thing I love","Be kind to someone new"],"relearn":"You can be yourself even somewhere new.","persona":"be-yourself","source":"belonging"},
  {"id":"wm-1402","cat":"be-yourself","type":"build","hook":"Build a 'my strengths' card from what makes you different.","prompt":"Pick your real strengths.","pieces":["I notice how others feel","I have my own ideas","I copy everyone","I keep trying"],"mode":"assemble","key":["I notice how others feel","I have my own ideas","I keep trying"],"relearn":"Your differences can become your strengths.","persona":"any","source":"self-esteem"},
  {"id":"wm-1403","cat":"be-yourself","type":"build","hook":"Build the steps to stand with a teased friend.","prompt":"Put the steps in order.","pieces":["Go stand beside them","Use their name kindly","Ask them to play"],"mode":"sequence","key":["Go stand beside them","Use their name kindly","Ask them to play"],"relearn":"You can put respect into action for a friend.","persona":"ally seed","source":"bystander"},
  {"id":"wm-1404","cat":"be-yourself","type":"build","hook":"Build your carry-forward motto from today.","prompt":"Pick the lines to carry.","pieces":["Who I am is mine","Many ways to be","I must copy others","I'm good as I am"],"mode":"assemble","key":["Who I am is mine","Many ways to be","I'm good as I am"],"relearn":"Who you are is yours, and you're good as you are.","persona":"any","source":"consolidation"},
  {"id": "wm-1405", "cat": "be-yourself", "type": "match", "hook": "Match each feeling to a kind thing you can do.", "pairs": [{"left": "I feel unsure", "right": "Tell a trusted grown-up"}, {"left": "I feel proud", "right": "Enjoy it, that's okay"}, {"left": "A friend feels small", "right": "Remind them they're great"}, {"left": "Someone teases me", "right": "Stay true to myself"}, {"left": "I want to try something new", "right": "Give it a go"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1406", "cat": "be-yourself", "type": "match", "hook": "Match each 'be yourself' idea to what it means.", "pairs": [{"left": "One of a kind", "right": "Nobody else is exactly me"}, {"left": "My differences", "right": "Can be my strengths"}, {"left": "I grow and change", "right": "And I'm still me"}, {"left": "Who I am", "right": "Is mine to know"}, {"left": "Proving myself", "right": "Something I never have to do"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1407", "cat": "be-yourself", "type": "match", "hook": "Match each push from others to a true, kind reply.", "pairs": [{"left": "Be like everyone else", "right": "I can be my own self"}, {"left": "Hide what you love", "right": "I can love what I love"}, {"left": "You can't change", "right": "I grow and stay me"}, {"left": "Prove you're real", "right": "I simply am who I am"}, {"left": "Copy me to belong", "right": "I belong as myself"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1408", "cat": "be-yourself", "type": "match", "hook": "Match each kid to a strength that is part of them.", "pairs": [{"left": "Asks lots of questions", "right": "Curious"}, {"left": "Shares their snack", "right": "Generous"}, {"left": "Keeps trying after a miss", "right": "Determined"}, {"left": "Notices a sad friend", "right": "Caring"}, {"left": "Has their own ideas", "right": "Original"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1409", "cat": "be-yourself", "type": "match", "hook": "Match each worry to who can help you carry it.", "pairs": [{"left": "Trouble at school", "right": "My teacher"}, {"left": "A scary feeling at home", "right": "A parent"}, {"left": "Something I can't say out loud yet", "right": "My sister or brother"}, {"left": "Feeling alone with a worry", "right": "Childline, one-zero-nine-eight"}, {"left": "Unsure who I am inside", "right": "A trusted grown-up"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1410", "cat": "be-yourself", "type": "match", "hook": "Match each 'me' part to where it lives.", "pairs": [{"left": "My name", "right": "What people call me"}, {"left": "My loves", "right": "The things I enjoy"}, {"left": "My feelings", "right": "Inside my heart"}, {"left": "Who I am", "right": "Mine to know best"}, {"left": "My strengths", "right": "What I'm good at"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1411", "cat": "be-yourself", "type": "match", "hook": "Match each true line to the moment it fits.", "pairs": [{"left": "You're great as you are", "right": "A friend feels down"}, {"left": "I'm being myself", "right": "Someone says to change"}, {"left": "I can ask for help", "right": "I feel unsure"}, {"left": "I'm one of a kind", "right": "Someone compares me"}, {"left": "I'll give it a try", "right": "Something new and a bit scary"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1412", "cat": "be-yourself", "type": "match", "hook": "Match each habit to the way it helps you be you.", "pairs": [{"left": "Naming what I like", "right": "Knowing myself"}, {"left": "Saying my own choice", "right": "Using my voice"}, {"left": "Trying new things", "right": "Growing"}, {"left": "Telling a grown-up a worry", "right": "Not carrying it alone"}, {"left": "Lifting a friend up", "right": "Sharing kindness"}], "relearn": "Each thing matches kindly with where it belongs.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1413", "cat": "be-yourself", "type": "sort", "hook": "Sort each line: is it true about being you, or not?", "items": [{"id": "a", "text": "Only I know who I am inside"}, {"id": "b", "text": "I must prove myself to others"}, {"id": "c", "text": "My differences can be strengths"}, {"id": "d", "text": "I have to copy everyone"}, {"id": "e", "text": "I can grow and still be me"}, {"id": "f", "text": "I should hide what I love"}], "bins": [{"id": "true", "label": "True about me", "valence": "pos"}, {"id": "not", "label": "Not true", "valence": "neg"}], "key": {"a": "true", "b": "not", "c": "true", "d": "not", "e": "true", "f": "not"}, "relearn": "What's true about you: only you know yourself, you grow, your differences are strengths.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1414", "cat": "be-yourself", "type": "sort", "hook": "Sort each thing: my own choice, or someone else's to decide?", "items": [{"id": "a", "text": "What I love to do"}, {"id": "b", "text": "Who I am inside"}, {"id": "c", "text": "My favourite colour"}, {"id": "d", "text": "The class fire-drill rule"}, {"id": "e", "text": "School starting time"}, {"id": "f", "text": "What makes me proud"}], "bins": [{"id": "mine", "label": "My own choice", "valence": "neutral"}, {"id": "shared", "label": "Someone else decides", "valence": "neutral"}], "key": {"a": "mine", "b": "mine", "c": "mine", "d": "shared", "e": "shared", "f": "mine"}, "relearn": "Some things are mine to choose; shared rules are decided together.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1415", "cat": "be-yourself", "type": "sort", "hook": "Sort each move: lifts someone up, or puts them down?", "items": [{"id": "a", "text": "\"You're great as you are\""}, {"id": "b", "text": "\"Just be normal\""}, {"id": "c", "text": "Standing beside a teased friend"}, {"id": "d", "text": "Laughing at how someone talks"}, {"id": "e", "text": "Asking a lonely kid to play"}, {"id": "f", "text": "Telling someone to hide who they are"}], "bins": [{"id": "up", "label": "Lifts up", "valence": "pos"}, {"id": "down", "label": "Puts down", "valence": "neg"}], "key": {"a": "up", "b": "down", "c": "up", "d": "down", "e": "up", "f": "down"}, "relearn": "Lifting people up beats putting them down.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1416", "cat": "be-yourself", "type": "sort", "hook": "Sort each feeling: handle it myself, or tell a trusted grown-up?", "items": [{"id": "a", "text": "A little nervous before a game"}, {"id": "b", "text": "A worry that won't go away"}, {"id": "c", "text": "Excited about a new hobby"}, {"id": "d", "text": "Feeling alone and unsure inside"}, {"id": "e", "text": "Happy about my drawing"}, {"id": "f", "text": "A scared feeling I can't shake"}], "bins": [{"id": "self", "label": "I can handle this", "valence": "pos"}, {"id": "tell", "label": "Tell a grown-up", "valence": "tell"}], "key": {"a": "self", "b": "tell", "c": "self", "d": "tell", "e": "self", "f": "tell"}, "relearn": "Some feelings I can handle; the heavy ones I tell a trusted grown-up.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1417", "cat": "be-yourself", "type": "sort", "hook": "Sort each part: a strength, or just something I like?", "items": [{"id": "a", "text": "I keep trying after a miss"}, {"id": "b", "text": "I like mango ice cream"}, {"id": "c", "text": "I notice when a friend is sad"}, {"id": "d", "text": "I enjoy rainy days"}, {"id": "e", "text": "I have my own bright ideas"}, {"id": "f", "text": "I like the colour green"}], "bins": [{"id": "strength", "label": "A strength of mine", "valence": "pos"}, {"id": "like", "label": "Just something I like", "valence": "neutral"}], "key": {"a": "strength", "b": "like", "c": "strength", "d": "like", "e": "strength", "f": "like"}, "relearn": "My strengths are things I do; likes are things I enjoy, both part of me.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1418", "cat": "be-yourself", "type": "sort", "hook": "Sort each line: being myself, or copying to fit in?", "items": [{"id": "a", "text": "Choosing the hobby I love"}, {"id": "b", "text": "Dropping a friend to look cool"}, {"id": "c", "text": "Sharing my own idea"}, {"id": "d", "text": "Pretending to like a game I don't"}, {"id": "e", "text": "Doing a task my own careful way"}, {"id": "f", "text": "Hiding what I love so others approve"}], "bins": [{"id": "me", "label": "Being myself", "valence": "pos"}, {"id": "copy", "label": "Copying to fit in", "valence": "neg"}], "key": {"a": "me", "b": "copy", "c": "me", "d": "copy", "e": "me", "f": "copy"}, "relearn": "Being myself beats copying others just to fit in.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1419", "cat": "be-yourself", "type": "sort", "hook": "Sort each statement: true about growing, or not?", "items": [{"id": "a", "text": "I can change and still be me"}, {"id": "b", "text": "Trying new things helps me grow"}, {"id": "c", "text": "Once decided, I can never change"}, {"id": "d", "text": "Learning new things is part of me"}, {"id": "e", "text": "Growing means I'm no longer myself"}, {"id": "f", "text": "I'm still one-of-a-kind as I grow"}], "bins": [{"id": "true", "label": "True", "valence": "pos"}, {"id": "not", "label": "Not true", "valence": "neg"}], "key": {"a": "true", "b": "true", "c": "not", "d": "true", "e": "not", "f": "true"}, "relearn": "I can grow and change and still be one-of-a-kind me.", "persona": "any", "source": "be-yourself"},
  {"id": "wm-1420", "cat": "be-yourself", "type": "sort", "hook": "Sort each thing: a part of who I am, or not really me?", "items": [{"id": "a", "text": "My kindness"}, {"id": "b", "text": "My shoe size"}, {"id": "c", "text": "My own ideas"}, {"id": "d", "text": "The brand on my bag"}, {"id": "e", "text": "What I love to do"}, {"id": "f", "text": "The latest trend everyone follows"}], "bins": [{"id": "me", "label": "Part of who I am", "valence": "pos"}, {"id": "no", "label": "Not really me", "valence": "neutral"}], "key": {"a": "me", "b": "no", "c": "me", "d": "no", "e": "me", "f": "no"}, "relearn": "What I am is my kindness, ideas and loves, not brands or trends.", "persona": "any", "source": "be-yourself"},
  {"id":"wm-1170","cat":"many-ways","type":"strike-rewrite","hook":"\"A boy who likes to dance can't really be a boy.\"","myth":{"un":"A boy who likes to dance can't really be a boy.","re":"There are many ways to be a boy, and dancing is one of them.","why":"What you love doesn't decide who you are."},"relearn":"There are many ways to be a boy; dancing is one of them.","persona":"Faizan-type","source":"gender norms"},
  {"id":"wm-1171","cat":"many-ways","type":"strike-rewrite","hook":"\"A girl can't be the bravest one in the team.\"","myth":{"un":"A girl can't be the bravest one in the team.","re":"There are many ways to be a girl, and bold and brave is one of them.","why":"Girls are as varied as all people."},"relearn":"There are many ways to be a girl; bold and brave is one of them.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-1172","cat":"many-ways","type":"strike-rewrite","hook":"\"Hijras are something new in India.\"","myth":{"un":"Hijras are something new in India.","re":"The hijra community has been part of India for a very long time.","why":"They appear in our old stories and history."},"relearn":"The hijra community has been part of India for a very long time.","persona":"India","source":"hijra history"},
  {"id":"wm-1173","cat":"many-ways","type":"strike-rewrite","hook":"\"Feeling like neither a boy nor a girl is just being silly.\"","myth":{"un":"Feeling like neither a boy nor a girl is just being silly.","re":"Some people feel like neither or both, and that is real and okay.","why":"People are wonderfully varied."},"relearn":"Some people feel like neither or both, and that is real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1174","cat":"many-ways","type":"strike-rewrite","hook":"\"Everyone has to fit into one of two boxes.\"","myth":{"un":"Everyone has to fit into one of two boxes.","re":"Boy, girl, and some feel like neither or both, all real.","why":"India has known people beyond two for a long time."},"relearn":"Boy, girl, and some feel like neither or both, all real.","persona":"India","source":"hijra history"},
  {"id":"wm-1175","cat":"many-ways","type":"strike-rewrite","hook":"\"The idea of more than two genders came from outside India.\"","myth":{"un":"The idea of more than two came from outside India.","re":"India has known people beyond boy and girl for a very long time.","why":"It is part of our own stories and law."},"relearn":"India has known people beyond boy and girl for a very long time.","persona":"India","source":"hijra history"},
  {"id":"wm-1176","cat":"many-ways","type":"strike-rewrite","hook":"\"Only male and female are real to the law in India.\"","myth":{"un":"Only male and female are real to the law in India.","re":"India's law recognises a third gender, not only male and female.","why":"The Supreme Court recognised it in NALSA, 2014."},"relearn":"India's law recognises a third gender.","persona":"India","source":"NALSA 2014"},
  {"id":"wm-1177","cat":"many-ways","type":"strike-rewrite","hook":"\"A girl who climbs trees and plays kabaddi is doing it wrong.\"","myth":{"un":"A girl who climbs trees and plays kabaddi is doing it wrong.","re":"There are many ways to be a girl, climbing and kabaddi included.","why":"Liking active games doesn't change who you are."},"relearn":"There are many ways to be a girl.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-1178","cat":"many-ways","type":"strike-rewrite","hook":"\"A quiet, gentle boy who paints isn't a 'real' boy.\"","myth":{"un":"A quiet, gentle boy who paints isn't a 'real' boy.","re":"Quiet, gentle, arty, this is one of the many ways to be a boy.","why":"Boys are as varied as all people."},"relearn":"Quiet, gentle, arty is one of the many ways to be a boy.","persona":"Faizan-type","source":"gender norms"},
  {"id":"wm-1179","cat":"many-ways","type":"strike-rewrite","hook":"\"People who feel different from their body are made wrong.\"","myth":{"un":"People who feel different from their body are 'made wrong'.","re":"No one is made wrong for being who they are.","why":"Every person deserves dignity and respect."},"relearn":"No one is 'made wrong' for being who they are.","persona":"respect","source":"dignity"},
  {"id":"wm-1180","cat":"many-ways","type":"strike-rewrite","hook":"\"You should fix a child who feels like a different gender.\"","myth":{"un":"You should 'fix' a child who feels like a different gender.","re":"Being who you are is healthy and normal, nothing to fix.","why":"Diversity is a normal part of growing up."},"relearn":"Being who you are is healthy and normal, nothing to fix.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1181","cat":"many-ways","type":"strike-rewrite","hook":"\"There's just one correct way to be either a boy or a girl.\"","myth":{"un":"There's just one correct way to be a boy or a girl.","re":"There is no single right way to be a boy or a girl.","why":"Each person finds their own way of being."},"relearn":"There is no single right way to be a boy or a girl.","persona":"gender thread","source":"gender norms"},
  {"id":"wm-1182","cat":"many-ways","type":"strike-rewrite","hook":"\"It's weird to use 'they' for one person.\"","myth":{"un":"It's weird to use 'they' for one person.","re":"Some people use 'they', and using it for them is kind and easy.","why":"Using someone's word shows respect."},"relearn":"Some people use 'they'; using it for them is kind and easy.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1183","cat":"many-ways","type":"strike-rewrite","hook":"\"Hijras don't belong at our festivals and weddings.\"","myth":{"un":"Hijras don't belong at our festivals and weddings.","re":"Hijras have long been part of Indian festivals and family life.","why":"Their blessings are an old part of our culture."},"relearn":"Hijras have long been part of Indian festivals and family life.","persona":"India","source":"hijra history"},
  {"id":"wm-1184","cat":"many-ways","type":"strike-rewrite","hook":"\"Liking sport makes a girl 'not a girl'.\"","myth":{"un":"Liking sport makes a girl 'not a girl'.","re":"Loving sport is just one of the many ways to be a girl.","why":"What you like doesn't change who you are."},"relearn":"Loving sport is one of the many ways to be a girl.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-1185","cat":"many-ways","type":"strike-rewrite","hook":"\"Everyone in a family must be the same kind of person.\"","myth":{"un":"Everyone in a family must be the same kind of person.","re":"One family can hold many ways of being, and that's lovely.","why":"Difference makes a family bigger, not smaller."},"relearn":"One family can hold many ways of being.","persona":"any","source":"diversity"},
  {"id":"wm-1186","cat":"many-ways","type":"strike-rewrite","hook":"\"There are only two kinds of people anywhere in the world.\"","myth":{"un":"There are only two kinds of people anywhere.","re":"Boy, girl, and some feel like neither or both, all real.","why":"People everywhere are wonderfully varied."},"relearn":"Boy, girl, and some feel like neither or both, all real.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1187","cat":"many-ways","type":"reflect","hook":"Lensy: there are so many ways to be a kid, loud, quiet, sporty, dreamy.","prompt":"Which kind of kid are you today?","options":["A bit of everything","Quiet today","Loud and bouncy"],"affirm":"However you are today, that's a wonderful way to be you.","relearn":"There are many ways to be, and yours is wonderful.","persona":"any","source":"diversity"},
  {"id":"wm-1188","cat":"many-ways","type":"reflect","hook":"Lensy: long ago in India, people beyond boy and girl were part of life.","prompt":"How does it feel to know that's our own history?","options":["Nice to know","Cool, it's ours","I never knew that"],"affirm":"India has known people beyond boy and girl for a very long time.","relearn":"India has known people beyond boy and girl for a very long time.","persona":"India","source":"hijra history"},
  {"id":"wm-1189","cat":"many-ways","type":"reflect","hook":"Lensy: India's own law says there can be more than just male and female.","prompt":"What do you think of that?","options":["That's fair","Good for everyone","Makes sense"],"affirm":"India's law recognises a third gender, so everyone is seen.","relearn":"India's law recognises a third gender.","persona":"India","source":"NALSA 2014"},
  {"id":"wm-1190","cat":"many-ways","type":"reflect","hook":"Lensy: you meet a kid who feels like neither a boy nor a girl.","prompt":"What might you say first?","options":["Hi, want to play?","What's your name?","Tell me about you"],"affirm":"Saying a kind hello is always a good start with anyone.","relearn":"Someone who feels like neither or both is real and okay.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1191","cat":"many-ways","type":"reflect","hook":"Lensy: a new friend says, 'please use they for me.'","prompt":"How do you feel about trying that?","options":["I can do that","Easy enough","I'll get used to it"],"affirm":"Using someone's word for themselves is a kind, easy gift.","relearn":"Some people use 'they'; using it for them is kind and easy.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1192","cat":"many-ways","type":"reflect","hook":"Lensy: there's no single right way to be a boy or a girl.","prompt":"What's one way you love being you?","options":["I'm caring","I'm curious","I'm funny"],"affirm":"That's a wonderful way to be, and it's all yours.","relearn":"There is no single right way to be a boy or a girl.","persona":"be-yourself","source":"gender norms"},
  {"id":"wm-1193","cat":"many-ways","type":"reflect","hook":"Lensy: some classmates are gentle, some are bold, some are both.","prompt":"What do you notice about your class?","options":["Everyone's different","We're all kinds","Lots of ways to be"],"affirm":"Yes, your class holds many wonderful ways to be.","relearn":"There are many ways to be, all in one class.","persona":"any","source":"diversity"},
  {"id":"wm-1194","cat":"many-ways","type":"reflect","hook":"Lensy: a boy in your class loves rangoli and quiet games.","prompt":"What do you think of that?","options":["That's nice","Lots of ways to be a boy","Sounds fun"],"affirm":"There are many ways to be a boy, and his is one of them.","relearn":"There are many ways to be a boy.","persona":"Faizan-type","source":"gender norms"},
  {"id":"wm-1195","cat":"many-ways","type":"reflect","hook":"Lensy: a girl in your class captains the cricket team.","prompt":"What do you think of that?","options":["Brilliant","Lots of ways to be a girl","Go her"],"affirm":"There are many ways to be a girl, and leading is one of them.","relearn":"There are many ways to be a girl.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-1196","cat":"many-ways","type":"reflect","hook":"Lensy: hijras have been part of India's stories for ages and ages.","prompt":"Want to know more about our own history one day?","options":["Yes please","Sounds interesting","I'd like that"],"affirm":"India has long had people beyond boy and girl, it's our story.","relearn":"India has long had people beyond boy and girl.","persona":"India","source":"hijra history"},
  {"id":"wm-1197","cat":"many-ways","type":"reflect","hook":"Lensy: everyone is a little different, and that's a good thing.","prompt":"What makes the world more fun, do you think?","options":["Lots of kinds of people","That we're all different","Meeting new people"],"affirm":"Many ways of being make the world more interesting for all of us.","relearn":"Many different people make the world more interesting.","persona":"any","source":"diversity"},
  {"id":"wm-1198","cat":"many-ways","type":"reflect","hook":"Lensy: you're sure who you are, and your friend is sure who they are.","prompt":"Can you both be right at once?","options":["Yes, both","Of course","We're both us"],"affirm":"Yes, you can know yourself and respect others at the same time.","relearn":"You can be sure of yourself and respect others too.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1199","cat":"many-ways","type":"reflect","hook":"Lensy: no one is made wrong for being who they are.","prompt":"What do you think everyone deserves?","options":["Kindness","Respect","To be themselves"],"affirm":"Yes, every way of being a person deserves kindness and respect.","relearn":"Every way of being a person deserves respect.","persona":"respect","source":"dignity"},
  {"id":"wm-1200","cat":"many-ways","type":"reflect","hook":"Lensy: you saw someone who feels like both a boy and a girl inside.","prompt":"What feels true to you?","options":["That's okay","People are varied","Real and okay"],"affirm":"Someone who feels like both is real and okay, just like you.","relearn":"Someone who feels like both is real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1201","cat":"many-ways","type":"match","hook":"Match each India fact to where it comes from. (All true!)","pairs":[{"left":"Third gender in law","right":"Court ruling, NALSA, 2014"},{"left":"Hijra community","right":"Long part of our history"},{"left":"More than two","right":"Part of our own stories"},{"left":"Wedding blessings","right":"An old Indian custom"},{"left":"Many ways to be","right":"True of people everywhere"}],"relearn":"'More than two' is part of India's own history and law.","persona":"India","source":"hijra history / NALSA"},
  {"id":"wm-1202","cat":"many-ways","type":"match","hook":"Match each way of being to 'real and okay'. (Trick: all are!)","pairs":[{"left":"A boy who dances","right":"Real and okay"},{"left":"A girl who plays cricket","right":"A wonderful way to be"},{"left":"Someone who feels like both","right":"True and fine"},{"left":"Someone who uses 'they'","right":"Easy to respect"},{"left":"Someone who feels like neither","right":"Welcome here too"}],"relearn":"Every way of being a person is real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1203","cat":"many-ways","type":"match","hook":"Match each kid to one of the many ways to be. (All are great!)","pairs":[{"left":"Loud and bouncy","right":"A fun way to be"},{"left":"Quiet and dreamy","right":"A calm way to be"},{"left":"Bold and brave","right":"A strong way to be"},{"left":"Gentle and caring","right":"A kind way to be"},{"left":"Curious and busy","right":"A bright way to be"}],"relearn":"There are many ways to be, all wonderful.","persona":"any","source":"diversity"},
  {"id":"wm-1204","cat":"many-ways","type":"match","hook":"Match each kind word to the friend it fits. (All are kind!)","pairs":[{"left":"To a kid who feels like both","right":"You're real and okay"},{"left":"To a kid who uses 'they'","right":"I'll use 'they' for you"},{"left":"To a shy new kid","right":"Want to play with us?"},{"left":"To a friend who's unsure","right":"You're great as you are"},{"left":"To anyone at all","right":"You belong here"}],"relearn":"Kind words help everyone feel they belong.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1205","cat":"many-ways","type":"match","hook":"Match each saying to what it means. (All point the same way!)","pairs":[{"left":"Many ways to be","right":"No single right way"},{"left":"You be you","right":"I'll be me"},{"left":"Who I am is mine","right":"Only I know it best"},{"left":"Respect everyone's me","right":"Be kind to all kinds"},{"left":"All real, all okay","right":"No one is made wrong"}],"relearn":"There are many ways to be, and each one deserves respect.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1206","cat":"many-ways","type":"match","hook":"Match each child to a way of being a boy. (Many ways are fine!)","pairs":[{"left":"Aarav loves cooking","right":"A boy who cooks"},{"left":"Dev paints all day","right":"A boy who paints"},{"left":"Karan cries at films","right":"A boy who feels deeply"},{"left":"Rohan dances garba","right":"A boy who dances"},{"left":"Vivaan loves babies","right":"A boy who is caring"}],"relearn":"There are many ways to be a boy.","persona":"Faizan-type","source":"gender norms"},
  {"id":"wm-1207","cat":"many-ways","type":"match","hook":"Match each child to a way of being a girl. (Many ways are fine!)","pairs":[{"left":"Meera fixes cycles","right":"A girl who builds"},{"left":"Sara plays kabaddi","right":"A girl who is sporty"},{"left":"Diya leads the class","right":"A girl who leads"},{"left":"Anvi loves bugs","right":"A girl who explores"},{"left":"Tara is very quiet","right":"A girl who is gentle"}],"relearn":"There are many ways to be a girl.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-1208","cat":"many-ways","type":"role-play","hook":"A classmate giggles, 'boys can't do bharatanatyam!'","setup":"Stand up kindly. Say:","yourLine":[{"text":"\"Sure they can, there are many ways to be a boy.\"","best":true},{"text":"\"Yeah, that's a bit weird.\""}],"relearn":"There are many ways to be a boy.","persona":"ally seed","source":"gender norms"},
  {"id":"wm-1209","cat":"many-ways","type":"role-play","hook":"A new friend tells you, 'I feel like neither a boy nor a girl.'","setup":"Be warm. Say:","yourLine":[{"text":"\"Okay! That's real and okay. Want to play?\"","best":true},{"text":"\"You have to pick one, though.\""}],"relearn":"Someone who feels like neither is real and okay.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1210","cat":"many-ways","type":"role-play","hook":"Someone asks you to use 'they' when you talk about them.","setup":"Say the kind line:","yourLine":[{"text":"\"Got it, I'll use 'they' for you.\"","best":true},{"text":"\"That's too hard to remember.\""}],"relearn":"Using someone's word for themselves is kind and easy.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1211","cat":"many-ways","type":"role-play","hook":"A friend says hijras at a wedding are 'strange'.","setup":"Share what you know. Say:","yourLine":[{"text":"\"They've been part of India for ages, that's our history.\"","best":true},{"text":"\"Yeah, kind of strange.\""}],"relearn":"Hijras have long been part of Indian life.","persona":"India","source":"hijra history"},
  {"id":"wm-1212","cat":"many-ways","type":"role-play","hook":"A cousin says, 'a real girl wouldn't play football.'","setup":"Speak up gently. Say:","yourLine":[{"text":"\"There are many ways to be a girl, football too.\"","best":true},{"text":"\"Maybe you're right.\""}],"relearn":"There are many ways to be a girl.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-1213","cat":"many-ways","type":"role-play","hook":"You're sure you're a boy, and your friend feels like both.","setup":"Say the both-at-once line:","yourLine":[{"text":"\"I know who I am, and I respect who you are.\"","best":true},{"text":"\"You should feel the way I do.\""}],"relearn":"You can be sure of yourself and respect others too.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1214","cat":"many-ways","type":"role-play","hook":"A kid teases another for being 'not a proper boy'.","setup":"Step in as an ally. Say:","yourLine":[{"text":"\"Leave him be, there are many ways to be a boy.\"","best":true},{"text":"\"Ha, good one.\""}],"relearn":"There are many ways to be a boy; stepping in is kind.","persona":"ally seed","source":"gender norms"},
  {"id":"wm-1215","cat":"many-ways","type":"sort","hook":"Sort: a friendly thought, or a rule that leaves people out?","items":[{"id":"a","text":"Anyone can like any colour"},{"id":"b","text":"Pink is only for girls"},{"id":"c","text":"Both boys and girls can dance"},{"id":"d","text":"Trucks are just for boys"},{"id":"e","text":"Everyone can choose their own games"},{"id":"f","text":"Long hair means you must be a girl"}],"bins":[{"id":"open","label":"Friendly thought","valence":"pos"},{"id":"rule","label":"Leaves people out","valence":"neg"}],"key":{"a":"open","b":"rule","c":"open","d":"rule","e":"open","f":"rule"},"relearn":"Colours, toys and games belong to everyone, not to one kind of kid.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1216","cat":"many-ways","type":"sort","hook":"Sort: part of India's own story, or not from India?","items":[{"id":"a","text":"Hijras, here for ages"},{"id":"b","text":"Third gender in our law"},{"id":"c","text":"Wedding blessings"},{"id":"d","text":"More than two is foreign"},{"id":"e","text":"NALSA, our own court"},{"id":"f","text":"India only knew two"}],"bins":[{"id":"ours","label":"India's own","valence":"neutral"},{"id":"not","label":"Not from India","valence":"neg"}],"key":{"a":"ours","b":"ours","c":"ours","d":"not","e":"ours","f":"not"},"relearn":"'More than two' is part of India's own history and law.","persona":"India","source":"hijra history / NALSA"},
  {"id":"wm-1217","cat":"many-ways","type":"sort","hook":"Sort: a kind reply, or an unkind one?","items":[{"id":"a","text":"I'll use 'they' for you"},{"id":"b","text":"You have to pick one"},{"id":"c","text":"You're real and okay"},{"id":"d","text":"That's too weird"},{"id":"e","text":"Want to play with us?"},{"id":"f","text":"You don't belong here"}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Kind words help everyone feel they belong.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1218","cat":"many-ways","type":"sort","hook":"Sort: a way of being a boy, or not really about boys?","items":[{"id":"a","text":"A boy who dances"},{"id":"b","text":"A boy who paints"},{"id":"c","text":"Only one way to be a boy"},{"id":"d","text":"A boy who plays kabaddi"},{"id":"e","text":"A boy who is gentle"},{"id":"f","text":"A boy can't ever cry"}],"bins":[{"id":"way","label":"A way to be a boy","valence":"neutral"},{"id":"no","label":"Not true","valence":"neg"}],"key":{"a":"way","b":"way","c":"no","d":"way","e":"way","f":"no"},"relearn":"There are many ways to be a boy.","persona":"Faizan-type","source":"gender norms"},
  {"id":"wm-1219","cat":"many-ways","type":"sort","hook":"Sort: a way of being a girl, or not really about girls?","items":[{"id":"a","text":"A girl who leads the team"},{"id":"b","text":"A girl who fixes cycles"},{"id":"c","text":"Only one way to be a girl"},{"id":"d","text":"A girl who loves science"},{"id":"e","text":"A girl who is bold"},{"id":"f","text":"A girl must always be quiet"}],"bins":[{"id":"way","label":"A way to be a girl","valence":"neutral"},{"id":"no","label":"Not true","valence":"neg"}],"key":{"a":"way","b":"way","c":"no","d":"way","e":"way","f":"no"},"relearn":"There are many ways to be a girl.","persona":"Ananya","source":"gender norms"},
  {"id":"wm-1220","cat":"many-ways","type":"sort","hook":"Sort: deserves respect, or never okay to do?","items":[{"id":"a","text":"A boy who loves dance"},{"id":"b","text":"Teasing someone for who they are"},{"id":"c","text":"Someone who feels like both"},{"id":"d","text":"Leaving a kid out for being different"},{"id":"e","text":"A friend who uses 'they'"},{"id":"f","text":"Saying someone is 'made wrong'"}],"bins":[{"id":"respect","label":"Deserves respect","valence":"pos"},{"id":"never","label":"Never okay","valence":"neg"}],"key":{"a":"respect","b":"never","c":"respect","d":"never","e":"respect","f":"never"},"relearn":"Every way of being a person deserves respect.","persona":"respect","source":"dignity"},
  {"id":"wm-1221","cat":"many-ways","type":"sort","hook":"Sort: a way to be, or a too-tight rule?","items":[{"id":"a","text":"Loud and bouncy"},{"id":"b","text":"Boys can't be gentle"},{"id":"c","text":"Quiet and dreamy"},{"id":"d","text":"Girls can't be bold"},{"id":"e","text":"Bold and caring"},{"id":"f","text":"Everyone must act the same"}],"bins":[{"id":"way","label":"A way to be","valence":"neutral"},{"id":"rule","label":"Too-tight rule","valence":"neg"}],"key":{"a":"way","b":"rule","c":"way","d":"rule","e":"way","f":"rule"},"relearn":"There are many ways to be; tight rules leave kids out.","persona":"any","source":"diversity"},
  {"id": "wm-1222", "cat": "many-ways", "type": "branch", "hook": "A boy in your group says he loves making rangoli.", "options": [{"text": "\"Cool, there are many ways to be a boy.\"", "consequence": "He smiles and shows you his design.", "best": true}, {"text": "\"That's a girl thing.\"", "consequence": "He looks down and hides his work."}, {"text": "Say nothing and walk off.", "consequence": "He's left feeling unsure and alone."}], "debrief": "There are many ways to be a boy; what he loves is fine.", "persona": "Faizan-type", "source": "gender norms", "relearn": "There are many ways to be a boy; what he loves is fine."},
  {"id": "wm-1223", "cat": "many-ways", "type": "branch", "hook": "A new friend says, 'please use they when you talk about me.'", "options": [{"text": "\"Sure, I'll use 'they' for you.\"", "consequence": "They feel seen and play happily with you.", "best": true}, {"text": "\"That's too confusing.\"", "consequence": "They feel a bit hurt and quiet."}, {"text": "Keep using the wrong word anyway.", "consequence": "They stop wanting to sit with you."}], "debrief": "Using someone's word for themselves is kind and easy.", "persona": "respect", "source": "respect / voice", "relearn": "Using someone's word for themselves is kind and easy."},
  {"id": "wm-1224", "cat": "many-ways", "type": "branch", "hook": "At a wedding, a kid points at a hijra guest and laughs.", "options": [{"text": "\"They've been part of India for ages.\"", "consequence": "The kid stops laughing and listens.", "best": true}, {"text": "Laugh along with the kid.", "consequence": "The guest hears it and feels unwelcome."}, {"text": "Pretend you didn't notice.", "consequence": "The teasing carries on."}], "debrief": "Hijras have long been part of Indian life and deserve respect.", "persona": "India", "source": "hijra history", "relearn": "Hijras belong in Indian life and deserve respect."},
  {"id": "wm-1225", "cat": "many-ways", "type": "branch", "hook": "A classmate feels like neither a boy nor a girl and tells you quietly.", "options": [{"text": "\"Thanks for telling me. That's okay.\"", "consequence": "They relax and feel safe with you.", "best": true}, {"text": "\"You're making that up.\"", "consequence": "They wish they'd never told you."}, {"text": "Tell the whole class loudly.", "consequence": "They feel exposed and upset."}], "debrief": "Feeling like neither or both is real and okay.", "persona": "respect", "source": "gender diversity", "relearn": "Feeling like neither or both is real and okay."},
  {"id": "wm-1226", "cat": "many-ways", "type": "branch", "hook": "Your team is picking players and a girl asks to be striker.", "options": [{"text": "\"Go for it, many ways to be a girl.\"", "consequence": "She scores and the team cheers.", "best": true}, {"text": "\"Strikers should be boys.\"", "consequence": "She sits out, feeling left behind."}, {"text": "Shrug and pick someone else.", "consequence": "She quietly stops asking to play."}], "debrief": "There are many ways to be a girl, striker included.", "persona": "Ananya", "source": "gender norms", "relearn": "There are many ways to be a girl, striker included."},
  {"id": "wm-1227", "cat": "many-ways", "type": "branch", "hook": "Kids start chanting 'girly boy' at a gentle classmate.", "options": [{"text": "\"Stop, there are many ways to be a boy.\"", "consequence": "The chanting stops and he stands taller.", "best": true}, {"text": "Join the chant.", "consequence": "He shrinks and stops coming to play."}, {"text": "Look away and stay quiet.", "consequence": "He feels no one is on his side."}], "debrief": "Stepping in for a friend is kind; many ways to be a boy.", "persona": "ally seed", "source": "gender norms", "relearn": "Stepping in for a friend is kind; many ways to be a boy."},
  {"id": "wm-1228", "cat": "many-ways", "type": "branch", "hook": "A friend says, 'more than two genders is a foreign idea.'", "options": [{"text": "\"No, it's India's own, hijras and our law.\"", "consequence": "They learn something true.", "best": true}, {"text": "\"Yeah, it's from outside.\"", "consequence": "A wrong idea spreads."}, {"text": "\"Maybe, I'm not sure.\"", "consequence": "The mix-up stays."}], "debrief": "'More than two' is part of India's own history and law.", "persona": "India", "source": "hijra history / NALSA", "relearn": "'More than two' is part of India's own history and law."},
  {"id": "wm-1229", "cat": "many-ways", "type": "branch", "hook": "Your sister says a friend who uses 'they' is 'just confused'.", "options": [{"text": "\"They know themselves; we can just use 'they'.\"", "consequence": "She nods and tries it kindly.", "best": true}, {"text": "\"Yeah, they're confused.\"", "consequence": "The unkind idea gets repeated."}, {"text": "\"Whatever, not my problem.\"", "consequence": "Nobody learns the kind way."}], "debrief": "Only you know yourself; using someone's word is kind.", "persona": "respect", "source": "respect / voice", "relearn": "Only you know yourself; using someone's word is kind."},
  {"id": "wm-1230", "cat": "many-ways", "type": "build", "prompt": "Build a welcome for a new friend who feels like neither a boy nor a girl. Pick the kind pieces.", "pieces": ["Say a warm hello", "Ask their name", "Use the words they ask for", "Invite them to play", "Tell them to pick a side", "Say they're being silly"], "mode": "assemble", "key": ["Say a warm hello", "Ask their name", "Use the words they ask for", "Invite them to play"], "relearn": "A kind welcome uses someone's words and includes them.", "persona": "respect", "source": "respect / voice", "hook": "Build a warm welcome for a new friend."},
  {"id": "wm-1231", "cat": "many-ways", "type": "build", "prompt": "Build a 'many ways to be a boy' poster. Pick the true pieces.", "pieces": ["A boy who dances", "A boy who paints", "A boy who is gentle", "A boy who leads", "Only one kind of boy", "A boy who can't cry"], "mode": "assemble", "key": ["A boy who dances", "A boy who paints", "A boy who is gentle", "A boy who leads"], "relearn": "There are many ways to be a boy.", "persona": "Faizan-type", "source": "gender norms", "hook": "Build a 'many ways to be a boy' poster. Pick the true pieces."},
  {"id": "wm-1232", "cat": "many-ways", "type": "build", "prompt": "Build a 'many ways to be a girl' poster. Pick the true pieces.", "pieces": ["A girl who builds", "A girl who leads", "A girl who plays sport", "A girl who is bold", "Only one kind of girl", "A girl must stay quiet"], "mode": "assemble", "key": ["A girl who builds", "A girl who leads", "A girl who plays sport", "A girl who is bold"], "relearn": "There are many ways to be a girl.", "persona": "Ananya", "source": "gender norms", "hook": "Build a 'many ways to be a girl' poster. Pick the true pieces."},
  {"id": "wm-1233", "cat": "many-ways", "type": "build", "prompt": "Build the India 'more than two' fact-board. Pick the true pieces.", "pieces": ["Hijras, here for ages", "A third gender in law", "Part of our own stories", "NALSA, 2014", "An idea from outside India", "India only knew two"], "mode": "assemble", "key": ["Hijras, here for ages", "A third gender in law", "Part of our own stories", "NALSA, 2014"], "relearn": "'More than two' is part of India's own history and law.", "persona": "India", "source": "hijra history / NALSA", "hook": "Build the India 'more than two' fact-board. Pick the true pieces."},
  {"id": "wm-1234", "cat": "many-ways", "type": "build", "prompt": "Put the steps for being a kind ally in order, first to last.", "pieces": ["Notice the teasing", "Say 'stop, that's not kind'", "Stand next to the friend", "Invite them to play with you"], "mode": "sequence", "key": ["Notice the teasing", "Say 'stop, that's not kind'", "Stand next to the friend", "Invite them to play with you"], "relearn": "Notice, speak up, stand with, include, that's being an ally.", "persona": "ally seed", "source": "respect / voice", "hook": "Put the steps for being a kind ally in order, first to last."},
  {"id": "wm-1235", "cat": "many-ways", "type": "build", "prompt": "Build the 'every way is okay' wall. Pick the pieces that belong.", "pieces": ["A boy who dances", "Someone who uses 'they'", "A girl who plays cricket", "Someone who feels like both", "Saying 'you're made wrong'", "'Only two kinds exist'"], "mode": "assemble", "key": ["A boy who dances", "Someone who uses 'they'", "A girl who plays cricket", "Someone who feels like both"], "relearn": "Every way of being a person is real and okay.", "persona": "gender thread", "source": "gender diversity", "hook": "Build the 'every way is okay' wall. Pick the pieces that belong."},
  {"id": "wm-1236", "cat": "many-ways", "type": "build", "prompt": "Put the steps for meeting a new friend who uses 'they' in order.", "pieces": ["Say hello", "Ask their name", "Hear that they use 'they'", "Use 'they' kindly"], "mode": "sequence", "key": ["Say hello", "Ask their name", "Hear that they use 'they'", "Use 'they' kindly"], "relearn": "Hear someone's word for themselves, then use it kindly.", "persona": "respect", "source": "respect / voice", "hook": "Put the steps for meeting a new friend who uses 'they' in order."},
  {"id": "wm-1237", "cat": "many-ways", "type": "build", "prompt": "Build a 'we all belong' classroom box. Pick the welcoming pieces.", "pieces": ["Quiet kids welcome", "Loud kids welcome", "Kids who feel like both welcome", "Everyone welcome here", "Only one kind of kid", "Some kids don't belong"], "mode": "assemble", "key": ["Quiet kids welcome", "Loud kids welcome", "Kids who feel like both welcome", "Everyone welcome here"], "relearn": "There are many ways to be, and everyone belongs.", "persona": "any", "source": "diversity", "hook": "Build a 'we all belong' classroom box. Pick the welcoming pieces."},
  {"id":"wm-1080","cat":"not-what-you-like","type":"strike-rewrite","hook":"\"Boys can't wear bangles for Diwali.\"","myth":{"un":"A boy who wears bangles isn't really a boy.","re":"Wearing bangles doesn't change who a boy is inside.","why":"Bangles are jewellery, not a gender."},"relearn":"What you wear doesn't change who you are inside.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1081","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl loves climbing trees and getting muddy.","myth":{"un":"Climbing and mud mean she isn't really a girl.","re":"Playing rough doesn't change that she's a girl.","why":"Climbing is a game, not a gender."},"relearn":"What you play doesn't change who you are inside.","persona":"Ananya","source":"gender vs expression"},
  {"id":"wm-1082","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy helps his mother cook roti.","myth":{"un":"A boy who cooks is turning into a girl.","re":"Cooking doesn't change that he's a boy.","why":"Cooking is a skill anyone can have."},"relearn":"Helping in the kitchen doesn't decide your gender.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-1083","cat":"not-what-you-like","type":"strike-rewrite","hook":"\"Girls can't be good at maths.\"","myth":{"un":"Being best at maths makes a girl 'not a real girl'.","re":"Being great at maths doesn't change that she's a girl.","why":"Maths has no gender; anyone can be good at it."},"relearn":"What you're good at doesn't decide your gender.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1084","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy's favourite colour is purple.","myth":{"un":"Purple is a girl colour, so he can't like it.","re":"Any colour can be anyone's favourite.","why":"Colours don't belong to a gender."},"relearn":"Liking a colour doesn't change who you are inside.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1085","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl wants the toy car, not the doll.","myth":{"un":"Wanting a car instead of a doll means she's really a boy.","re":"Liking a toy car doesn't change that she's a girl.","why":"Toys are for whoever enjoys them."},"relearn":"Toys don't decide your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1086","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy loves Bharatanatyam dance class.","myth":{"un":"Dancing like that turns a boy into a girl.","re":"Loving to dance doesn't change that he's a boy.","why":"Dance is for everyone who loves it."},"relearn":"What you love to do doesn't decide your gender.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-1087","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl keeps her hair very short for summer.","myth":{"un":"Short hair means she stopped being a girl.","re":"Short hair doesn't change that she's a girl.","why":"Hair length is a choice, not a gender."},"relearn":"Your haircut doesn't decide who you are inside.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1088","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy plays with his sister's kitchen set.","myth":{"un":"That toy is 'for girls', so it changes him.","re":"A toy kitchen doesn't change who he is inside.","why":"No toy belongs to only one gender."},"relearn":"No toy can change who you are inside.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1089","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl is the loudest cheerleader at kabaddi.","myth":{"un":"Being loud and bold means she's not a proper girl.","re":"Being loud and bold doesn't change that she's a girl.","why":"There's no one quiet way to be a girl."},"relearn":"How loud or bold you are doesn't decide your gender.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1090","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy carries a bright pink water bottle to school.","myth":{"un":"A pink bottle makes the other kids call him a girl.","re":"A pink bottle doesn't change that he's a boy.","why":"It's just a bottle in a colour he likes."},"relearn":"The colour of your things doesn't decide your gender.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-1091","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl skips dolls and builds with blocks all day.","myth":{"un":"Building things is a boy thing she shouldn't enjoy.","re":"Building doesn't change that she's a girl.","why":"Blocks are for any kid who likes to build."},"relearn":"What you build or make doesn't decide your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1092","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy hugs his soft toy elephant to sleep.","myth":{"un":"Big boys with soft toys aren't really boys.","re":"Loving a soft toy doesn't change that he's a boy.","why":"Comfort toys are for any age and any kid."},"relearn":"Liking a soft toy doesn't decide your gender.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-1093","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl wears her brother's old shorts to play.","myth":{"un":"Wearing 'boy clothes' means she's turning into a boy.","re":"Shorts don't change that she's a girl.","why":"Clothes are just clothes, not a gender."},"relearn":"Clothes don't decide who you are inside.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1094","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy paints his nails the way his didi does.","myth":{"un":"Painted nails turn a boy into a girl.","re":"Painted nails don't change that he's a boy.","why":"Nail colour is decoration, not a gender."},"relearn":"How you decorate yourself doesn't decide your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1095","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl plays goalkeeper in the street football game.","myth":{"un":"Football is for boys, so it makes her one.","re":"Playing football doesn't change that she's a girl.","why":"Any sport is for any kid who wants to play."},"relearn":"The games you play don't decide your gender.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1096","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy gets scared of the dark and says so.","myth":{"un":"A boy who feels scared is acting like a girl.","re":"Feeling scared doesn't change that he's a boy.","why":"Every kid feels scared sometimes."},"relearn":"Feelings aren't a gender; everyone has them.","persona":"Faizan-type","source":"links g01"},
  {"id":"wm-1097","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl never cries, even when she falls hard.","myth":{"un":"A girl who doesn't cry isn't really a girl.","re":"Crying or not crying doesn't change that she's a girl.","why":"Tears or no tears, feelings aren't a gender."},"relearn":"Whether you cry doesn't decide your gender.","persona":"Ananya","source":"links g01"},
  {"id":"wm-1098","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy sings the sweetest in the school choir.","myth":{"un":"Singing sweetly is a girl thing, so he isn't a real boy.","re":"Singing sweetly doesn't change that he's a boy.","why":"A voice you love using has no gender."},"relearn":"What you're good at doesn't decide your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1099","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl wants a haircut like her favourite cricketer.","myth":{"un":"That 'boy haircut' will stop her being a girl.","re":"A new haircut doesn't change that she's a girl.","why":"A haircut is a style, not a gender."},"relearn":"A haircut can't change who you are inside.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1100","cat":"not-what-you-like","type":"strike-rewrite","hook":"A boy loves rangoli and flower garlands.","myth":{"un":"Liking pretty rangoli makes a boy a girl.","re":"Loving rangoli doesn't change that he's a boy.","why":"Art and beauty are for everyone."},"relearn":"What you find beautiful doesn't decide your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1101","cat":"not-what-you-like","type":"strike-rewrite","hook":"A girl is captain and gives all the orders in games.","myth":{"un":"Being a bossy leader makes her 'like a boy'.","re":"Leading the team doesn't change that she's a girl.","why":"Leaders can be any gender."},"relearn":"Being a leader doesn't decide your gender.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1102","cat":"not-what-you-like","type":"strike-rewrite","hook":"\"If you like both boy things and girl things, you're confused.\"","myth":{"un":"Liking both 'boy' and 'girl' things means you're confused.","re":"Liking lots of different things is normal and fine.","why":"Things don't really belong to a gender at all."},"relearn":"You can like all sorts of things; that's just being you.","persona":"gender thread","source":"gender vs expression"},
  {"id":"wm-1103","cat":"not-what-you-like","type":"sort","hook":"Sort: does this decide your gender, or is it just what you like?","items":[{"id":"a","text":"Liking the colour blue"},{"id":"b","text":"Who you know you are inside"},{"id":"c","text":"Loving cricket"},{"id":"d","text":"Your favourite snack"},{"id":"e","text":"Wearing a kurta"},{"id":"f","text":"Liking to dance"}],"bins":[{"id":"gender","label":"Decides your gender","valence":"neutral"},{"id":"like","label":"Just what you like","valence":"neutral"}],"key":{"a":"like","b":"gender","c":"like","d":"like","e":"like","f":"like"},"relearn":"Only who you know you are inside is your gender; the rest is just what you like.","persona":"gender thread","source":"UNESCO 3.1"},
  {"id":"wm-1104","cat":"not-what-you-like","type":"sort","hook":"Sort each one: is it just a hobby, or is it who you are inside?","items":[{"id":"a","text":"Playing football"},{"id":"b","text":"Drawing pictures"},{"id":"c","text":"Who you know you are inside"},{"id":"d","text":"Dancing garba"},{"id":"e","text":"Singing songs"},{"id":"f","text":"Climbing trees"}],"bins":[{"id":"hobby","label":"Just a hobby","valence":"neutral"},{"id":"inside","label":"Who you are inside","valence":"neutral"}],"key":{"a":"hobby","b":"hobby","c":"inside","d":"hobby","e":"hobby","f":"hobby"},"relearn":"Hobbies are fun things you do; only the inside-you is your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1105","cat":"not-what-you-like","type":"sort","hook":"Sort: is it just clothing, or is it who you are inside?","items":[{"id":"a","text":"A frock"},{"id":"b","text":"Shorts"},{"id":"c","text":"A kurta-pyjama"},{"id":"d","text":"A sari"},{"id":"e","text":"A cap"},{"id":"f","text":"Who you know you are inside"}],"bins":[{"id":"clothes","label":"Just clothing","valence":"neutral"},{"id":"inside","label":"Who you are inside","valence":"neutral"}],"key":{"a":"clothes","b":"clothes","c":"clothes","d":"clothes","e":"clothes","f":"inside"},"relearn":"Clothes are things you put on; only the inside-you is your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1106","cat":"not-what-you-like","type":"sort","hook":"Sort: just a colour you like, or who you are inside?","items":[{"id":"a","text":"Pink"},{"id":"b","text":"Blue"},{"id":"c","text":"Green"},{"id":"d","text":"Who you know you are inside"},{"id":"e","text":"Purple"},{"id":"f","text":"Yellow"}],"bins":[{"id":"colour","label":"Just a colour","valence":"neutral"},{"id":"inside","label":"Who you are inside","valence":"neutral"}],"key":{"a":"colour","b":"colour","c":"colour","d":"inside","e":"colour","f":"colour"},"relearn":"Every colour is for everyone; only the inside-you is your gender.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-1107","cat":"not-what-you-like","type":"sort","hook":"Sort: just a feeling, or who you are inside?","items":[{"id":"a","text":"Feeling happy"},{"id":"b","text":"Feeling scared"},{"id":"c","text":"Crying when sad"},{"id":"d","text":"Feeling angry"},{"id":"e","text":"Who you know you are inside"},{"id":"f","text":"Feeling shy"}],"bins":[{"id":"feeling","label":"Just a feeling","valence":"neutral"},{"id":"inside","label":"Who you are inside","valence":"neutral"}],"key":{"a":"feeling","b":"feeling","c":"feeling","d":"feeling","e":"inside","f":"feeling"},"relearn":"Everyone has all the feelings; only the inside-you is your gender.","persona":"any","source":"links g01"},
  {"id":"wm-1108","cat":"not-what-you-like","type":"sort","hook":"Sort: just a toy, or who you are inside?","items":[{"id":"a","text":"A doll"},{"id":"b","text":"A toy car"},{"id":"c","text":"Building blocks"},{"id":"d","text":"A cricket bat"},{"id":"e","text":"A kitchen set"},{"id":"f","text":"Who you know you are inside"}],"bins":[{"id":"toy","label":"Just a toy","valence":"neutral"},{"id":"inside","label":"Who you are inside","valence":"neutral"}],"key":{"a":"toy","b":"toy","c":"toy","d":"toy","e":"toy","f":"inside"},"relearn":"Toys are for any kid who enjoys them; only the inside-you is your gender.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1109","cat":"not-what-you-like","type":"sort","hook":"Sort: things anyone can like, vs the one thing that's your gender.","items":[{"id":"a","text":"Mehndi on your hands"},{"id":"b","text":"Long or short hair"},{"id":"c","text":"Bangles"},{"id":"d","text":"Who you know you are inside"},{"id":"e","text":"Painted nails"},{"id":"f","text":"Wearing a cap"}],"bins":[{"id":"anyone","label":"Anyone can like","valence":"neutral"},{"id":"inside","label":"Who you are inside","valence":"neutral"}],"key":{"a":"anyone","b":"anyone","c":"anyone","d":"inside","e":"anyone","f":"anyone"},"relearn":"Looks and decorations are for anyone; only the inside-you is your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1110","cat":"not-what-you-like","type":"sort","hook":"Sort: just something you're good at, or who you are inside?","items":[{"id":"a","text":"Good at maths"},{"id":"b","text":"Good at cooking"},{"id":"c","text":"Good at running"},{"id":"d","text":"Good at singing"},{"id":"e","text":"Who you know you are inside"},{"id":"f","text":"Good at drawing"}],"bins":[{"id":"skill","label":"Just a skill","valence":"neutral"},{"id":"inside","label":"Who you are inside","valence":"neutral"}],"key":{"a":"skill","b":"skill","c":"skill","d":"skill","e":"inside","f":"skill"},"relearn":"Any skill is open to anyone; only the inside-you is your gender.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1111","cat":"not-what-you-like","type":"sort","hook":"Sort: does it change your gender, or change nothing about it?","items":[{"id":"a","text":"Getting a new haircut"},{"id":"b","text":"Trying a new sport"},{"id":"c","text":"Wearing a new outfit"},{"id":"d","text":"Liking a new colour"},{"id":"e","text":"Picking a new hobby"},{"id":"f","text":"Who you know you are inside"}],"bins":[{"id":"nope","label":"Changes nothing","valence":"neutral"},{"id":"isgender","label":"Is your gender","valence":"neutral"}],"key":{"a":"nope","b":"nope","c":"nope","d":"nope","e":"nope","f":"isgender"},"relearn":"None of those change your gender; only who you are inside is your gender, and it stays steady.","persona":"gender thread","source":"gender stability"},
  {"id":"wm-1112","cat":"not-what-you-like","type":"branch","hook":"A kid says you can't pick the pink box because of your gender.","options":[{"text":"Say \"I'll pick the colour I like\"","consequence":"You take the pink box and enjoy it; the rule was silly.","outcome":"assertive","best":true},{"text":"Pick a different colour so no one teases","consequence":"You give up your favourite over a wrong idea.","outcome":"missed"}],"debrief":"A colour is just a colour; it doesn't decide your gender.","relearn":"You can like any colour, whatever your gender.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1113","cat":"not-what-you-like","type":"branch","hook":"Friends laugh that a boy joined the dance, not the cricket.","options":[{"text":"Tell them \"dancing is great and he's still himself\"","consequence":"He keeps dancing happily; the teasing fades.","outcome":"ally","best":true},{"text":"Join the laughing so they include you","consequence":"A friend feels small for loving something fun.","outcome":"missed"}],"debrief":"Dance doesn't change who he is; backing a friend is kind.","relearn":"What you love to do doesn't decide your gender.","persona":"ally seed","source":"gender vs expression / bystander"},
  {"id":"wm-1114","cat":"not-what-you-like","type":"branch","hook":"A girl is told she can't be goalkeeper because she's a girl.","options":[{"text":"Say \"girls play too\" and take the spot","consequence":"She plays a great game; the rule made no sense.","outcome":"assertive","best":true},{"text":"Sit out so no one argues","consequence":"She misses out on a game she'd love over an unfair rule.","outcome":"missed"}],"debrief":"Any sport is for any kid; football doesn't decide gender.","relearn":"The games you play don't decide your gender.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1115","cat":"not-what-you-like","type":"branch","hook":"Someone says your new short haircut makes you 'not a girl anymore'.","options":[{"text":"Smile and say \"I'm still me, just with new hair\"","consequence":"You feel calm and proud; nothing about you changed.","outcome":"assertive","best":true},{"text":"Worry all day that your hair changed you","consequence":"You carry a worry that simply isn't true.","outcome":"missed"}],"debrief":"A haircut is a style; who you are inside stays the same.","relearn":"A haircut can't change who you are inside.","persona":"be-yourself","source":"gender vs expression"},
  {"id":"wm-1116","cat":"not-what-you-like","type":"branch","hook":"A cousin teases a boy for carrying a flowery umbrella.","options":[{"text":"Say \"it's just an umbrella I like\" and keep it","consequence":"He stays dry and happy; the tease lands flat.","outcome":"assertive","best":true},{"text":"Hide the umbrella and get wet","consequence":"He gives up something useful over a silly comment.","outcome":"missed"}],"debrief":"An umbrella's pattern doesn't decide anyone's gender.","relearn":"The look of your things doesn't decide your gender.","persona":"Faizan-type","source":"gender vs expression"},
  {"id":"wm-1117","cat":"not-what-you-like","type":"branch","hook":"At a stall you both want the same bright bag; a kid says it's 'for girls'.","options":[{"text":"Say \"bags don't belong to a gender\" and buy it","consequence":"You carry the bag you love; the rule was made up.","outcome":"assertive","best":true},{"text":"Swap for a 'boy' bag you don't like","consequence":"You end up with something you didn't even want.","outcome":"missed"}],"debrief":"No object belongs to one gender; pick what you like.","relearn":"Things don't have a gender; you can like any of them.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1118","cat":"not-what-you-like","type":"branch","hook":"A boy in class admits he likes the doll corner best.","options":[{"text":"Say \"that's a fun corner\" and play with him","consequence":"He relaxes and you both have a great time.","outcome":"ally","best":true},{"text":"Whisper that dolls will 'turn him into a girl'","consequence":"He feels ashamed of something harmless.","outcome":"missed"}],"debrief":"A toy can't change who he is; including him is kind.","relearn":"No toy can change who you are inside.","persona":"ally seed","source":"gender vs expression"},
  {"id":"wm-1119","cat":"not-what-you-like","type":"branch","hook":"A girl is best at maths and a boy says she's 'showing off like a boy'.","options":[{"text":"Say \"I just like maths\" and keep raising her hand","consequence":"She keeps shining; the comment doesn't slow her down.","outcome":"assertive","best":true},{"text":"Stop answering so she won't stand out","consequence":"She hides a strength over an unfair idea.","outcome":"missed"}],"debrief":"Being good at maths doesn't change that she's a girl.","relearn":"What you're good at doesn't decide your gender.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1120","cat":"not-what-you-like","type":"branch","hook":"Kids dare a boy to prove he's a boy by not crying at a sad film.","options":[{"text":"Say \"crying is fine; I'm a boy either way\"","consequence":"He watches freely; he never had to prove anything.","outcome":"assertive","best":true},{"text":"Hold back tears to pass their 'test'","consequence":"He bottles up feelings over a wrong idea.","outcome":"missed"}],"debrief":"You never have to prove your gender; feelings aren't a test.","relearn":"Feelings aren't a gender, and you never have to prove who you are.","persona":"be-yourself","source":"links g01"},
  {"id":"wm-1121","cat":"not-what-you-like","type":"role-play","hook":"A classmate says your friend can't like pink because he's a boy.","setup":"Stand up for him. Say:","yourLine":[{"text":"\"Pink is just a colour; he's still exactly who he is.\"","best":true},{"text":"\"Yeah, pink is a bit girly...\""}],"relearn":"Liking a colour doesn't change who you are inside.","persona":"ally seed","source":"gender vs expression / voice"},
  {"id":"wm-1122","cat":"not-what-you-like","type":"role-play","hook":"Someone tells a girl she's 'too rough' to really be a girl.","setup":"Back her up. Say:","yourLine":[{"text":"\"Playing rough doesn't change that she's a girl.\"","best":true},{"text":"\"Maybe play calmer so they stop.\""}],"relearn":"How you play doesn't decide your gender.","persona":"Ananya","source":"links g04 / voice"},
  {"id":"wm-1123","cat":"not-what-you-like","type":"role-play","hook":"A kid is teased for bringing a doll to show-and-tell.","setup":"Be the kind voice. Say:","yourLine":[{"text":"\"Cool doll! Toys are for anyone who likes them.\"","best":true},{"text":"Stay quiet so they don't tease you too."}],"relearn":"Toys don't decide your gender.","persona":"ally seed","source":"gender vs expression / voice"},
  {"id":"wm-1124","cat":"not-what-you-like","type":"role-play","hook":"Your friend frets that his nail polish makes him 'not a boy'.","setup":"Reassure him. Say:","yourLine":[{"text":"\"Painted nails don't change anything; you're still you.\"","best":true},{"text":"\"Maybe wipe it off, just in case.\""}],"relearn":"How you decorate yourself doesn't decide your gender.","persona":"be-yourself","source":"gender vs expression / voice"},
  {"id":"wm-1125","cat":"not-what-you-like","type":"role-play","hook":"A boy worries that loving to sing makes the others doubt him.","setup":"Cheer him on. Say:","yourLine":[{"text":"\"You sing beautifully, and you're every bit a boy.\"","best":true},{"text":"\"Sing softer so nobody hears.\""}],"relearn":"What you're good at doesn't decide your gender.","persona":"be-yourself","source":"gender vs expression / voice"},
  {"id":"wm-1126","cat":"not-what-you-like","type":"role-play","hook":"Someone says a girl can't be team captain like a boy.","setup":"Speak up for her. Say:","yourLine":[{"text":"\"Captains can be any gender; she leads great.\"","best":true},{"text":"\"Let a boy be captain instead.\""}],"relearn":"Being a leader doesn't decide your gender.","persona":"Ananya","source":"links g04 / voice"},
  {"id":"wm-1127","cat":"not-what-you-like","type":"role-play","hook":"A friend is told cooking with his nani is 'a girl's job'.","setup":"Set it straight. Say:","yourLine":[{"text":"\"Cooking is a great skill for anyone.\"","best":true},{"text":"\"Maybe just watch, don't help.\""}],"relearn":"What you do at home doesn't decide your gender.","persona":"any","source":"gender vs expression / voice"},
  {"id":"wm-1128","cat":"not-what-you-like","type":"reflect","hook":"Lensy: can a boy AND a girl both love the colour pink?","prompt":"What do you think?","options":["Yes, colours are for everyone","Of course they can","Pink is just a colour"],"affirm":"Yes! Any colour is for anyone; it never changes who you are.","relearn":"Colours are for everyone; they don't decide your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1129","cat":"not-what-you-like","type":"reflect","hook":"Lensy: if you try a brand-new hobby, does your gender change?","prompt":"What do you think?","options":["No, it stays the same","A hobby is just for fun","Who I am stays steady"],"affirm":"Right, a new hobby is fun, and the inside-you stays exactly the same.","relearn":"Hobbies don't change who you are inside.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1130","cat":"not-what-you-like","type":"reflect","hook":"Lensy: who gets to decide what toys you enjoy?","prompt":"What do you think?","options":["Me","Whoever's playing","Anyone who likes the toy"],"affirm":"You do: toys are for whoever enjoys them, and they don't decide your gender.","relearn":"You choose your toys; they don't decide your gender.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1131","cat":"not-what-you-like","type":"reflect","hook":"Lensy: your gender is decided by...?","prompt":"Finish the thought.","options":["who I know I am inside","not my clothes or hair","not the games I play"],"affirm":"Your gender is who you know you are inside, not your clothes, hair or games.","relearn":"Gender is who you are inside, not what you like or wear.","persona":"gender thread","source":"UNESCO 3.1"},
  {"id":"wm-1132","cat":"not-what-you-like","type":"reflect","hook":"Lensy: if a girl loves cricket, what does that tell you?","prompt":"What do you think?","options":["She loves cricket","She's a girl who loves cricket","People can love anything"],"affirm":"It tells you she loves cricket, and she's still a girl. Liking a sport changes nothing.","relearn":"What you love doesn't change who you are inside.","persona":"Ananya","source":"links g04"},
  {"id":"wm-1133","cat":"not-what-you-like","type":"reflect","hook":"Lensy: can you like 'boy things' and 'girl things' at the same time?","prompt":"What do you think?","options":["Yes, they're just things","Sure, anything I like","Things have no gender"],"affirm":"Yes, like anything you want; things don't really belong to a gender at all.","relearn":"You can like all sorts of things; they're just things.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1134","cat":"not-what-you-like","type":"reflect","hook":"Lensy: a boy who cries at a sad story, what is he?","prompt":"What do you think?","options":["Still a boy","A boy with feelings","Just a kid feeling sad"],"affirm":"Still a boy with feelings, and everyone has feelings; they aren't a gender.","relearn":"Feelings aren't a gender; everyone has them.","persona":"any","source":"links g01"},
  {"id":"wm-1135","cat":"not-what-you-like","type":"reflect","hook":"Lensy: do you ever have to prove your gender to anyone?","prompt":"What do you think?","options":["No, never","I just know who I am","Only I know me best"],"affirm":"No, you never have to prove who you are; only you know yourself best.","relearn":"You never have to prove who you are.","persona":"be-yourself","source":"self-knowledge"},
  {"id":"wm-1136","cat":"not-what-you-like","type":"reflect","hook":"Lensy: name something you love that 'people say' isn't for your gender.","prompt":"Think of one: there's no wrong answer.","options":["A colour I love","A game I love","A song or dance I love"],"affirm":"Whatever you picked, it's yours to love, and it doesn't change who you are inside.","relearn":"What you love is yours, and it doesn't decide your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1137","cat":"not-what-you-like","type":"match","hook":"Match what someone likes to the true thing about them.","pairs":[{"left":"A boy who loves pink","right":"is still a boy"},{"left":"A girl who loves football","right":"is still a girl"},{"left":"A boy who loves to dance","right":"is exactly who he is"},{"left":"A girl with short hair","right":"is exactly who she is"},{"left":"A kid who likes both","right":"is just being themselves"}],"relearn":"What you like doesn't change who you are inside.","persona":"gender thread","source":"gender vs expression"},
  {"id":"wm-1138","cat":"not-what-you-like","type":"match","hook":"Match each thing to what it really is (not a gender).","pairs":[{"left":"A favourite colour","right":"just a colour"},{"left":"A haircut","right":"just a style"},{"left":"A toy","right":"just something fun"},{"left":"An outfit","right":"just clothes"},{"left":"Who you are inside","right":"your real gender"}],"relearn":"Likes are just likes; only the inside-you is your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1139","cat":"not-what-you-like","type":"match","hook":"Match the kid to the thing they enjoy: all still themselves.","pairs":[{"left":"Reyansh likes purple","right":"a colour he enjoys"},{"left":"Ananya plays kabaddi","right":"a sport she enjoys"},{"left":"Faizan loves dancing","right":"something he enjoys"},{"left":"Meera builds with blocks","right":"a hobby she enjoys"},{"left":"Arjun cooks with dad","right":"a skill he enjoys"}],"relearn":"Everyone enjoys different things, and none of it changes who they are.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1140","cat":"not-what-you-like","type":"match","hook":"Match the teasing myth to the kind, true reply.","pairs":[{"left":"\"Pink isn't for boys\"","right":"\"Colours are for everyone\""},{"left":"\"Football isn't for girls\"","right":"\"Any sport is for any kid\""},{"left":"\"Boys can't cry\"","right":"\"Everyone has feelings\""},{"left":"\"Dolls will change him\"","right":"\"Toys can't change who you are\""},{"left":"\"Prove you're a boy\"","right":"\"Nobody has to prove that\""}],"relearn":"For every silly myth there's a kind, true thing to say back.","persona":"ally seed","source":"gender vs expression"},
  {"id":"wm-1141","cat":"not-what-you-like","type":"match","hook":"Match each item to where it belongs in your life.","pairs":[{"left":"Your clothes","right":"on your body"},{"left":"Your hobbies","right":"how you have fun"},{"left":"Your favourite colour","right":"things you like"},{"left":"Your skills","right":"things you can do"},{"left":"Who you are inside","right":"only you know best"}],"relearn":"Lots of parts make you, you; only the inside-you is your gender.","persona":"any","source":"self-concept"},
  {"id":"wm-1142","cat":"not-what-you-like","type":"match","hook":"Match the question to the honest answer.","pairs":[{"left":"Does a haircut change you?","right":"No, you're still you"},{"left":"Does a new toy change you?","right":"No, it's just for fun"},{"left":"Does a colour change you?","right":"No, it's just a colour"},{"left":"Does a sport change you?","right":"No, it's just a game"},{"left":"What decides your gender?","right":"Who you know you are"}],"relearn":"Nothing you like or wear changes who you are inside.","persona":"gender thread","source":"gender stability"},
  {"id":"wm-1143","cat":"not-what-you-like","type":"match","hook":"Match the kind word to the friend who needs it.","pairs":[{"left":"To a teased dancer","right":"\"Dance on, you're great\""},{"left":"To a pink-loving boy","right":"\"Nice colour choice!\""},{"left":"To a football-mad girl","right":"\"Play your game!\""},{"left":"To a boy who cries","right":"\"Feelings are okay\""},{"left":"To anyone unsure","right":"\"You're good as you are\""}],"relearn":"A kind word helps a friend stay proud of what they love.","persona":"ally seed","source":"gender vs expression"},
  {"id":"wm-1144","cat":"not-what-you-like","type":"match","hook":"Match each 'just a' thing to a 'who you are' thing.","pairs":[{"left":"Just a hairstyle","right":"Always yourself"},{"left":"Just a hobby","right":"Steady inside-you"},{"left":"Just an outfit","right":"The real you stays"},{"left":"Just a snack you love","right":"Still completely you"},{"left":"Just a colour","right":"You, unchanged"}],"relearn":"The little 'just-a' things change; the inside-you stays steady.","persona":"any","source":"gender stability"},
  {"id":"wm-1145","cat":"not-what-you-like","type":"build","hook":"Build a reply for when a friend hears \"pink isn't for boys\".","prompt":"Pick the parts of a kind, true reply.","pieces":["Pink is just a colour","Colours are for everyone","You're still exactly you","liking it changes nothing"],"mode":"assemble","key":["Pink is just a colour","Colours are for everyone","You're still exactly you","liking it changes nothing"],"relearn":"Liking a colour doesn't change who you are inside.","persona":"ally seed","source":"gender vs expression"},
  {"id":"wm-1146","cat":"not-what-you-like","type":"build","hook":"Build the list of things that are 'just what you like'.","prompt":"Drag in the things that are only preferences, not your gender.","pieces":["my favourite colour","my hobbies","my haircut","my clothes","the games I play"],"mode":"assemble","key":["my favourite colour","my hobbies","my haircut","my clothes","the games I play"],"relearn":"All of these are just what you like; only the inside-you is your gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1147","cat":"not-what-you-like","type":"build","hook":"Build the calm steps when someone says your hobby changed your gender.","prompt":"Put the steps in order.","pieces":["Hear what they said","Remember it isn't true","Say \"I'm still me\"","Keep enjoying my hobby"],"mode":"sequence","key":["Hear what they said","Remember it isn't true","Say \"I'm still me\"","Keep enjoying my hobby"],"relearn":"A hobby never changes who you are inside; stay calm and stay you.","persona":"be-yourself","source":"gender vs expression"},
  {"id":"wm-1148","cat":"not-what-you-like","type":"build","hook":"Build the truth: \"My gender is decided by ___, not by ___.\"","prompt":"Pick the pieces that finish it truly.","pieces":["who I know I am inside","not my clothes","not my hair","not the toys I like","not my favourite colour"],"mode":"assemble","key":["who I know I am inside","not my clothes","not my hair","not the toys I like","not my favourite colour"],"relearn":"Your gender is who you are inside, not the things you like or wear.","persona":"gender thread","source":"UNESCO 3.1"},
  {"id":"wm-1149","cat":"not-what-you-like","type":"build","hook":"Build a fair playtime where everyone picks what they enjoy.","prompt":"Add the rules that keep it open to all.","pieces":["Any toy for any kid","Any colour for anyone","Any game for everyone","No \"that's not for you\""],"mode":"assemble","key":["Any toy for any kid","Any colour for anyone","Any game for everyone","No \"that's not for you\""],"relearn":"When things aren't 'for' a gender, every kid gets to enjoy them.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1150","cat":"not-what-you-like","type":"build","hook":"Build the steps to back up a friend who's teased for what they love.","prompt":"Put the ally steps in order.","pieces":["Notice they feel small","Step beside them","Say \"that's great, and you're still you\"","Play along with them"],"mode":"sequence","key":["Notice they feel small","Step beside them","Say \"that's great, and you're still you\"","Play along with them"],"relearn":"Backing a friend up shows what they love doesn't change who they are.","persona":"ally seed","source":"gender vs expression / bystander"},
  {"id":"wm-1151","cat":"not-what-you-like","type":"build","hook":"Build a 'these can't change me' shield from true reminders.","prompt":"Pick the reminders that belong on your shield.","pieces":["colours can't change me","toys can't change me","clothes can't change me","only I know who I am"],"mode":"assemble","key":["colours can't change me","toys can't change me","clothes can't change me","only I know who I am"],"relearn":"None of the things you like can change who you are inside.","persona":"be-yourself","source":"gender stability"},
  {"id":"wm-1152","cat":"not-what-you-like","type":"build","hook":"Build the answer to \"why can a girl love cricket?\"","prompt":"Pick the true reasons.","pieces":["Sports are for everyone","Liking it changes nothing","She's still a girl","Anyone can love a game"],"mode":"assemble","key":["Sports are for everyone","Liking it changes nothing","She's still a girl","Anyone can love a game"],"relearn":"What you love doesn't change who you are inside.","persona":"Ananya","source":"links g04"},
  {"id":"wm-900","cat":"parts-of-me","type":"build","hook":"Lensy: build a 'this is me' poster for your room.","prompt":"Drag the parts that belong on your me-poster.","pieces":["my name","games I love","my biggest laugh","my family","who I am inside","my favourite food"],"mode":"assemble","key":["my name","games I love","my biggest laugh","my family","who I am inside","my favourite food"],"relearn":"Many parts together make one you, and your gender is just one of them.","persona":"any","source":"self-concept"},
  {"id":"wm-901","cat":"parts-of-me","type":"build","hook":"Build a friendship card that says who you are.","prompt":"Add the parts you'd tell a new friend about you.","pieces":["my name","what I'm good at","what makes me laugh","who I am inside"],"mode":"assemble","key":["my name","what I'm good at","what makes me laugh","who I am inside"],"relearn":"You get to choose which of your many parts to share.","persona":"any","source":"self-expression"},
  {"id":"wm-902","cat":"parts-of-me","type":"build","hook":"Reyansh wants to add 'who I am inside' to his collage.","prompt":"Place it among his other parts (one of many).","pieces":["I'm a boy, and that's me","plus the cricket I love","plus my big laugh","plus my whole family"],"mode":"assemble","key":["I'm a boy, and that's me","plus the cricket I love","plus my big laugh","plus my whole family"],"relearn":"Who you are inside is one important part of you, among many.","persona":"Reyansh","source":"identity facets"},
  {"id":"wm-903","cat":"parts-of-me","type":"build","hook":"Ananya makes a 'me jar' to keep all her parts in.","prompt":"Drop in the parts that make Ananya, Ananya.","pieces":["her name","her sense of fair play","the dance she loves","who she knows she is"],"mode":"assemble","key":["her name","her sense of fair play","the dance she loves","who she knows she is"],"relearn":"All the parts you keep inside add up to the one-of-a-kind you.","persona":"Ananya","source":"self-concept"},
  {"id":"wm-904","cat":"parts-of-me","type":"build","hook":"Build a name badge for your first day at a new school.","prompt":"Add what you'd want a new class to know about you.","pieces":["the name I like to be called","one thing I love","one thing I'm kind about"],"mode":"assemble","key":["the name I like to be called","one thing I love","one thing I'm kind about"],"relearn":"Your name and your loves are yours to share when you meet new people.","persona":"any","source":"self-expression"},
  {"id":"wm-905","cat":"parts-of-me","type":"build","hook":"Faizan builds a quiet little collage of himself.","prompt":"Add the gentle parts that are truly Faizan.","pieces":["my name","the songs I hum","how gently I care","who I am inside"],"mode":"assemble","key":["my name","the songs I hum","how gently I care","who I am inside"],"relearn":"Every part of you belongs to you, exactly as you are.","persona":"Faizan-type","source":"protect-and-affirm"},
  {"id":"wm-906","cat":"parts-of-me","type":"build","hook":"Put your collage in order, from the day you were named to now.","prompt":"Sequence your parts in the order you found them.","pieces":["my name when I was born","the family I grew up with","the loves I found","who I know I am now"],"mode":"sequence","key":["my name when I was born","the family I grew up with","the loves I found","who I know I am now"],"relearn":"You gather your parts over time, and they all stay part of you.","persona":"any","source":"identity exploration"},
  {"id":"wm-907","cat":"parts-of-me","type":"build","hook":"Lensy: build a 'me tree' with roots, trunk and leaves.","prompt":"Place each part of you on the tree.","pieces":["my family (roots)","who I am inside (trunk)","my loves (leaves)","my name (the sign on it)"],"mode":"assemble","key":["my family (roots)","who I am inside (trunk)","my loves (leaves)","my name (the sign on it)"],"relearn":"All your parts grow together into one whole, special you.","persona":"any","source":"self-concept"},
  {"id":"wm-908","cat":"parts-of-me","type":"build","hook":"Build a 'team me' poster for show-and-tell.","prompt":"Pick the players for team me.","pieces":["my name","the brave bit of me","the funny bit of me","the kind bit of me","who I am inside"],"mode":"assemble","key":["my name","the brave bit of me","the funny bit of me","the kind bit of me","who I am inside"],"relearn":"Lots of parts play on team you, and your gender is one player among many.","persona":"any","source":"self-concept"},
  {"id":"wm-909","cat":"parts-of-me","type":"build","hook":"Make a flag for the country of YOU.","prompt":"Add the parts that go on your flag.","pieces":["my name","what I love most","who I am inside"],"mode":"assemble","key":["my name","what I love most","who I am inside"],"relearn":"You're the one and only you, made of many parts you can be proud of.","persona":"any","source":"uniqueness"},
  {"id":"wm-910","cat":"parts-of-me","type":"build","hook":"Build a 'me suitcase' for a trip to your nani's house.","prompt":"Pack the parts of you that come everywhere with you.","pieces":["my name","my feelings","who I am inside","the games I love"],"mode":"assemble","key":["my name","my feelings","who I am inside","the games I love"],"relearn":"Your inside parts travel with you wherever you go.","persona":"any","source":"self-concept"},
  {"id":"wm-911","cat":"parts-of-me","type":"build","hook":"Lensy: finish your collage with a frame.","prompt":"Pick the words for the frame around all your parts.","pieces":["one of a kind","made of many parts","who I am is mine"],"mode":"assemble","key":["one of a kind","made of many parts","who I am is mine"],"relearn":"All your parts together make one special, one-of-a-kind you.","persona":"any","source":"self-concept"},
  {"id":"wm-912","cat":"parts-of-me","type":"build","hook":"Build a 'parts of me' rangoli, dot by dot.","prompt":"Place each dot for a part of you.","pieces":["my name","my family","my loves","my feelings","who I am inside"],"mode":"assemble","key":["my name","my family","my loves","my feelings","who I am inside"],"relearn":"Many dots make one pattern, the way many parts make one you.","persona":"any","source":"self-concept"},
  {"id":"wm-913","cat":"parts-of-me","type":"build","hook":"Build the order of your morning that makes you feel like you.","prompt":"Sequence the parts of a 'feels like me' morning.","pieces":["wake and stretch","do the thing I love","be with my family","head out as me"],"mode":"sequence","key":["wake and stretch","do the thing I love","be with my family","head out as me"],"relearn":"You carry the same you through your whole day.","persona":"any","source":"self-concept"},
  {"id":"wm-914","cat":"parts-of-me","type":"reflect","hook":"Lensy: which part of you feels most YOU this morning?","prompt":"Point to one (or say your own).","options":["The part that loves to draw","The part that cracks jokes","The part that helps at home","Who I am inside"],"affirm":"Whatever you picked, it's part of the one-of-a-kind you. Lovely.","relearn":"You're made of many parts, and you get to notice them.","persona":"any","source":"self-concept"},
  {"id":"wm-915","cat":"parts-of-me","type":"reflect","hook":"Lensy: if you made a 'me' song, what would be in it?","prompt":"Pick a line for your song.","options":["My name and my loves","My family and my friends","The brave, funny, kind me","All of the above"],"affirm":"Your song can hold all of you at once. That's the magic of you.","relearn":"All your parts can sing together as one you.","persona":"any","source":"self-expression"},
  {"id":"wm-916","cat":"parts-of-me","type":"reflect","hook":"Ananya thinks for a sec: what's a part of you nobody can see?","prompt":"What comes to mind?","options":["My feelings","Who I am inside","My dreams","All of them are inside"],"affirm":"Some of your best parts live inside, where only you know them best.","relearn":"Many parts of you are inside, and they're just as real.","persona":"Ananya","source":"self-concept"},
  {"id":"wm-917","cat":"parts-of-me","type":"reflect","hook":"Lensy: your gender is one part of you. What are some others?","prompt":"Name a few (or pick).","options":["What I love","How I treat people","My family","My big imagination"],"affirm":"So many parts make you, you, and your gender is just one of them.","relearn":"Your gender is one part among many; the whole you is much bigger.","persona":"gender thread","source":"identity facets"},
  {"id":"wm-918","cat":"parts-of-me","type":"reflect","hook":"Lensy: nobody learns everything about themselves in one day. How does that sit with you?","prompt":"Pick one.","options":["Feels fine","No rush for me","I can take my time","I'll keep learning"],"affirm":"Learning who you are takes time, and you have all of it you need.","relearn":"Getting to know yourself can take time, and that's fine.","persona":"any","source":"identity exploration"},
  {"id":"wm-919","cat":"parts-of-me","type":"reflect","hook":"Reyansh: which part of you would your best friend pick first?","prompt":"What do you think they'd say?","options":["That I'm funny","That I'm a good teammate","That I'm loyal","I'd ask them!"],"affirm":"Friends often see our good parts clearly. They're real, too.","relearn":"Other people notice your parts, but you know yourself best.","persona":"Reyansh","source":"self-concept"},
  {"id":"wm-920","cat":"parts-of-me","type":"reflect","hook":"Lensy: is there anyone in the whole world exactly like you?","prompt":"What do you think?","options":["No, I'm one of a kind","Nobody's just like me","I'm unique","Not even my twin!"],"affirm":"Nobody else is exactly you. That's pretty amazing.","relearn":"You are one of a kind; nobody else is just like you.","persona":"any","source":"uniqueness"},
  {"id":"wm-921","cat":"parts-of-me","type":"reflect","hook":"Faizan: what's one gentle part of you you'd never want to lose?","prompt":"Pick one (or say your own).","options":["How I care about others","The quiet songs I love","My soft heart","All of me"],"affirm":"Your gentle parts are wonderful parts. Keep every one of them.","relearn":"Every part of you, gentle ones too, belongs to you.","persona":"Faizan-type","source":"protect-and-affirm"},
  {"id":"wm-922","cat":"parts-of-me","type":"reflect","hook":"Lensy: which part of you grew the most this year?","prompt":"Have a think.","options":["I got braver","I got kinder","I learned something new","I understand myself more"],"affirm":"You can grow and change and still be wonderfully you.","relearn":"Your parts can grow, and the one-of-a-kind you stays you.","persona":"any","source":"identity exploration"},
  {"id":"wm-923","cat":"parts-of-me","type":"reflect","hook":"Lensy: think of one thing you love about yourself. Got it?","prompt":"Pick one.","options":["Yes, I do","That was easy","I have lots","Found one"],"affirm":"That thing you love is one bright part of the whole you.","relearn":"Each thing you like about yourself is part of the whole you.","persona":"any","source":"self-concept"},
  {"id":"wm-924","cat":"parts-of-me","type":"reflect","hook":"Lensy: which part of you do you show at home, but not at school?","prompt":"Have a think (no wrong answer).","options":["My silly side","My singing","My big feelings","I'm the same everywhere"],"affirm":"You can show different parts in different places, and they're all you.","relearn":"You're the same you, even when you show different parts.","persona":"any","source":"self-concept"},
  {"id":"wm-925","cat":"parts-of-me","type":"reflect","hook":"Lensy: who knows the inside-you best?","prompt":"Who do you think?","options":["Me","Only I do","I know my own heart"],"affirm":"You know your inside-self best of all. That part is yours to know.","relearn":"Who you are inside is something only you know best.","persona":"any","source":"self-knowledge"},
  {"id":"wm-926","cat":"parts-of-me","type":"reflect","hook":"Lensy: name a part of you that makes you proud.","prompt":"Say one (or pick).","options":["I help my little cousin","I'm good at a sport","I'm honest","I never give up"],"affirm":"That's a real part of you, and it's worth being proud of.","relearn":"You can be proud of your many parts.","persona":"any","source":"self-concept"},
  {"id":"wm-927","cat":"parts-of-me","type":"reflect","hook":"Ananya: if your parts were colours, what would your picture look like?","prompt":"Imagine it.","options":["Bright and busy","Calm and blue","All the colours","Just my favourites"],"affirm":"Your mix of colours is yours alone. No one paints quite like you.","relearn":"Your many parts mix into one picture that's only yours.","persona":"Ananya","source":"uniqueness"},
  {"id":"wm-928","cat":"parts-of-me","type":"reflect","hook":"Lensy: which part of you is the same as last year?","prompt":"Think about it.","options":["My name","Who I am inside","My family","Lots stayed the same"],"affirm":"Some parts of you stay steady, even as others grow. Both are you.","relearn":"Some parts hold steady while others change; all are still you.","persona":"any","source":"self-concept"},
  {"id":"wm-929","cat":"parts-of-me","type":"reflect","hook":"Lensy: what would you put on a sticker that says 'this is me'?","prompt":"Pick a sticker.","options":["My name","A heart for who I love","A star for who I am","A smile"],"affirm":"Any of those is a true little piece of you. Stick it on proudly.","relearn":"Small symbols can carry big parts of who you are.","persona":"any","source":"self-expression"},
  {"id":"wm-930","cat":"parts-of-me","type":"reflect","hook":"Lensy: a part of you no one can take away, what is it?","prompt":"What do you think?","options":["Who I am inside","My feelings","My name","My memories"],"affirm":"Some parts of you are yours forever, no matter what. That's a comfort.","relearn":"The deepest parts of you are yours to keep.","persona":"any","source":"self-knowledge"},
  {"id":"wm-931","cat":"parts-of-me","type":"reflect","hook":"Lensy: if you drew a map of you, where would your kindness go?","prompt":"Pick a spot (or say your own).","options":["Right in the middle","Near my heart","Everywhere","In my hands"],"affirm":"Wherever you place it, your kindness is a real part of your map.","relearn":"Your good qualities are parts of you, just like your loves.","persona":"any","source":"self-concept"},
  {"id":"wm-932","cat":"parts-of-me","type":"match","hook":"Match each kid to the part they're describing.","pairs":[{"left":"\"I love mehndi patterns\"","right":"Something they love"},{"left":"\"My nana taught me chess\"","right":"Family they belong with"},{"left":"\"I feel shy at first\"","right":"A feeling inside"},{"left":"\"People call me Diya\"","right":"Their name"},{"left":"\"I just know who I am\"","right":"Their inside-self"}],"relearn":"Each thing a kid says points to a different part of who they are.","persona":"any","source":"self-concept"},
  {"id":"wm-933","cat":"parts-of-me","type":"match","hook":"Match the part of you to a place it shows up.","pairs":[{"left":"Your name","right":"On your school notebook"},{"left":"What you love","right":"In how you spend recess"},{"left":"Your feelings","right":"On your face sometimes"},{"left":"Your family","right":"At home together"},{"left":"Who you are inside","right":"Quietly, always"}],"relearn":"Your parts show up in many places, and all of them are yours.","persona":"any","source":"self-concept"},
  {"id":"wm-934","cat":"parts-of-me","type":"match","hook":"Match the kid's hobby to the part of them it grows.","pairs":[{"left":"Plays the dholak","right":"Their love of music"},{"left":"Helps cook roti","right":"Their helping hands"},{"left":"Reads comics","right":"Their big imagination"},{"left":"Runs races","right":"Their strong body"},{"left":"Tells stories","right":"Their bright voice"}],"relearn":"The things you do help your many parts grow.","persona":"any","source":"self-concept"},
  {"id":"wm-935","cat":"parts-of-me","type":"match","hook":"Match the question to the part of you it asks about.","pairs":[{"left":"\"What are you called?\"","right":"My name"},{"left":"\"What do you love?\"","right":"My favourite things"},{"left":"\"How do you feel?\"","right":"My feelings"},{"left":"\"Who's at home?\"","right":"My family"},{"left":"\"Who are you, really?\"","right":"My inside-self"}],"relearn":"Different questions ask about different parts of you.","persona":"any","source":"self-concept"},
  {"id":"wm-936","cat":"parts-of-me","type":"match","hook":"Reyansh sorts his parts. Match each to its kind.","pairs":[{"left":"Reyansh","right":"A name"},{"left":"Cricket fan","right":"A love"},{"left":"Big brother","right":"A family role"},{"left":"Excited","right":"A feeling"},{"left":"A boy, and that's him","right":"Who he is inside"}],"relearn":"Reyansh is made of a name, loves, family, feelings and his inside-self.","persona":"Reyansh","source":"identity facets"},
  {"id":"wm-937","cat":"parts-of-me","type":"match","hook":"Match the part to a true thing about it.","pairs":[{"left":"Your name","right":"You can like the one you're called"},{"left":"Your loves","right":"They can change and grow"},{"left":"Your feelings","right":"They live inside you"},{"left":"Your family","right":"They're people you belong with"},{"left":"Who you are","right":"Only you know it best"}],"relearn":"Every part of you has its own true place in the one-of-a-kind you.","persona":"any","source":"self-concept"},
  {"id":"wm-938","cat":"parts-of-me","type":"match","hook":"Match two friends' parts that are different but both okay.","pairs":[{"left":"Aarav loves football","right":"Diya loves drawing"},{"left":"Aarav is loud","right":"Diya is quiet"},{"left":"Aarav has short hair","right":"Diya has long plaits"},{"left":"Aarav lives in a city","right":"Diya lives in a village"},{"left":"Both are kind","right":"Both are themselves"}],"relearn":"Two kids can have different parts and both be wonderfully themselves.","persona":"any","source":"uniqueness"},
  {"id":"wm-939","cat":"parts-of-me","type":"match","hook":"Match the part of Ananya to where she keeps it.","pairs":[{"left":"Her name","right":"On her badge"},{"left":"Her love of dance","right":"In her feet"},{"left":"Her fairness","right":"In how she shares"},{"left":"Her worries","right":"Inside, sometimes"},{"left":"Who she is","right":"In her own heart"}],"relearn":"Ananya's parts live in different places, and all belong to her.","persona":"Ananya","source":"self-concept"},
  {"id":"wm-940","cat":"parts-of-me","type":"match","hook":"Match the 'this is me' line to the part it names.","pairs":[{"left":"\"I'm Kabir\"","right":"My name"},{"left":"\"I love kabaddi\"","right":"What I love"},{"left":"\"I'm a bit shy\"","right":"A feeling of mine"},{"left":"\"I've got two sisters\"","right":"My family"},{"left":"\"I'm me\"","right":"Who I am inside"}],"relearn":"When you describe yourself, each line names a different part of you.","persona":"any","source":"self-expression"},
  {"id":"wm-941","cat":"parts-of-me","type":"sort","hook":"Sort: a part that's inside you, or one you can see?","items":[{"id":"a","text":"My height"},{"id":"b","text":"My feelings"},{"id":"c","text":"My smile"},{"id":"d","text":"Who I know I am"},{"id":"e","text":"My freckles"},{"id":"f","text":"What I dream about"}],"bins":[{"id":"out","label":"You can see it","valence":"neutral"},{"id":"in","label":"It's inside me","valence":"neutral"}],"key":{"a":"out","b":"in","c":"out","d":"in","e":"out","f":"in"},"relearn":"Some parts of you show; some live inside; all of them are you.","persona":"any","source":"self-concept"},
  {"id":"wm-942","cat":"parts-of-me","type":"sort","hook":"Sort: a part of who you are, or something you just use?","items":[{"id":"a","text":"My kindness"},{"id":"b","text":"My pencil case"},{"id":"c","text":"What I love doing"},{"id":"d","text":"My phone game"},{"id":"e","text":"Who I am inside"},{"id":"f","text":"My family"}],"bins":[{"id":"me","label":"Part of me","valence":"neutral"},{"id":"use","label":"A thing I use","valence":"neutral"}],"key":{"a":"me","b":"use","c":"me","d":"use","e":"me","f":"me"},"relearn":"Your kindness, loves, inside-self and family are parts of you, not just things.","persona":"any","source":"self-concept"},
  {"id":"wm-943","cat":"parts-of-me","type":"sort","hook":"Sort each part into 'stays the same' or 'can grow'.","items":[{"id":"a","text":"My name"},{"id":"b","text":"How tall I am"},{"id":"c","text":"Who I am inside"},{"id":"d","text":"What I'm good at"},{"id":"e","text":"The games I like"},{"id":"f","text":"How brave I feel"}],"bins":[{"id":"steady","label":"Tends to stay","valence":"neutral"},{"id":"grow","label":"Can grow or change","valence":"neutral"}],"key":{"a":"steady","b":"grow","c":"steady","d":"grow","e":"grow","f":"grow"},"relearn":"Some parts hold steady while others grow, and all stay part of you.","persona":"any","source":"identity exploration"},
  {"id":"wm-944","cat":"parts-of-me","type":"sort","hook":"Sort: which part answers each question about you?","items":[{"id":"a","text":"Diya"},{"id":"b","text":"Loves painting"},{"id":"c","text":"Feels excited"},{"id":"d","text":"Has a baby brother"},{"id":"e","text":"Just knows she's her"},{"id":"f","text":"Tall for her age"}],"bins":[{"id":"name","label":"Her name + body","valence":"neutral"},{"id":"inside","label":"Her loves + inside","valence":"neutral"}],"key":{"a":"name","b":"inside","c":"inside","d":"name","e":"inside","f":"name"},"relearn":"Each part of Diya answers a different 'who are you?' question.","persona":"any","source":"self-concept"},
  {"id":"wm-945","cat":"parts-of-me","type":"sort","hook":"Sort: a part of YOU, or a part of your best friend?","items":[{"id":"a","text":"My own name"},{"id":"b","text":"My friend's favourite song"},{"id":"c","text":"Who I am inside"},{"id":"d","text":"My friend's family"},{"id":"e","text":"My feelings"},{"id":"f","text":"My friend's hobby"}],"bins":[{"id":"mine","label":"A part of me","valence":"neutral"},{"id":"theirs","label":"A part of my friend","valence":"neutral"}],"key":{"a":"mine","b":"theirs","c":"mine","d":"theirs","e":"mine","f":"theirs"},"relearn":"Your parts are yours; your friend has their own. Both are wonderful.","persona":"any","source":"uniqueness"},
  {"id":"wm-946","cat":"parts-of-me","type":"sort","hook":"Sort each part into 'I can choose it' or 'it's just me'.","items":[{"id":"a","text":"The hobby I pick"},{"id":"b","text":"Who I am inside"},{"id":"c","text":"The friends I make"},{"id":"d","text":"My feelings as they come"},{"id":"e","text":"The clothes I wear"},{"id":"f","text":"My name from birth"}],"bins":[{"id":"choose","label":"I get to choose","valence":"neutral"},{"id":"is","label":"It's just me","valence":"neutral"}],"key":{"a":"choose","b":"is","c":"choose","d":"is","e":"choose","f":"is"},"relearn":"Some parts you choose; some are just you. All belong to you.","persona":"any","source":"self-knowledge"},
  {"id":"wm-947","cat":"parts-of-me","type":"sort","hook":"Faizan sorts his parts: 'shows on the outside' or 'lives inside'.","items":[{"id":"a","text":"His gentle voice"},{"id":"b","text":"The songs in his head"},{"id":"c","text":"His tidy hair"},{"id":"d","text":"How deeply he cares"},{"id":"e","text":"His shy smile"},{"id":"f","text":"Who he knows he is"}],"bins":[{"id":"out","label":"Shows outside","valence":"neutral"},{"id":"in","label":"Lives inside","valence":"neutral"}],"key":{"a":"out","b":"in","c":"out","d":"in","e":"out","f":"in"},"relearn":"Faizan's inside parts are just as real as the ones you can see.","persona":"Faizan-type","source":"protect-and-affirm"},
  {"id":"wm-948","cat":"parts-of-me","type":"sort","hook":"Sort each line into 'about my body' or 'about my inside-self'.","items":[{"id":"a","text":"I have brown eyes"},{"id":"b","text":"I love cricket"},{"id":"c","text":"I'm 8 years old"},{"id":"d","text":"I feel kind"},{"id":"e","text":"I have curly hair"},{"id":"f","text":"I know who I am"}],"bins":[{"id":"body","label":"About my body","valence":"neutral"},{"id":"inside","label":"About my inside-self","valence":"neutral"}],"key":{"a":"body","b":"inside","c":"body","d":"inside","e":"body","f":"inside"},"relearn":"Your body and your inside-self are different parts, both yours.","persona":"any","source":"self-concept"},
  {"id":"wm-949","cat":"parts-of-me","type":"sort","hook":"Sort: what makes you YOU, or just something you have today?","items":[{"id":"a","text":"My favourite snack"},{"id":"b","text":"Who I am inside"},{"id":"c","text":"Today's mood"},{"id":"d","text":"My kindness"},{"id":"e","text":"My new shoes"},{"id":"f","text":"My family"}],"bins":[{"id":"makes","label":"Makes me, me","valence":"neutral"},{"id":"today","label":"Just for today","valence":"neutral"}],"key":{"a":"today","b":"makes","c":"today","d":"makes","e":"today","f":"makes"},"relearn":"Deep parts make you you; passing things come and go.","persona":"any","source":"self-concept"},
  {"id":"wm-950","cat":"parts-of-me","type":"role-play","hook":"A new classmate asks, \"So, what are you like?\"","setup":"Tell them about you. Say:","yourLine":[{"text":"\"I'm ___, I love ___, and I'm me.\"","best":true},{"text":"\"I'm just like everyone else.\""}],"relearn":"You can describe yourself by your many parts, in your own words.","persona":"any","source":"self-expression"},
  {"id":"wm-951","cat":"parts-of-me","type":"role-play","hook":"Your cousin says, \"But what ARE you, really?\"","setup":"Answer in your own way. Say:","yourLine":[{"text":"\"I'm lots of things, and all of them are me.\"","best":true},{"text":"\"I dunno, you tell me.\""}],"relearn":"You're made of many parts, and you get to name them yourself.","persona":"any","source":"self-knowledge"},
  {"id":"wm-952","cat":"parts-of-me","type":"role-play","hook":"Reyansh: a friend says \"you're ONLY a cricket guy.\"","setup":"Tell him there's more to you. Say:","yourLine":[{"text":"\"Cricket's one part of me, but I'm lots more too.\"","best":true},{"text":"\"Yeah, that's all I am.\""}],"relearn":"One thing you love is a part of you, not the whole of you.","persona":"Reyansh","source":"identity facets"},
  {"id":"wm-953","cat":"parts-of-me","type":"role-play","hook":"At a family party, an aunty says \"tell us about yourself!\"","setup":"Share a few parts of you. Say:","yourLine":[{"text":"\"My name's ___, I love ___, and I'm good at ___.\"","best":true},{"text":"\"There's nothing to tell.\""}],"relearn":"You always have parts worth sharing; you choose which ones.","persona":"any","source":"self-expression"},
  {"id":"wm-954","cat":"parts-of-me","type":"role-play","hook":"Ananya: someone says \"girls can't be the brainy AND sporty one.\"","setup":"Stand up for your many parts. Say:","yourLine":[{"text":"\"I can be both, those are both parts of me.\"","best":true},{"text":"\"I guess I have to pick one.\""}],"relearn":"You can hold many parts at once; no one part cancels another.","persona":"Ananya","source":"self-concept"},
  {"id":"wm-955","cat":"parts-of-me","type":"role-play","hook":"Faizan is asked, \"what's the best thing about you?\"","setup":"Help Faizan answer gently. Say:","yourLine":[{"text":"\"I'm kind, and that's a part of me I like.\"","best":true},{"text":"\"Nothing, really.\""}],"relearn":"You can name a part of you you're proud of, even quietly.","persona":"Faizan-type","source":"protect-and-affirm"},
  {"id":"wm-956","cat":"parts-of-me","type":"role-play","hook":"A friend says \"copy me, then we'll be the same!\"","setup":"Keep your own parts. Say:","yourLine":[{"text":"\"I'd rather be me; you be you, I'll be me.\"","best":true},{"text":"\"Okay, I'll just be like you.\""}],"relearn":"You don't have to copy anyone; your own parts make you, you.","persona":"any","source":"uniqueness"},
  {"id":"wm-957","cat":"parts-of-me","type":"strike-rewrite","hook":"Lensy spots a wobbly idea. Fix it.","myth":{"un":"Your gender is the only thing that says who you are.","re":"Your gender is one part of you, among many.","why":"Your name, loves, feelings and family are all parts of who you are too."},"relearn":"Your gender is one part among many; the whole you is much bigger.","persona":"gender thread","source":"identity facets"},
  {"id":"wm-958","cat":"parts-of-me","type":"strike-rewrite","hook":"A line needs a rewrite. Strike and fix.","myth":{"un":"You're either the smart kid or the fun kid, never both.","re":"You can be smart AND fun AND kind, all at once.","why":"You're made of many parts, and they can all be true together."},"relearn":"You can hold many parts at once; one doesn't cancel another.","persona":"any","source":"self-concept"},
  {"id":"wm-959","cat":"parts-of-me","type":"strike-rewrite","hook":"Reyansh repeats something. Help him fix it.","myth":{"un":"Whatever your friends like has to be the only part of you.","re":"Your friends' likes are theirs; your own parts are yours.","why":"You get to know and keep the parts that are truly you."},"relearn":"Your parts are yours, even if your friends like other things.","persona":"Reyansh","source":"self-knowledge"},
  {"id":"wm-960","cat":"parts-of-me","type":"strike-rewrite","hook":"Strike the wobbly bit and rewrite it true.","myth":{"un":"If you change a hobby, you stop being you.","re":"You can change what you love and still be wonderfully you.","why":"Your loves can grow and change; the one-of-a-kind you stays."},"relearn":"Your loves can change, and you're still the same you.","persona":"any","source":"identity exploration"},
  {"id":"wm-961","cat":"parts-of-me","type":"strike-rewrite","hook":"Lensy: this idea needs fixing.","myth":{"un":"Other people get to decide who you are inside.","re":"Who you are inside is something only you know best.","why":"Your inside-self is yours; no one else lives in your heart."},"relearn":"Only you know your inside-self best.","persona":"any","source":"self-knowledge"},
  {"id":"wm-962","cat":"parts-of-me","type":"strike-rewrite","hook":"Strike and rewrite this one.","myth":{"un":"You have to be exactly like everyone to be a real 'you'.","re":"Being different from others is a normal, good part of being you.","why":"Nobody else is exactly you, and that's what makes you one of a kind."},"relearn":"You don't have to match anyone; different is normal and good.","persona":"any","source":"uniqueness"},
  {"id":"wm-963","cat":"parts-of-me","type":"strike-rewrite","hook":"Faizan heard this. Help fix it.","myth":{"un":"A quiet, gentle kid hasn't really got much of a 'self'.","re":"A quiet, gentle kid is full of real, wonderful parts inside.","why":"Some of your biggest parts live inside, where they still count."},"relearn":"Quiet parts are real parts; your inside-self is full and yours.","persona":"Faizan-type","source":"protect-and-affirm"},
  {"id":"wm-964","cat":"parts-of-me","type":"strike-rewrite","hook":"Lensy: rewrite this so it's true.","myth":{"un":"One part of you, like your name, is the whole of you.","re":"Your name is one part; lots of parts together make you.","why":"Your loves, feelings, family and inside-self all add up to you."},"relearn":"No single part is the whole you; many parts make one you.","persona":"any","source":"self-concept"},
  {"id":"wm-965","cat":"parts-of-me","type":"branch","hook":"A new kid asks what you're like, but you feel shy.","options":[{"text":"Share one true part: \"I love drawing.\"","consequence":"They smile and say they do too.","best":true},{"text":"Say \"nothing\" and look away.","consequence":"The chat stops; it's awkward."},{"text":"Make up someone cooler.","consequence":"It feels off; it isn't you."}],"debrief":"Sharing one true part lets people meet the real you.","relearn":"You can share your parts a little at a time.","persona":"any","source":"self-expression"},
  {"id":"wm-966","cat":"parts-of-me","type":"branch","hook":"A classmate says \"you can only be ONE thing, pick.\"","options":[{"text":"\"I'm lots of things at once.\"","consequence":"You feel whole; they learn something.","best":true},{"text":"Pick one, hide the rest.","consequence":"Parts of you feel left out."},{"text":"Get upset and walk off.","consequence":"You still feel boxed in."}],"debrief":"You're many parts at once; no need to squeeze into one box.","relearn":"You can be many things at once.","persona":"any","source":"self-concept"},
  {"id":"wm-967","cat":"parts-of-me","type":"branch","hook":"You're making a 'me' poster and don't know what to add.","options":[{"text":"Start with your name and one love.","consequence":"It grows easily; it feels like you.","best":true},{"text":"Copy your friend's poster.","consequence":"Nice, but not about you."},{"text":"Leave it blank; it's hard.","consequence":"You miss showing your parts."}],"debrief":"Begin with one true part, and the rest of you follows.","relearn":"Your name and loves are a great place to begin.","persona":"any","source":"self-expression"},
  {"id":"wm-968","cat":"parts-of-me","type":"branch","hook":"Reyansh feels he must be 'only the funny one' for his gang.","options":[{"text":"Let his thoughtful side show too.","consequence":"Friends like fuller Reyansh more.","best":true},{"text":"Hide all but the jokes.","consequence":"He tires of being one thing."},{"text":"Stop hanging out.","consequence":"He's lonely; nothing's solved."}],"debrief":"Friends who matter like the whole you, not one part.","relearn":"You don't have to be only one part for anyone.","persona":"Reyansh","source":"self-concept"},
  {"id":"wm-969","cat":"parts-of-me","type":"branch","hook":"Ananya is told to drop football because 'it's not a girl part'.","options":[{"text":"Keep football; it's truly her.","consequence":"She stays whole and happy.","best":true},{"text":"Quit, though she loves it.","consequence":"A real part goes quiet."},{"text":"Argue loudly back.","consequence":"A fight; nothing's better."}],"debrief":"What you love is a real part of you; you keep your parts.","relearn":"No one else decides which parts are 'allowed' to be you.","persona":"Ananya","source":"self-knowledge"},
  {"id":"wm-970","cat":"parts-of-me","type":"branch","hook":"Faizan worries his gentle parts make him 'less' of himself.","options":[{"text":"Tell a trusted grown-up.","consequence":"They say his gentle parts are real.","best":true},{"text":"Hide every soft part.","consequence":"He shrinks; the worry grows."},{"text":"Carry it alone.","consequence":"It feels heavy; no help."}],"debrief":"Your gentle parts are real; a trusted grown-up can remind you.","relearn":"You don't have to carry worry about yourself alone.","persona":"Faizan-type","source":"protect-and-affirm"},
  {"id":"wm-971","cat":"parts-of-me","type":"branch","hook":"At a family lunch everyone describes you in one word.","options":[{"text":"Add yours: \"I'm lots of things!\"","consequence":"They laugh and see more of you.","best":true},{"text":"Let one word be the whole you.","consequence":"It feels too small."},{"text":"Say nothing.","consequence":"Your real parts stay hidden."}],"debrief":"You can speak up and show the many parts that make you, you.","relearn":"You get to add your own words about who you are.","persona":"any","source":"self-expression"},
  {"id":"wm-972","cat":"parts-of-me","type":"branch","hook":"You changed your favourite game; a friend says \"so you're different now?\"","options":[{"text":"\"My loves changed, but I'm me.\"","consequence":"Your friend gets it; you relax.","best":true},{"text":"Worry you've stopped being you.","consequence":"You feel wobbly for no reason."},{"text":"Pretend you still love it.","consequence":"It feels fake; not you."}],"debrief":"Your loves can change while the one-of-a-kind you stays.","relearn":"Changing what you like doesn't change who you are.","persona":"any","source":"identity exploration"},
  {"id":"wm-1260","cat":"respect-me","type":"role-play","hook":"A new girl says \"please call me Meera, not didi.\"","setup":"Show respect. Say:","yourLine":[{"text":"\"Okay, Meera! Sit with us.\"","best":true},{"text":"Keep calling her didi"}],"relearn":"Call people the name they ask for; it shows respect.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1261","cat":"respect-me","type":"role-play","hook":"On the bus a cousin keeps using your baby nickname loudly.","setup":"Speak up kindly. Say:","yourLine":[{"text":"\"I like my real name, please.\"","best":true},{"text":"Stay quiet and feel small"}],"relearn":"You can ask people to use the name you like best.","persona":"be-yourself","source":"voice"},
  {"id":"wm-1262","cat":"respect-me","type":"role-play","hook":"A friend tells you their new short name for themself.","setup":"Welcome it. Say:","yourLine":[{"text":"\"Got it! I'll use that.\"","best":true},{"text":"\"Your old name was better.\""}],"relearn":"Using the name a friend gives is an easy way to be kind.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1263","cat":"respect-me","type":"role-play","hook":"Kids giggle when a boy joins the rangoli-making.","setup":"Be a friend. Say:","yourLine":[{"text":"\"Make one with me!\"","best":true},{"text":"Giggle along with them"}],"relearn":"Anyone can join in; laughing at them isn't kind.","persona":"any","source":"inclusion / voice"},
  {"id":"wm-1264","cat":"respect-me","type":"role-play","hook":"A classmate brings dosa for tiffin and others say \"yuck.\"","setup":"Stand with them. Say:","yourLine":[{"text":"\"Smells great, can I try?\"","best":true},{"text":"Say \"yuck\" too"}],"relearn":"You can be kind about what makes someone different.","persona":"ally seed","source":"inclusion / voice"},
  {"id":"wm-1265","cat":"respect-me","type":"role-play","hook":"Someone laughs at your friend's stutter.","setup":"Help your friend. Say:","yourLine":[{"text":"\"Take your time, I'm listening.\"","best":true},{"text":"Finish their words for them"}],"relearn":"Giving someone time to speak is a kind, respectful thing.","persona":"Faizan-type","source":"support / voice"},
  {"id":"wm-1266","cat":"respect-me","type":"role-play","hook":"A friend's dad cooks dinner and a kid calls it \"a mum's job.\"","setup":"Reply kindly. Say:","yourLine":[{"text":"\"Anyone can cook, it's lovely!\"","best":true},{"text":"\"Yeah, that's strange.\""}],"relearn":"Jobs at home aren't only for one gender; that's okay.","persona":"any","source":"respect / voice"},
  {"id":"wm-1267","cat":"respect-me","type":"role-play","hook":"A new neighbour speaks a different language at play.","setup":"Make them feel welcome. Say:","yourLine":[{"text":"\"Teach me a word! I'll teach you one.\"","best":true},{"text":"Walk away from them"}],"relearn":"Curiosity and kindness make new friends feel welcome.","persona":"any","source":"inclusion / voice"},
  {"id":"wm-1268","cat":"respect-me","type":"role-play","hook":"Your team groans when the quiet kid is picked.","setup":"Lift them up. Say:","yourLine":[{"text":"\"Glad you're on our team!\"","best":true},{"text":"Groan with the team"}],"relearn":"A warm welcome tells someone they belong on the team.","persona":"ally seed","source":"inclusion / voice"},
  {"id":"wm-1269","cat":"respect-me","type":"role-play","hook":"A friend wears their grandmother's old bangles to school.","setup":"Be kind. Say:","yourLine":[{"text":"\"Those are special, I love them.\"","best":true},{"text":"\"That's so weird.\""}],"relearn":"What's special to someone deserves respect, not teasing.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1270","cat":"respect-me","type":"role-play","hook":"Kids in the park won't share the swing with a new child.","setup":"Make room. Say:","yourLine":[{"text":"\"Your turn next, come on!\"","best":true},{"text":"Hog the swing too"}],"relearn":"Sharing and taking turns is a simple way to include everyone.","persona":"any","source":"inclusion / voice"},
  {"id":"wm-1271","cat":"respect-me","type":"role-play","hook":"A friend says \"please use 'they' for me.\"","setup":"Show respect. Say:","yourLine":[{"text":"\"Sure! Thanks for telling me.\"","best":true},{"text":"\"That's too hard, no.\""}],"relearn":"Using the word someone asks for is kind and easy to learn.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1272","cat":"respect-me","type":"role-play","hook":"At a wedding a kid mocks how your friend dances.","setup":"Stand by your friend. Say:","yourLine":[{"text":"\"They dance how they like, let's join!\"","best":true},{"text":"Laugh and copy the mocking"}],"relearn":"How someone moves or dances is theirs; standing by them is kind.","persona":"Faizan-type","source":"support / voice"},
  {"id":"wm-1273","cat":"respect-me","type":"role-play","hook":"You forgot a classmate's name and almost guess.","setup":"Be honest and kind. Say:","yourLine":[{"text":"\"Sorry, remind me your name?\"","best":true},{"text":"Call them \"hey, you\""}],"relearn":"Asking kindly for a name beats guessing or calling \"hey, you.\"","persona":"respect","source":"respect / voice"},
  {"id":"wm-1274","cat":"respect-me","type":"role-play","hook":"A friend is upset they were left off the cricket team for being a girl.","setup":"Be fair. Say:","yourLine":[{"text":"\"You can bat with us, come on.\"","best":true},{"text":"\"Maybe just watch.\""}],"relearn":"Including a friend left out for their gender is the fair thing.","persona":"Ananya","source":"fairness / voice"},
  {"id":"wm-1275","cat":"respect-me","type":"role-play","hook":"Someone asks why your friend's family is different from yours.","setup":"Answer kindly. Say:","yourLine":[{"text":"\"Families come in many kinds, it's nice.\"","best":true},{"text":"\"Theirs is wrong.\""}],"relearn":"Families differ; respecting that is kinder than calling it wrong.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1276","cat":"respect-me","type":"branch","hook":"A boy in your class wears mehndi for a festival and kids laugh.","options":[{"text":"Say \"it's for his festival, it's nice\"","consequence":"The laughing stops and he feels okay.","outcome":"ally","best":true},{"text":"Laugh so you fit in","consequence":"He feels ashamed of his own festival.","outcome":"bystander"}],"debrief":"Festivals and what they wear deserve respect, not laughter.","relearn":"You can speak up when someone's teased for their festival.","persona":"ally seed","source":"bystander"},
  {"id":"wm-1277","cat":"respect-me","type":"branch","hook":"Friends are passing around a mean nickname for a classmate.","options":[{"text":"Use their real name and don't pass it on","consequence":"The mean name loses its power and fades.","outcome":"kind","best":true},{"text":"Pass it along for a laugh","consequence":"The hurtful name spreads further.","outcome":"unkind"}],"debrief":"A mean nickname isn't \"just a joke\"; using real names is respect.","relearn":"You can stop a mean nickname by using someone's real name.","persona":"respect","source":"respect"},
  {"id":"wm-1278","cat":"respect-me","type":"branch","hook":"A girl wants to try kabaddi and the boys say \"only boys.\"","options":[{"text":"Say \"anyone can try, let her play\"","consequence":"She joins and the game is more fun.","outcome":"fair","best":true},{"text":"Agree it's only for boys","consequence":"She's shut out for no fair reason.","outcome":"unfair"}],"debrief":"Games aren't only for one gender; including her is fair.","relearn":"No game is closed to someone just for their gender.","persona":"Ananya","source":"fairness"},
  {"id":"wm-1279","cat":"respect-me","type":"branch","hook":"A new student sits alone at lunch every day.","options":[{"text":"Invite them to sit with you","consequence":"They feel welcome and make a friend.","outcome":"kind","best":true},{"text":"Leave them on their own","consequence":"They keep feeling left out and lonely.","outcome":"missed"}],"debrief":"A small invite can make someone feel they belong.","relearn":"Inviting someone in is an everyday act of respect.","persona":"any","source":"inclusion"},
  {"id":"wm-1280","cat":"respect-me","type":"branch","hook":"Your friend whispers a rude word about a hijra person on the street.","options":[{"text":"Say \"that's not kind, they're a person too\"","consequence":"Your friend rethinks and is gentler.","outcome":"values","best":true},{"text":"Whisper it back","consequence":"You spread the unkind word too.","outcome":"missed"}],"debrief":"Everyone deserves respect; unkind words about anyone aren't okay.","relearn":"You can choose kind words even when a friend doesn't.","persona":"India","source":"values"},
  {"id":"wm-1281","cat":"respect-me","type":"branch","hook":"Two friends argue and one starts mocking the other's voice.","options":[{"text":"Say \"let's talk, no mocking\"","consequence":"They cool down and sort it out.","outcome":"kind","best":true},{"text":"Cheer the mocking on","consequence":"The argument turns meaner.","outcome":"unkind"}],"debrief":"Even in a fight, mocking how someone is isn't fair.","relearn":"You can disagree without making fun of who someone is.","persona":"respect","source":"respect"},
  {"id":"wm-1282","cat":"respect-me","type":"branch","hook":"A kid copies your friend's accent to get laughs.","options":[{"text":"Say \"everyone talks differently, stop\"","consequence":"The mocking stops and your friend relaxes.","outcome":"ally","best":true},{"text":"Laugh at the accent too","consequence":"Your friend feels small about how they speak.","outcome":"bystander"}],"debrief":"How someone speaks is part of them; mocking it isn't kind.","relearn":"You can step in when someone's mocked for how they talk.","persona":"ally seed","source":"bystander"},
  {"id":"wm-1283","cat":"respect-me","type":"branch","hook":"In a group game, no one will pass to the slowest runner.","options":[{"text":"Pass to them and cheer them on","consequence":"They join in and have fun with everyone.","outcome":"kind","best":true},{"text":"Skip them every time","consequence":"They feel useless and left out.","outcome":"missed"}],"debrief":"Including someone who's slower is fairer and kinder.","relearn":"Everyone gets a turn, whatever they're good at.","persona":"any","source":"inclusion"},
  {"id":"wm-1284","cat":"respect-me","type":"branch","hook":"A classmate is teased because their parents both wear the same kind of clothes.","options":[{"text":"Say \"their family's their own, leave it\"","consequence":"The teasing stops; they feel safer.","outcome":"ally","best":true},{"text":"Ask nosy questions to join the teasing","consequence":"They feel singled out and hurt.","outcome":"bystander"}],"debrief":"A friend's family is theirs to have; teasing it isn't kind.","relearn":"You can stand up when someone's teased about their family.","persona":"ally seed","source":"bystander"},
  {"id":"wm-1285","cat":"respect-me","type":"branch","hook":"You realise you've been calling a classmate the wrong name for a week.","options":[{"text":"Say sorry and use the right name from now","consequence":"They feel seen and you both move on.","outcome":"repair","best":true},{"text":"Keep using it since it's a habit","consequence":"They keep feeling unseen.","outcome":"missed"}],"debrief":"It's never too late to fix a name; say sorry and switch.","relearn":"Fixing a name you got wrong is a kind, easy repair.","persona":"respect","source":"repair"},
  {"id":"wm-1286","cat":"respect-me","type":"branch","hook":"A friend tells you a secret about who they feel they are inside.","options":[{"text":"Keep it safe and be kind","consequence":"They trust you and feel less alone.","outcome":"kind","best":true},{"text":"Tell the whole class","consequence":"They feel exposed and hurt.","outcome":"unkind"}],"debrief":"What a friend trusts you with is theirs to share, not yours.","relearn":"Keeping a friend's trust is part of respecting them.","persona":"respect","source":"respect"},
  {"id":"wm-1287","cat":"respect-me","type":"branch","hook":"At the temple a kid points and stares at someone who looks different.","options":[{"text":"Gently say \"let's not stare, come on\"","consequence":"They stop and the person isn't made to feel odd.","outcome":"kind","best":true},{"text":"Stare and point too","consequence":"The person feels gawked at and uncomfortable.","outcome":"unkind"}],"debrief":"Staring can make someone feel uncomfortable; a kind word doesn't.","relearn":"You can gently stop staring and teasing of someone different.","persona":"respect","source":"respect"},
  {"id":"wm-1288","cat":"respect-me","type":"branch","hook":"A friend is told \"you can't sing, that's for girls.\"","options":[{"text":"Say \"anyone can sing, go for it\"","consequence":"They sing and enjoy it freely.","outcome":"fair","best":true},{"text":"Agree singing's for girls","consequence":"They give up something they love.","outcome":"unfair"}],"debrief":"Singing, like anything, isn't only for one gender.","relearn":"What someone loves doing isn't decided by their gender.","persona":"Ananya","source":"fairness"},
  {"id":"wm-1289","cat":"respect-me","type":"branch","hook":"Older kids tell you to laugh at a younger child who plays \"the wrong\" games.","options":[{"text":"Refuse and play with the younger child","consequence":"The younger child feels safe and happy.","outcome":"values","best":true},{"text":"Laugh to impress the older kids","consequence":"A little kid is hurt to make others laugh.","outcome":"missed"}],"debrief":"You don't have to be unkind to fit in with older kids.","relearn":"You can choose kindness even when bigger kids don't.","persona":"ally seed","source":"values"},
  {"id":"wm-1290","cat":"respect-me","type":"branch","hook":"A friend's name is hard for you to say and others mock it.","options":[{"text":"Practise it until you get it right","consequence":"Your friend feels their name matters.","outcome":"kind","best":true},{"text":"Give them an easier nickname instead","consequence":"They feel their real name was rejected.","outcome":"missed"}],"debrief":"Learning a name, even a tricky one, shows it matters.","relearn":"Trying to say someone's real name right is respect.","persona":"respect","source":"respect"},
  {"id":"wm-1291","cat":"respect-me","type":"branch","hook":"Your group decides to leave one kid out of the birthday plan.","options":[{"text":"Say \"let's include everyone\"","consequence":"No one is left feeling unwanted.","outcome":"kind","best":true},{"text":"Go along to keep the peace","consequence":"One kid is hurt on purpose.","outcome":"missed"}],"debrief":"Leaving someone out on purpose isn't kind; include everyone.","relearn":"You can speak up so no one is left out on purpose.","persona":"any","source":"inclusion"},
  {"id":"wm-1292","cat":"respect-me","type":"strike-rewrite","hook":"\"If I don't like how they are, I can ignore them.\"","myth":{"un":"If someone is different, I can ignore them like they're not there.","re":"Everyone deserves to be noticed and treated kindly.","why":"Being ignored on purpose hurts."},"relearn":"Everyone deserves to be noticed and treated kindly.","persona":"respect","source":"respect"},
  {"id":"wm-1293","cat":"respect-me","type":"strike-rewrite","hook":"\"Teasing is fine if everyone's laughing.\"","myth":{"un":"Teasing someone is fine as long as everyone's laughing.","re":"If one person is hurt, the teasing isn't really fun.","why":"Laughs don't make hurting someone okay."},"relearn":"If one person is hurt, the teasing isn't really fun.","persona":"respect","source":"respect"},
  {"id":"wm-1294","cat":"respect-me","type":"strike-rewrite","hook":"\"They have to earn my respect first.\"","myth":{"un":"People have to earn my respect before I'm kind to them.","re":"Everyone gets basic respect just for being a person.","why":"Kindness isn't a prize you make people win."},"relearn":"Everyone gets basic respect just for being a person.","persona":"respect","source":"respect"},
  {"id":"wm-1295","cat":"respect-me","type":"strike-rewrite","hook":"\"Saying sorry is for babies.\"","myth":{"un":"Saying sorry when you hurt someone is for babies.","re":"Saying sorry and trying again is something brave people do.","why":"It takes courage to admit a mistake."},"relearn":"Saying sorry and trying again is something brave people do.","persona":"respect","source":"repair"},
  {"id":"wm-1296","cat":"respect-me","type":"strike-rewrite","hook":"\"It's polite to make fun of how someone talks.\"","myth":{"un":"Copying how someone talks to get laughs is just a bit of fun.","re":"Mocking how someone speaks can really hurt them.","why":"Everyone's voice and way of talking is their own."},"relearn":"Mocking how someone speaks can really hurt them.","persona":"respect","source":"respect"},
  {"id":"wm-1297","cat":"respect-me","type":"strike-rewrite","hook":"\"If a grown-up is unkind, I should copy them.\"","myth":{"un":"If a grown-up says an unkind word, I should copy them.","re":"You can choose kind words even when a grown-up doesn't.","why":"Your choices about kindness are your own."},"relearn":"You can choose kind words even when a grown-up doesn't.","persona":"ally seed","source":"values"},
  {"id":"wm-1298","cat":"respect-me","type":"sort","hook":"Sort: respectful, or not respectful?","items":[{"id":"a","text":"Using the name someone asks for"},{"id":"b","text":"Mocking how someone walks"},{"id":"c","text":"Including the new kid"},{"id":"d","text":"Spreading a mean nickname"},{"id":"e","text":"Listening when a friend talks"},{"id":"f","text":"Staring to make someone feel odd"}],"bins":[{"id":"yes","label":"Respectful","valence":"pos"},{"id":"no","label":"Not respectful","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"Using names, including and listening are respect; mocking, mean names and staring aren't.","persona":"respect","source":"respect"},
  {"id":"wm-1299","cat":"respect-me","type":"sort","hook":"Sort: kind move, or unkind move?","items":[{"id":"a","text":"Saying sorry for a wrong name"},{"id":"b","text":"Laughing at a friend's tiffin"},{"id":"c","text":"Sharing a turn on the swing"},{"id":"d","text":"Leaving someone out on purpose"},{"id":"e","text":"Cheering on a quiet kid"},{"id":"f","text":"Copying a mean word"}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Saying sorry, sharing and cheering are kind; mocking, excluding and copying mean words aren't.","persona":"respect","source":"respect"},
  {"id":"wm-1300","cat":"respect-me","type":"sort","hook":"Sort: fair, or unfair?","items":[{"id":"a","text":"Anyone can join the game"},{"id":"b","text":"\"No girls allowed\""},{"id":"c","text":"Everyone gets a turn"},{"id":"d","text":"\"That's only for boys\""},{"id":"e","text":"Picking teams by who's there"},{"id":"f","text":"Leaving out a kid for their gender"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Letting anyone join and taking turns is fair; shutting people out for their gender isn't.","persona":"Ananya","source":"fairness"},
  {"id":"wm-1301","cat":"respect-me","type":"sort","hook":"Sort: this helps a teased friend, or this doesn't?","items":[{"id":"a","text":"Standing next to them"},{"id":"b","text":"Joining the teasing"},{"id":"c","text":"Saying \"you okay?\""},{"id":"d","text":"Laughing along"},{"id":"e","text":"Telling a teacher with them"},{"id":"f","text":"Pretending you didn't see"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"nothelp","label":"Doesn't help","valence":"neg"}],"key":{"a":"helps","b":"nothelp","c":"helps","d":"nothelp","e":"helps","f":"nothelp"},"relearn":"Standing by, checking in and telling a teacher help; laughing along or ignoring don't.","persona":"ally seed","source":"bystander"},
  {"id":"wm-1302","cat":"respect-me","type":"sort","hook":"Sort: shows you're listening, or shows you're not?","items":[{"id":"a","text":"Looking at your friend"},{"id":"b","text":"Talking over them"},{"id":"c","text":"Waiting your turn to speak"},{"id":"d","text":"Rolling your eyes"},{"id":"e","text":"Asking a friendly question"},{"id":"f","text":"Walking off mid-sentence"}],"bins":[{"id":"listen","label":"Listening","valence":"pos"},{"id":"notlisten","label":"Not listening","valence":"neg"}],"key":{"a":"listen","b":"notlisten","c":"listen","d":"notlisten","e":"listen","f":"notlisten"},"relearn":"Looking, waiting and asking show you're listening; talking over and walking off don't.","persona":"respect","source":"respect"},
  {"id":"wm-1325","cat":"respect-me","type":"sort","hook":"Sort: kind words, or unkind words?","items":[{"id":"a","text":"\"Want to play with us?\""},{"id":"b","text":"\"That's so weird.\""},{"id":"c","text":"\"You're doing great!\""},{"id":"d","text":"\"You can't sit here.\""},{"id":"e","text":"\"Sorry, my mistake.\""},{"id":"f","text":"\"Nobody likes you.\""}],"bins":[{"id":"kind","label":"Kind words","valence":"pos"},{"id":"unkind","label":"Unkind words","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Welcoming, cheering and saying sorry are kind words; \"weird\" and shutting people out aren't.","persona":"respect","source":"respect"},
  {"id":"wm-1303","cat":"respect-me","type":"reflect","hook":"Lensy: someone new joined your class today. What's a kind first move?","prompt":"Pick what feels right.","options":["Say hi and my name","Show them around","Ask them to sit with me","Smile and wave"],"affirm":"Any of those is a warm welcome. A small hello means a lot.","relearn":"A small, kind welcome helps someone new feel they belong.","persona":"respect","source":"inclusion"},
  {"id":"wm-1304","cat":"respect-me","type":"reflect","hook":"Lensy: a friend got teased and looked sad. How could you check on them?","prompt":"Pick a way that's you.","options":["Sit beside them quietly","Say \"you okay?\"","Share my snack","Walk home with them"],"affirm":"That's kind. Just being there tells a friend they're not alone.","relearn":"Being there for a teased friend tells them they're not alone.","persona":"Faizan-type","source":"support"},
  {"id":"wm-1305","cat":"respect-me","type":"reflect","hook":"Lensy: you got someone's name wrong. What feels right to do?","prompt":"Pick one.","options":["Say sorry","Use the right name now","Ask them to remind me","All of these"],"affirm":"Lovely. Fixing a name is an easy, kind thing to do.","relearn":"Saying sorry and using the right name is a kind, easy fix.","persona":"respect","source":"repair"},
  {"id":"wm-1306","cat":"respect-me","type":"reflect","hook":"Lensy: what does respect look like in your home or class?","prompt":"Pick one you've seen.","options":["Taking turns to talk","Sharing things","Using kind words","Helping each other"],"affirm":"Yes! Respect shows up in small everyday things like that.","relearn":"Respect shows up in small, everyday actions.","persona":"respect","source":"respect"},
  {"id":"wm-1307","cat":"respect-me","type":"reflect","hook":"Lensy: a friend is different from you in some way. What could you be curious about?","prompt":"Pick something.","options":["Their favourite game","Their festivals","Their food","Their name's meaning"],"affirm":"Curiosity, asked kindly, is a friendly way to know someone.","relearn":"Kind curiosity is a friendly way to get to know someone.","persona":"any","source":"inclusion"},
  {"id":"wm-1308","cat":"respect-me","type":"reflect","hook":"Lensy: someone stood up for you once. How did it feel?","prompt":"Pick what fits.","options":["Safe","Less alone","Happy","Grateful"],"affirm":"That feeling is why standing up for others matters so much.","relearn":"Standing up for someone helps them feel safe and less alone.","persona":"ally seed","source":"support"},
  {"id":"wm-1309","cat":"respect-me","type":"match","hook":"Match the moment to the kind reply.","pairs":[{"left":"Friend says \"call me Veer\"","right":"\"Okay, Veer!\""},{"left":"You used the wrong name","right":"\"Sorry, I'll get it right.\""},{"left":"A new kid sits alone","right":"\"Come sit with us!\""},{"left":"A friend is teased","right":"\"That's not kind, stop.\""},{"left":"A friend likes 'other-gender' toys","right":"\"Cool, let's play!\""}],"relearn":"Each kind reply uses a name, repairs, includes, defends or accepts a friend.","persona":"respect","source":"respect"},
  {"id":"wm-1310","cat":"respect-me","type":"match","hook":"Match the action to what it shows.","pairs":[{"left":"Using someone's chosen name","right":"Respect"},{"left":"Letting everyone join the game","right":"Fairness"},{"left":"Saying sorry and retrying","right":"Repair"},{"left":"Sitting with a lonely kid","right":"Kindness"},{"left":"Stopping a mean nickname","right":"Standing up"}],"relearn":"Names show respect, including shows fairness, sorry repairs, sitting shows kindness, stopping a name is standing up.","persona":"respect","source":"respect"},
  {"id":"wm-1311","cat":"respect-me","type":"match","hook":"Match the unkind move to a kinder one.","pairs":[{"left":"Laughing at a friend's food","right":"Asking to try a bite"},{"left":"Mocking how someone talks","right":"Listening patiently"},{"left":"Leaving a kid out","right":"Inviting them in"},{"left":"Staring to make someone feel odd","right":"Smiling hello"},{"left":"Spreading a mean name","right":"Using their real name"}],"relearn":"Every unkind move has a kinder swap: try, listen, invite, smile, use real names.","persona":"respect","source":"respect"},
  {"id":"wm-1312","cat":"respect-me","type":"match","hook":"Match who's speaking to their respectful line.","pairs":[{"left":"Welcoming a new friend","right":"\"Want to play?\""},{"left":"Checking on a sad friend","right":"\"You okay? I'm here.\""},{"left":"A friend asks for 'they'","right":"\"Sure, thanks.\""},{"left":"Someone teases a classmate","right":"\"Leave them alone.\""},{"left":"You forgot a name","right":"\"Remind me your name?\""}],"relearn":"Welcoming, checking in, using people's words, defending and asking names show respect.","persona":"respect","source":"respect"},
  {"id":"wm-1313","cat":"respect-me","type":"match","hook":"Match the situation to the fair thing to do.","pairs":[{"left":"\"No girls in this game\"","right":"\"Anyone can play.\""},{"left":"Same kid always left out","right":"Pick them this time"},{"left":"One kid never gets a turn","right":"\"Your turn next.\""},{"left":"A friend can't keep up","right":"Slow down for them"},{"left":"Birthday plan skips a kid","right":"\"Let's invite everyone.\""}],"relearn":"Fairness means anyone can play, everyone gets a turn, and no one is skipped.","persona":"Ananya","source":"fairness"},
  {"id":"wm-1314","cat":"respect-me","type":"match","hook":"Match the kind habit to its everyday example.","pairs":[{"left":"Use the name people give","right":"\"Hi Aarav!\""},{"left":"Don't tease who someone is","right":"No copying mean words"},{"left":"Say sorry and retry","right":"\"My mistake, sorry.\""},{"left":"Include everyone","right":"\"Come join us!\""},{"left":"Stand up for a friend","right":"\"That's not fair.\""}],"relearn":"The respect habits: use names, don't tease, say sorry, include, stand up.","persona":"respect","source":"respect"},
  {"id":"wm-1315","cat":"respect-me","type":"match","hook":"Match the feeling to the kind thing that helps it.","pairs":[{"left":"Feeling left out","right":"Being invited in"},{"left":"Feeling teased","right":"Someone standing up"},{"left":"Feeling unheard","right":"Someone listening"},{"left":"Feeling unsure of a welcome","right":"A friendly hello"},{"left":"Feeling hurt by a mistake","right":"A real \"sorry\""}],"relearn":"Inviting, defending, listening, greeting and apologising each ease a hurt feeling.","persona":"respect","source":"respect"},
  {"id":"wm-1316","cat":"respect-me","type":"match","hook":"Match the word to what it means in respect.","pairs":[{"left":"Include","right":"Make sure no one's left out"},{"left":"Apologise","right":"Say sorry and mean it"},{"left":"Listen","right":"Hear someone out fully"},{"left":"Defend","right":"Stand up for someone"},{"left":"Welcome","right":"Help someone feel they belong"}],"relearn":"Include, apologise, listen, defend and welcome are the words of respect in action.","persona":"respect","source":"respect"},
  {"id":"wm-1317","cat":"respect-me","type":"build","hook":"A new kid joins your class.","prompt":"Build a kind welcome. Pick the moves that help.","pieces":["Say hi and your name","Ask their name","Show them around","Invite them to sit with you","Whisper about them","Ignore them"],"mode":"assemble","key":["Say hi and your name","Ask their name","Show them around","Invite them to sit with you"],"relearn":"A kind welcome is saying hi, asking their name, showing around and inviting them in.","persona":"respect","source":"inclusion"},
  {"id":"wm-1318","cat":"respect-me","type":"build","hook":"You called a classmate the wrong name.","prompt":"Build the repair, in order.","pieces":["Notice your mistake","Say sorry","Use the right name","Keep using it"],"mode":"sequence","key":["Notice your mistake","Say sorry","Use the right name","Keep using it"],"relearn":"Repair a name like this: notice, say sorry, use the right one, and keep it up.","persona":"respect","source":"repair"},
  {"id":"wm-1319","cat":"respect-me","type":"build","hook":"A friend is being teased for who they are.","prompt":"Build a way to help. Pick the kind moves.","pieces":["Say \"that's not kind\"","Stand beside them","Ask if they're okay","Tell a teacher together","Join the teasing","Walk away from them"],"mode":"assemble","key":["Say \"that's not kind\"","Stand beside them","Ask if they're okay","Tell a teacher together"],"relearn":"Helping a teased friend: speak up, stand beside, check in, and tell a teacher together.","persona":"ally seed","source":"bystander"},
  {"id":"wm-1320","cat":"respect-me","type":"build","hook":"Your group is picking teams for a game.","prompt":"Build a fair way to pick. Choose the fair moves.","pieces":["Make sure everyone's in","Give everyone a turn","Mix up the teams","Cheer everyone on","Leave the slow kid out","Say \"no girls\""],"mode":"assemble","key":["Make sure everyone's in","Give everyone a turn","Mix up the teams","Cheer everyone on"],"relearn":"A fair game includes everyone, gives turns, mixes teams and cheers everyone on.","persona":"Ananya","source":"fairness"},
  {"id":"wm-1321","cat":"respect-me","type":"build","hook":"A friend tells you their chosen name and word for themself.","prompt":"Build the respectful response, in order.","pieces":["Listen","Say thanks for telling me","Use their name and word","Keep using them"],"mode":"sequence","key":["Listen","Say thanks for telling me","Use their name and word","Keep using them"],"relearn":"When a friend shares their name and word: listen, thank them, use them, keep it up.","persona":"respect","source":"respect"},
  {"id":"wm-1322","cat":"respect-me","type":"build","hook":"What goes into treating everyone with respect?","prompt":"Build the respect kit. Pick the pieces that belong.","pieces":["Use people's names","Don't tease who they are","Say sorry and retry","Include everyone","Make them be like you","Decide who's 'normal'"],"mode":"assemble","key":["Use people's names","Don't tease who they are","Say sorry and retry","Include everyone"],"relearn":"The respect kit: use names, don't tease, say sorry, and include everyone.","persona":"respect","source":"respect"},
  {"id":"wm-1323","cat":"respect-me","type":"build","hook":"A friend mixed up your name; you want to gently fix it.","prompt":"Build a kind way to ask, in order.","pieces":["Smile, don't get cross","Say \"it's actually...\"","Say your real name","Say \"thanks!\" when they get it"],"mode":"sequence","key":["Smile, don't get cross","Say \"it's actually...\"","Say your real name","Say \"thanks!\" when they get it"],"relearn":"You can fix your name kindly: smile, correct gently, say it, and thank them.","persona":"be-yourself","source":"voice"},
  {"id":"wm-1324","cat":"respect-me","type":"build","hook":"A classmate eats alone because kids tease their food.","prompt":"Build a way to be a friend. Pick the kind moves.","pieces":["Sit with them","Ask about their food","Try a bite","Tell others to stop","Say \"yuck\" too","Move tables away"],"mode":"assemble","key":["Sit with them","Ask about their food","Try a bite","Tell others to stop"],"relearn":"Be a friend at lunch: sit with them, ask, try a bite, and tell teasers to stop.","persona":"ally seed","source":"inclusion"},
  {"id":"wm-990","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Sex and gender are the very same thing.\"","myth":{"un":"Sex and gender are the very same thing.","re":"Sex is the body you're born with; gender is who you know you are inside.","why":"One is about the body, one is about your inside-self."},"relearn":"Sex is the body; gender is who you know you are inside.","persona":"gender thread","source":"UNESCO 3.1"},
  {"id":"wm-991","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"A doctor's first 'it's a boy!' decides who you are inside.\"","myth":{"un":"A doctor's first 'it's a boy!' decides who you are inside.","re":"That guess is about your body; only you grow to know your inside-self.","why":"Your inside-self is yours to know, not a first glance."},"relearn":"A first guess is about the body; your inside-self is yours to know.","persona":"gender thread","source":"sex vs gender"},
  {"id":"wm-992","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Short hair means a kid must be a boy.\"","myth":{"un":"Short hair means a kid must be a boy.","re":"You can't tell a kid's gender from their hair; gender is who they know inside.","why":"Looks don't show an inside-self."},"relearn":"You can't tell someone's gender from how they look.","persona":"any","source":"gender vs expression"},
  {"id":"wm-993","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"You can spot anyone's gender just by looking once.\"","myth":{"un":"You can spot anyone's gender just by looking once.","re":"You can't; gender is who someone knows they are inside, not what you see.","why":"An inside-self isn't on the outside."},"relearn":"You can't know someone's gender just by looking.","persona":"any","source":"gender vs expression"},
  {"id":"wm-994","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"If everyone says you're a certain way, then that must be the real you.\"","myth":{"un":"If everyone says you're a certain way, that must be the real you.","re":"What you feel inside counts even when others guess differently.","why":"People on the outside can guess wrong; your inside-self is the true one."},"relearn":"Your inside-self stays true even if others guess wrong.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-995","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Feeling like a different gender is just a passing phase to fix.\"","myth":{"un":"Feeling like a different gender is just a phase to fix.","re":"For most kids who they are inside is settled by school age, and it's okay.","why":"It's a normal part of who people are, not a problem."},"relearn":"Who you are inside is usually settled early, and that's okay.","persona":"gender thread","source":"gender development"},
  {"id":"wm-996","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Everyone in the world is only a boy or a girl.\"","myth":{"un":"Everyone is only a boy or a girl, with nothing else.","re":"Most feel like a boy or girl; some feel like neither or both, and that's real.","why":"There are more ways to be than just two."},"relearn":"Some people feel like neither or both, and that's real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-997","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"You have to prove your gender to other people.\"","myth":{"un":"You have to prove your gender to other people.","re":"You never have to prove who you are; you simply know it inside.","why":"Knowing yourself is enough; no test needed."},"relearn":"You never have to prove who you are.","persona":"be-yourself","source":"self-knowledge"},
  {"id":"wm-998","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Liking dolls turns a boy into a girl inside.\"","myth":{"un":"Liking dolls turns a boy into a girl inside.","re":"What you play with doesn't change your gender; who you are inside stays yours.","why":"Toys are just toys, not your inside-self."},"relearn":"What you like doesn't change who you are inside.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-999","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"If a baby's body looks one way, their inside-self must match.\"","myth":{"un":"If a baby's body looks one way, their inside-self must match.","re":"For most they match; for some they differ, and both are real and okay.","why":"Body and inside-self are two different things."},"relearn":"Body and inside-self match for most and differ for some; both are okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1000","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Clothes are what really tell you a person's gender.\"","myth":{"un":"Clothes are what tell you a person's gender.","re":"Clothes don't show gender; gender is who someone knows they are inside.","why":"Anyone can wear anything; it doesn't reveal an inside-self."},"relearn":"Clothes don't tell you someone's gender.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1001","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"Knowing you're a boy or a girl is something a grown-up teaches you.\"","myth":{"un":"A grown-up teaches you whether you're a boy or a girl.","re":"Grown-ups can guess, but who you are inside is something you come to know.","why":"Your inside-self is yours to feel, not handed to you."},"relearn":"Who you are inside is yours to know.","persona":"gender thread","source":"self-identification"},
  {"id":"wm-1002","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"A voice or a name tells you exactly what someone's gender is.\"","myth":{"un":"A voice or a name tells you exactly someone's gender.","re":"They don't; the kind way is to let people tell you who they are.","why":"Only the person knows their own inside-self."},"relearn":"Let people tell you who they are.","persona":"respect","source":"gender vs expression"},
  {"id":"wm-1003","cat":"sex-and-gender","type":"strike-rewrite","hook":"\"What's on the outside matters more than who you are inside.\"","myth":{"un":"The outside matters more than who you know you are inside.","re":"Who you know you are inside is the real you; the outside is just one part.","why":"Your inside-self is the part only you truly know."},"relearn":"Who you know you are inside is the real you.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-1004","cat":"sex-and-gender","type":"match","hook":"Match each thing to the body or to inside-self.","pairs":[{"left":"The parts you're born with","right":"About the body"},{"left":"Who you know you are","right":"About inside-self"},{"left":"What a first glance sees","right":"The body, only"},{"left":"A feeling that's truly yours","right":"Inside-self, only"},{"left":"What only you can know","right":"Inside-self, yours alone"}],"relearn":"Some things are about the body (sex); some about inside-self (gender).","persona":"educator","source":"sex vs gender"},
  {"id":"wm-1005","cat":"sex-and-gender","type":"match","hook":"Match each kid's words to what they're telling you.","pairs":[{"left":"\"I'm a boy\"","right":"He knows his inside-self"},{"left":"\"I'm a girl\"","right":"She knows her inside-self"},{"left":"\"I feel like both\"","right":"They know their inside-self"},{"left":"\"Call me Meera\"","right":"The name to kindly use"},{"left":"\"I'm still figuring it out\"","right":"That's okay; give them time"}],"relearn":"Let each kid tell you who they are; that's theirs to know.","persona":"gender thread","source":"self-identification"},
  {"id":"wm-1006","cat":"sex-and-gender","type":"match","hook":"Match each simple sentence to the right word.","pairs":[{"left":"The body you're born with","right":"Sex"},{"left":"Who you know you are inside","right":"Gender"},{"left":"Letting others be themselves","right":"Respect"},{"left":"The name people call you","right":"Your name"},{"left":"The one-of-a-kind you","right":"Inside-self"}],"relearn":"Sex is the body; gender is who you know inside; respect is letting people be.","persona":"educator","source":"body literacy"},
  {"id":"wm-1007","cat":"sex-and-gender","type":"match","hook":"Match how to be kind when you meet someone new.","pairs":[{"left":"Not sure if boy or girl?","right":"Ask their name and use it"},{"left":"They tell you their gender","right":"Believe them"},{"left":"You used the wrong name","right":"Say sorry and try again"},{"left":"A friend feels different inside","right":"Tell them that's okay"},{"left":"Someone is figuring it out","right":"Give them time"}],"relearn":"Let people tell you who they are, and use the name they give.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1008","cat":"sex-and-gender","type":"match","hook":"Match the question to who can answer it best.","pairs":[{"left":"What is my name?","right":"Me, and the grown-ups who named me"},{"left":"Who am I inside?","right":"Only me"},{"left":"Am I a boy, girl, or both?","right":"Only I truly know"},{"left":"What body was I born with?","right":"A doctor first saw it"},{"left":"Who decides my inside-self?","right":"No one but me"}],"relearn":"Only you can answer who you are inside.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-1009","cat":"sex-and-gender","type":"match","hook":"Match each true thing to finish the sentence.","pairs":[{"left":"For most people, body and inside-self...","right":"match"},{"left":"For some people, they...","right":"differ, and that's okay"},{"left":"Your gender is who you...","right":"know you are inside"},{"left":"You can tell gender by looks...","right":"no, you can't"},{"left":"Who decides who you are?","right":"only you"}],"relearn":"For most, body and inside-self match; for some they differ, and that's okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1010","cat":"sex-and-gender","type":"match","hook":"Match each kid to a kind reply.","pairs":[{"left":"\"My name is Aarav, I'm a boy\"","right":"\"Hi Aarav! Want to play?\""},{"left":"\"I'm a girl, my name is Diya\"","right":"\"Nice to meet you, Diya!\""},{"left":"\"I feel like neither\"","right":"\"That's okay, what's your name?\""},{"left":"\"I like being called they\"","right":"\"Okay, I'll remember that\""},{"left":"\"I'm not sure yet\"","right":"\"No rush, I'm your friend\""}],"relearn":"Use the name and words a friend gives you; that's respect.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1011","cat":"sex-and-gender","type":"match","hook":"Match each thing to whether you can SEE it or only the person KNOWS it.","pairs":[{"left":"Someone's haircut","right":"You can see it"},{"left":"Who they are inside","right":"Only they know it"},{"left":"The clothes they wear","right":"You can see those"},{"left":"Their gender","right":"They know it inside"},{"left":"What body they were born with","right":"A doctor first saw it"}],"relearn":"You can see looks; only the person knows their gender inside.","persona":"gender thread","source":"gender vs expression"},
  {"id":"wm-1012","cat":"sex-and-gender","type":"match","hook":"Match the start of each true sentence to its end.","pairs":[{"left":"Sex is about your...","right":"body"},{"left":"Gender is about your...","right":"inside-self"},{"left":"For some kids, the two...","right":"differ, and that's real"},{"left":"You never have to...","right":"prove who you are"},{"left":"The kind thing is to...","right":"use the name they give"}],"relearn":"Sex is the body; gender is the inside-self; you never have to prove it.","persona":"educator","source":"sex vs gender"},
  {"id":"wm-1013","cat":"sex-and-gender","type":"match","hook":"Match each kid's hobby to what it tells you about their gender.","pairs":[{"left":"A boy who loves cooking","right":"Still a boy inside"},{"left":"A girl who plays cricket","right":"Still a girl inside"},{"left":"A kid who loves dancing","right":"Gender is unchanged"},{"left":"What a hobby shows about gender","right":"Nothing at all"},{"left":"Who knows a kid's gender","right":"Only that kid"}],"relearn":"What you like doesn't decide or change your gender.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1014","cat":"sex-and-gender","type":"match","hook":"Match each word to its opposite idea.","pairs":[{"left":"Sex (the body)","right":"Gender (the inside-self)"},{"left":"What others guess","right":"What only you know"},{"left":"Telling by looks","right":"Letting people tell you"},{"left":"Having to prove it","right":"Simply knowing it"},{"left":"One or two boxes","right":"Many ways to be"}],"relearn":"Gender is who you know inside, not what others guess from looks.","persona":"gender thread","source":"sex vs gender"},
  {"id":"wm-1015","cat":"sex-and-gender","type":"reflect","hook":"Lensy: where does your gender live?","prompt":"What feels true to you?","options":["Inside me","In my heart","In the me only I know"],"affirm":"Yes, your gender is who you know you are inside.","relearn":"Gender is who you know you are inside.","persona":"any","source":"UNESCO 3.1"},
  {"id":"wm-1016","cat":"sex-and-gender","type":"reflect","hook":"Lensy: when your heart feels something true, who feels it first?","prompt":"Choose one.","options":["My own heart","I feel it inside","Nobody feels it for me"],"affirm":"Your feelings live in you, and that's how you come to know yourself.","relearn":"Your own feelings help you know who you are.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-1017","cat":"sex-and-gender","type":"reflect","hook":"Lensy: a new friend says their name. What's nice to do?","prompt":"Pick what feels kind.","options":["Use their name","Remember it","Say it back warmly"],"affirm":"Lovely. Using the name someone gives is a kind way to show respect.","relearn":"Use the name someone gives you; it shows respect.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1018","cat":"sex-and-gender","type":"reflect","hook":"Lensy: a kid's body and inside-self differ. Is that okay?","prompt":"What do you feel?","options":["Yes, that's okay","It's real","Everyone's me is fine"],"affirm":"Yes. For some people they differ, and that is real and okay.","relearn":"For some, body and inside-self differ, and that's real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1019","cat":"sex-and-gender","type":"reflect","hook":"Lensy: can you tell someone's gender by their clothes?","prompt":"What do you think?","options":["No","Only they know inside","Looks don't tell you"],"affirm":"Right. You can't tell gender from clothes; only the person knows inside.","relearn":"You can't tell someone's gender from how they look.","persona":"any","source":"gender vs expression"},
  {"id":"wm-1020","cat":"sex-and-gender","type":"reflect","hook":"Lensy: do you ever have to prove who you are?","prompt":"What feels true?","options":["No","I just know me","Knowing is enough"],"affirm":"That's right. You never have to prove who you are; knowing is enough.","relearn":"You never have to prove who you are.","persona":"be-yourself","source":"self-knowledge"},
  {"id":"wm-1021","cat":"sex-and-gender","type":"reflect","hook":"Lensy: someone feels like neither a boy nor a girl. How does that sound?","prompt":"What do you think?","options":["That's real","It's okay","Many ways to be"],"affirm":"Yes. Some feel like neither or both, and that's a real way to be.","relearn":"Some people feel like neither or both, and that's real.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1022","cat":"sex-and-gender","type":"reflect","hook":"Lensy: a friend tells you something true about themselves. How do you treat it?","prompt":"Choose one.","options":["Like a gift","Gently and kindly","I believe them"],"affirm":"When someone shares who they are, treating it gently is real respect.","relearn":"Hold what someone shares about themselves with care.","persona":"respect","source":"respect"},
  {"id":"wm-1023","cat":"sex-and-gender","type":"reflect","hook":"Lensy: the word for the body you're born with is...?","prompt":"Pick the one that fits.","options":["Sex","The body word","Body you're born with"],"affirm":"Yes, sex is the body you're born with.","relearn":"Sex is the body you're born with.","persona":"educator","source":"UNESCO 3.1"},
  {"id":"wm-1024","cat":"sex-and-gender","type":"reflect","hook":"Lensy: a friend tells you their gender. Do you believe them?","prompt":"What feels right?","options":["Yes","They know best","Of course"],"affirm":"Yes. People know their own inside-self, so we believe them.","relearn":"People know their own inside-self; believe them.","persona":"respect","source":"self-identification"},
  {"id":"wm-1025","cat":"sex-and-gender","type":"reflect","hook":"Lensy: is it okay to still be figuring out who you are?","prompt":"What do you feel?","options":["Yes","No rush","I can take my time"],"affirm":"Yes. It's okay to take your time; a trusted grown-up can help.","relearn":"It's okay to take your time figuring out who you are.","persona":"be-yourself","source":"self-knowledge"},
  {"id":"wm-1026","cat":"sex-and-gender","type":"reflect","hook":"Lensy: your gender is one part of you. How many parts make the whole you?","prompt":"What do you think?","options":["Many","Lots of parts","More than one"],"affirm":"Yes, you're made of many parts, and gender is just one of them.","relearn":"Your gender is one part among many that make you.","persona":"any","source":"self-concept"},
  {"id":"wm-1027","cat":"sex-and-gender","type":"reflect","hook":"Lensy: a doctor's first 'it's a girl!' was about your...?","prompt":"Pick the one that fits.","options":["Body","Body you were born with","The outside, at first"],"affirm":"Right. That first guess was about the body; gender is who you grow to know.","relearn":"A first guess is about the body; gender is who you grow to know.","persona":"educator","source":"sex vs gender"},
  {"id":"wm-1028","cat":"sex-and-gender","type":"reflect","hook":"Lensy: who gets to decide who you are inside?","prompt":"What feels true?","options":["Only me","Me, no one else","It's mine to know"],"affirm":"Yes. No one else decides; who you are inside is yours.","relearn":"No one else decides who you are inside.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-1029","cat":"sex-and-gender","type":"branch","hook":"A new classmate says, \"I'm a girl, call me Tara.\" A boy giggles.","options":[{"text":"\"Hi Tara, want to sit with us?\"","consequence":"Tara feels welcomed.","outcome":"kind","best":true},{"text":"Giggle along too","consequence":"Tara feels left out over who she is.","outcome":"unkind"},{"text":"Say nothing","consequence":"Tara still feels unsure she belongs.","outcome":"passive"}],"debrief":"Use the name a friend gives you; it's a kind way to show respect.","relearn":"Use the name a friend gives; it shows respect.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1030","cat":"sex-and-gender","type":"branch","hook":"A kid at the park: boy or girl? You can't tell, and you want to play.","options":[{"text":"\"Hi! What's your name?\" and use it","consequence":"A new friend, the kind way.","outcome":"kind","best":true},{"text":"Loudly: \"Are you a boy or a girl?\"","consequence":"The kid feels put on the spot.","outcome":"unkind"},{"text":"Guess the wrong thing","consequence":"They feel unseen.","outcome":"careless"}],"debrief":"Let people tell you who they are; using their name is enough.","relearn":"Let people tell you who they are; use their name.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1031","cat":"sex-and-gender","type":"branch","hook":"Your cousin says, \"My body and inside-self don't match.\"","options":[{"text":"\"That's okay, you're still you\"","consequence":"Your cousin feels safe.","outcome":"kind","best":true},{"text":"\"That's not possible\"","consequence":"Your cousin is hurt over something real.","outcome":"unkind"},{"text":"Change the subject","consequence":"Your cousin feels unheard.","outcome":"passive"}],"debrief":"For some people body and inside-self differ; that's real and okay.","relearn":"For some, body and inside-self differ, and that's real and okay.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1032","cat":"sex-and-gender","type":"branch","hook":"A friend says \"Boys can't have long hair, so you're not a boy.\"","options":[{"text":"\"Hair doesn't decide that; I'm a boy\"","consequence":"You stand up for yourself, calmly.","outcome":"strong","best":true},{"text":"Believe them","consequence":"You feel small over an untrue idea.","outcome":"sad"},{"text":"Cut your hair to prove it","consequence":"You change for a wrong idea.","outcome":"unfair"}],"debrief":"Hair doesn't decide gender; you know who you are inside.","relearn":"Looks don't decide your gender; you know it inside.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1033","cat":"sex-and-gender","type":"branch","hook":"You called a new friend the wrong name; they look upset.","options":[{"text":"\"Sorry! I'll get it right\"","consequence":"Your friend feels respected; mistake mended.","outcome":"kind","best":true},{"text":"\"It's not a big deal\"","consequence":"Your friend feels brushed off.","outcome":"unkind"},{"text":"Keep using the wrong name","consequence":"Your friend feels hurt.","outcome":"unkind"}],"debrief":"Mistakes happen: say sorry and try again; that's kind.","relearn":"Say sorry and try again; that's kind.","persona":"respect","source":"respect"},
  {"id":"wm-1034","cat":"sex-and-gender","type":"branch","hook":"You feel unsure about who you are inside, and it's on your mind.","options":[{"text":"Tell a trusted grown-up","consequence":"You don't carry it alone; they help.","outcome":"safe","best":true},{"text":"Keep it secret and worry","consequence":"The worry sits heavy.","outcome":"lonely"},{"text":"Decide you're 'wrong'","consequence":"You feel bad over something okay.","outcome":"sad"}],"debrief":"It's okay to feel unsure; a trusted grown-up can help you.","relearn":"If you feel unsure, a trusted grown-up can help; don't carry it alone.","persona":"be-yourself","source":"self-knowledge"},
  {"id":"wm-1035","cat":"sex-and-gender","type":"branch","hook":"Kids argue whether a classmate is 'really' a boy or a girl.","options":[{"text":"\"Only they know: let's ask their name\"","consequence":"The argument stops; they're respected.","outcome":"kind","best":true},{"text":"Pick a side and argue","consequence":"They feel talked-about, not seen.","outcome":"unkind"},{"text":"Vote on it","consequence":"A vote can't decide an inside-self.","outcome":"unfair"}],"debrief":"No one votes on who you are; only you know your inside-self.","relearn":"Only you know your inside-self; no one votes on it.","persona":"gender thread","source":"self-identification"},
  {"id":"wm-1036","cat":"sex-and-gender","type":"role-play","hook":"At the park, a kid you just met has short hair and a pink kurta. A friend whispers, \"Ask if it's a boy or girl.\"","setup":"What do you do?","yourLine":[{"text":"Just play together and learn their name as you go","best":true},{"text":"Stop the game to ask them which one they are"}],"relearn":"You don't need to label someone to play and be kind.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1037","cat":"sex-and-gender","type":"role-play","hook":"A friend teases you: \"You can't be a boy, you like pink!\"","setup":"Stand up for yourself, kindly. Say:","yourLine":[{"text":"\"Pink is just a colour. I know I'm a boy.\"","best":true},{"text":"\"...maybe you're right.\""}],"relearn":"What you like doesn't change who you are inside.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1038","cat":"sex-and-gender","type":"role-play","hook":"Your friend says, \"I think I'm a different gender than people called me.\"","setup":"Be a kind friend. Say:","yourLine":[{"text":"\"Thank you for telling me. You're still my friend.\"","best":true},{"text":"\"That's so weird.\""}],"relearn":"When a friend tells you who they are, believe and welcome them.","persona":"respect","source":"self-identification"},
  {"id":"wm-1039","cat":"sex-and-gender","type":"role-play","hook":"Someone asks you, \"How do you KNOW you're a girl?\"","setup":"Answer in your own calm way. Say:","yourLine":[{"text":"\"I just know it inside. That part is mine.\"","best":true},{"text":"\"...I'm not sure I'm allowed to know.\""}],"relearn":"You know your inside-self; you don't have to prove it.","persona":"be-yourself","source":"self-knowledge"},
  {"id":"wm-1040","cat":"sex-and-gender","type":"role-play","hook":"A classmate keeps calling your friend the wrong name on purpose.","setup":"Step in for your friend. Say:","yourLine":[{"text":"\"Their name is Riya. Let's call her that.\"","best":true},{"text":"\"...\" (say nothing)"}],"relearn":"Using the wrong name on purpose isn't kind; you can step in.","persona":"ally seed","source":"respect / voice"},
  {"id":"wm-1041","cat":"sex-and-gender","type":"role-play","hook":"A younger kid asks you, \"What's the difference between sex and gender?\"","setup":"Explain it simply. Say:","yourLine":[{"text":"\"Sex is the body you're born with; gender is who you know you are inside.\"","best":true},{"text":"\"They're the exact same thing.\""}],"relearn":"Sex is the body; gender is who you know you are inside.","persona":"educator","source":"UNESCO 3.1"},
  {"id":"wm-1042","cat":"sex-and-gender","type":"role-play","hook":"A friend says, \"I feel like neither a boy nor a girl.\"","setup":"Be warm and kind. Say:","yourLine":[{"text":"\"Okay! That's a real way to be. You're still my friend.\"","best":true},{"text":"\"You have to pick one.\""}],"relearn":"Some feel like neither or both; that's a real way to be.","persona":"gender thread","source":"gender diversity"},
  {"id":"wm-1043","cat":"sex-and-gender","type":"sort","hook":"Sort each thing: about the body, or about your inside-self?","items":[{"id":"a","text":"The parts you were born with"},{"id":"b","text":"Who you know you are"},{"id":"c","text":"What a doctor first saw"},{"id":"d","text":"The feeling of being you"},{"id":"e","text":"Your body's shape at birth"},{"id":"f","text":"What only you can know"}],"bins":[{"id":"sex","label":"About the body (sex)","valence":"neutral"},{"id":"gender","label":"About inside-self (gender)","valence":"neutral"}],"key":{"a":"sex","b":"gender","c":"sex","d":"gender","e":"sex","f":"gender"},"relearn":"Some things are about the body (sex); some about inside-self (gender).","persona":"educator","source":"sex vs gender"},
  {"id":"wm-1044","cat":"sex-and-gender","type":"sort","hook":"Sort each one: can you SEE it from outside, or does only the PERSON know it?","items":[{"id":"a","text":"A haircut"},{"id":"b","text":"Their gender"},{"id":"c","text":"The clothes they wear"},{"id":"d","text":"Who they are inside"},{"id":"e","text":"Their shoes"},{"id":"f","text":"How they truly feel about themselves"}],"bins":[{"id":"see","label":"You can see it","valence":"neutral"},{"id":"know","label":"Only they know it","valence":"neutral"}],"key":{"a":"see","b":"know","c":"see","d":"know","e":"see","f":"know"},"relearn":"You can see looks; only the person knows their gender inside.","persona":"gender thread","source":"gender vs expression"},
  {"id":"wm-1045","cat":"sex-and-gender","type":"sort","hook":"Sort each idea: is it TRUE, or a MYTH we don't believe?","items":[{"id":"a","text":"Only you know your inside-self"},{"id":"b","text":"You can tell gender by looks"},{"id":"c","text":"Body and inside-self can differ"},{"id":"d","text":"You must prove your gender"},{"id":"e","text":"Some feel like neither or both"},{"id":"f","text":"Liking pink changes who you are"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"You can't tell gender by looks, and what you like doesn't change who you are.","persona":"gender thread","source":"gender vs expression"},
  {"id":"wm-1046","cat":"sex-and-gender","type":"sort","hook":"Sort each into the right word it describes.","items":[{"id":"a","text":"The body you're born with"},{"id":"b","text":"Who you know you are inside"},{"id":"c","text":"Parts the doctor first saw"},{"id":"d","text":"A feeling that is truly yours"},{"id":"e","text":"What a first glance can show"},{"id":"f","text":"The you only you know best"}],"bins":[{"id":"sex","label":"Sex","valence":"neutral"},{"id":"gender","label":"Gender","valence":"neutral"}],"key":{"a":"sex","b":"gender","c":"sex","d":"gender","e":"sex","f":"gender"},"relearn":"Sex is about the body; gender is who you know you are inside.","persona":"educator","source":"sex vs gender"},
  {"id":"wm-1047","cat":"sex-and-gender","type":"sort","hook":"Sort each thing: does it DECIDE your gender, or is it just what you like?","items":[{"id":"a","text":"Who you know you are inside"},{"id":"b","text":"Your favourite colour"},{"id":"c","text":"Your own true feeling of you"},{"id":"d","text":"The toys you play with"},{"id":"e","text":"Only you, knowing yourself"},{"id":"f","text":"The clothes you like"}],"bins":[{"id":"decides","label":"Decides your gender","valence":"neutral"},{"id":"likes","label":"Just what you like","valence":"neutral"}],"key":{"a":"decides","b":"likes","c":"decides","d":"likes","e":"decides","f":"likes"},"relearn":"Only you, inside, decides your gender; the rest is what you like.","persona":"Reyansh","source":"gender vs expression"},
  {"id":"wm-1048","cat":"sex-and-gender","type":"sort","hook":"Sort who can answer each question: only YOU, or a GROWN-UP who was there.","items":[{"id":"a","text":"Who am I inside?"},{"id":"b","text":"What body was I born with?"},{"id":"c","text":"Am I a boy, girl, or both?"},{"id":"d","text":"What did the doctor first see?"},{"id":"e","text":"Who decides my inside-self?"},{"id":"f","text":"When was I born?"}],"bins":[{"id":"you","label":"Only you know","valence":"neutral"},{"id":"grownup","label":"A grown-up was there","valence":"neutral"}],"key":{"a":"you","b":"grownup","c":"you","d":"grownup","e":"you","f":"grownup"},"relearn":"Grown-ups know what they saw; only you know who you are inside.","persona":"be-yourself","source":"self-identification"},
  {"id":"wm-1049","cat":"sex-and-gender","type":"sort","hook":"Sort each reply when a friend tells you their gender: KIND or UNKIND.","items":[{"id":"a","text":"\"Thanks for telling me!\""},{"id":"b","text":"\"That's so weird.\""},{"id":"c","text":"\"You're still my friend.\""},{"id":"d","text":"\"Prove it.\""},{"id":"e","text":"\"I'll use your name.\""},{"id":"f","text":"\"You have to pick one.\""}],"bins":[{"id":"kind","label":"Kind","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"When a friend tells you who they are, believe them and use their name.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1050","cat":"sex-and-gender","type":"build","hook":"Lensy: build a 'how to meet someone new' plan, step by step.","prompt":"Put the kind steps in order.","pieces":["Say hello","Ask their name","Use the name they give","If you slip up, say sorry and retry"],"mode":"sequence","key":["Say hello","Ask their name","Use the name they give","If you slip up, say sorry and retry"],"relearn":"Say hi, ask their name, use it, and say sorry if you slip up.","persona":"respect","source":"respect / voice"},
  {"id":"wm-1051","cat":"sex-and-gender","type":"build","hook":"Lensy: build the 'sex' card. Pick only the pieces that belong to sex (the body).","prompt":"Gather what 'sex' is about.","pieces":["The body you're born with","The parts a doctor first saw","Who you know you are inside","Your favourite colour"],"mode":"assemble","key":["The body you're born with","The parts a doctor first saw"],"relearn":"Sex is about the body you're born with.","persona":"educator","source":"sex vs gender"},
  {"id":"wm-1052","cat":"sex-and-gender","type":"build","hook":"Lensy: build the 'gender' card. Pick only the pieces that belong to gender.","prompt":"Gather what 'gender' is about.","pieces":["Who you know you are inside","A feeling that's truly yours","The body you're born with","What a first glance sees"],"mode":"assemble","key":["Who you know you are inside","A feeling that's truly yours"],"relearn":"Gender is who you know you are inside.","persona":"gender thread","source":"sex vs gender"},
  {"id":"wm-1053","cat":"sex-and-gender","type":"build","hook":"Lensy: build a kit of true things to remember about who you are.","prompt":"Pick the true reminders for your kit.","pieces":["Only I know who I am inside","I never have to prove who I am","I must look a certain way to be me","You can tell my gender by my clothes"],"mode":"assemble","key":["Only I know who I am inside","I never have to prove who I am"],"relearn":"Only you know who you are inside, and you never have to prove it.","persona":"be-yourself","source":"self-knowledge"},
  {"id":"wm-1054","cat":"sex-and-gender","type":"build","hook":"Lensy: build the steps to be a kind ally when a friend is teased about their gender.","prompt":"Put the ally steps in order.","pieces":["Notice the teasing","Stand next to your friend","Say their real name kindly","Invite your friend to play"],"mode":"sequence","key":["Notice the teasing","Stand next to your friend","Say their real name kindly","Invite your friend to play"],"relearn":"Notice, stand with your friend, use their name, and include them.","persona":"ally seed","source":"respect / voice"},
  {"id":"wm-1055","cat":"sex-and-gender","type":"build","hook":"Lensy: build a 'me' reminder. Gender is one part: pick the true reminders.","prompt":"Pick the true pieces for your reminder.","pieces":["My gender is one part of me","Many parts make the whole me","My gender is the only thing about me","I must prove who I am"],"mode":"assemble","key":["My gender is one part of me","Many parts make the whole me"],"relearn":"Your gender is one part among many that make you.","persona":"any","source":"self-concept"},
  {"id":"wm-1056","cat":"sex-and-gender","type":"build","hook":"Lensy: build a plan for when you used the wrong name by mistake.","prompt":"Put the kind steps in order.","pieces":["Notice your mistake","Say sorry","Use the right name","Carry on playing together"],"mode":"sequence","key":["Notice your mistake","Say sorry","Use the right name","Carry on playing together"],"relearn":"Mistakes happen: notice, say sorry, use the right name, carry on.","persona":"respect","source":"respect"},
  {"id":"wm-1057","cat":"sex-and-gender","type":"build","hook":"Lensy: build the answer to 'what tells you someone's gender?' Pick only what's true.","prompt":"Pick the true pieces.","pieces":["What the person tells you","Letting them say it themselves","Their haircut","The clothes they wear"],"mode":"assemble","key":["What the person tells you","Letting them say it themselves"],"relearn":"Let people tell you their gender; looks don't reveal it.","persona":"gender thread","source":"gender vs expression"},
];

